  static const List<String> _p1 = [
    '«وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ ۝ وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ ۝ قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ۝ قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ ۝ وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ ۝ وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ ۝ فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ ۝ فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ۝ قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ۝ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ»',
    '«وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ» أَيْ نَعْبُدُكَ دَائِمًا لَا يَعْصِيكَ مِنَّا أَحَدٌ، فَإِنْ كَانَ الْمُرَادُ بِخَلْقِ هَؤُلَاءِ أَنْ يَعْبُدُوكَ فَهَا نَحْنُ لَا نَفْتُرُ لَيْلًا وَلَا نَهَارًا.',
    '«ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ».',
    'وَلِهَذَا قَالَ لَهُ مُوسَى الْكِلِيمُ حِينَ اجْتَمَعَ هُوَ وَإِيَّاهُ فِي الْمَلَأِ الْأَعْلَى وتناظر كَمَا سَيَأْتِي: أَنْتَ آدَمُ أَبُو الْبَشَرِ الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ، وَنَفَخَ فِيكَ مِنْ رُوحِهِ، وأسجد لَك مَلَائكَته، وعلمك أَسمَاء كل شئ.',
    'وَهَكَذَا يَقُولُ لَهُ أَهْلُ الْمَحْشَرِ يَوْمَ الْقِيَامَةِ كَمَا تَقَدَّمَ، وَكَمَا سَيَأْتِي إِنْ شَاءَ اللَّهُ تَعَالَى.',
    'وَقَالَ فِي الْآيَةِ الْأُخْرَى: «وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ ۝ قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ».',
    'ثمَّ هُوَ فَاسد فِي نَفسه، فَإِن الطين أَنْفَع وَخير من النَّار، لَان الطين فِيهِ الرزانة والحلم والاناة والنمو، وَالنَّار فِيهَا الطيش والخفة والسرعة والاحراق.',
    'فَأَخْبَرَ تَعَالَى أَنَّهُ خَاطَبَ الْمَلَائِكَةَ قَائِلًا لَهُم: «إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ» أَعْلَمَ بِمَا يُرِيدُ أَنْ يَخْلُقَ مِنْ آدَمَ وَذُرِّيَّتِهِ الَّذِينَ يُخْلِفُ بَعْضُهُمْ بَعْضًا كَمَا قَالَ: «وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ ٱلۡأَرۡضِ» وَقَالَ: «وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ» فَأَخْبَرَهُمْ بِذَلِكَ عَلَى سَبِيلِ التَّنْوِيهِ بِخَلْقِ آدَمَ وَذُرِّيَّتِهِ، كَمَا يُخْبِرُ بِالْأَمْرِ الْعَظِيمِ قَبْلَ كَوْنِهِ، فَقَالَتِ الْمَلَائِكَةُ سَائِلِينَ عَلَى وَجْهِ الِاسْتِكْشَافِ وَالِاسْتِعْلَامِ عَنْ وَجْهِ الْحِكْمَةِ لَا عَلَى وَجْهِ الِاعْتِرَاضِ وَالتَّنَقُّصِ لِبَنِي آدَمَ وَالْحَسَدِ لَهُمْ، كَمَا قَدْ يَتَوَهَّمُهُ بَعْضُ جَهَلَةِ الْمُفَسِّرِينَ، قَالُوا: «أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ».',
    '«قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ» أَيْ أَعْلَمُ مِنَ الْمَصْلَحَةِ الرَّاجِحَةِ فِي خَلْقِ هَؤُلَاءِ مَالا تعلمُونَ، أَيْ سَيُوجَدُ مِنْهُمُ الْأَنْبِيَاءُ وَالْمُرْسَلُونَ وَالصِّدِّيقُونَ وَالشُّهَدَاءُ والصالحون.',
    'ثُمَّ بَيَّنَ لَهُمْ شَرَفَ آدَمَ عَلَيْهِمْ فِي الْعلم فَقَالَ: «وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا».',
    'وَالصَّحِيحُ: أَنه علمه أَسمَاء الذورات وَأَفْعَالَهَا مُكَبَّرَهَا وَمُصَغَّرَهَا، كَمَا أَشَارَ إِلَيْهِ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا.',
    'قَالُوا: «سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ» أَي سُبْحَانَكَ أَن يُحِيط أحد بشئ مِنْ عِلْمِكَ مِنْ غَيْرِ تَعْلِيمِكَ، كَمَا قَالَ: «وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ». «قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ» أَيْ أَعْلَمُ السِّرَّ كَمَا أَعْلَمُ الْعَلَانِيَةَ.',
    'وَقَوله: «وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ» هَذَا إِكْرَامٌ عَظِيمٌ مِنَ اللَّهِ تَعَالَى لِآدَمَ حِينَ خَلَقَهُ بِيَدِهِ، وَنَفَخَ فِيهِ مِنْ رُوحِهِ، كَمَا قَالَ: «فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ» فَهَذِهِ أَرْبَعُ تَشْرِيفَاتٍ: خَلْقُهُ لَهُ بِيَدِهِ الْكَرِيمَةِ، ونفخه مِنْ رُوحِهِ، وَأَمْرُهُ الْمَلَائِكَةَ بِالسُّجُودِ لَهُ، وَتَعْلِيمُهُ أَسْمَاءَ الْأَشْيَاءِ.',
    '«فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ ۝ إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ ۝ قَالَ يَٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ ۝ قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ۝ قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ ۝ وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ»',
    'اسْتَحَقَّ هَذَا مِنَ اللَّهِ تَعَالَى لِأَنَّهُ اسْتَلْزَمَ تنقصه لآدَم وازدراءه بِهِ وَتَرَفُّعُهُ عَلَيْهِ مُخَالَفَةَ الْأَمْرِ الْإِلِهِيِّ، وَمُعَانَدَةَ الْحَقِّ فِي النَّصِّ عَلَى آدَمَ عَلَى التَّعْيِينِ.',
    'وَأَمَرَ اللَّهُ آدَمَ عَلَيْهِ السَّلَامُ أَنْ يَسْكُنَ هُوَ وَزَوْجَتُهُ الْجَنَّةَ فَقَالَ: «وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ».',
    'وَسِيَاق هَذِه الْآيَات يقتضى أَن خلق حَوَّاء كَانَ قبل دُخُول آدم إِلَى الْجنَّة لقَوْله: «وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ» وَهَذَا قد صرح بِهِ إِسْحَاق ابْن يَسَارٍ وَهُوَ ظَاهِرُ هَذِهِ الْآيَاتِ.',
    'وَقَالَ آخَرُونَ: بَلِ الْجَنَّةُ الَّتِي أُسْكِنَهَا آدَمُ لَمْ تَكُنْ جَنَّةَ الْخلد، لانه كلف فِيهَا أَلا يَأْكُلَ مِنْ تِلْكَ الشَّجَرَةِ، وَلِأَنَّهُ نَامَ فِيهَا وَأَخْرَجَ مِنْهَا، وَدَخَلَ عَلَيْهِ إِبْلِيسُ فِيهَا، وَهَذَا مِمَّا يُنَافِي أَنْ تَكُونَ جَنَّةَ الْمَأْوَى.',
    'وَقَالَ تَعَالَى:',
    '«وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ ۝ فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ ۝ إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ ۝ وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ»',
    'وَقَوْلُهُ: «فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ»',
    '«وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ ۝ قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ»',
    'وَهَذَا اعْتِرَافٌ وَرُجُوعٌ إِلَى الْإِنَابَةِ، وَتَذَلُّلٌ وَخُضُوعٌ وَاسْتِكَانَةٌ، وَافْتِقَارٌ إِلَيْهِ تَعَالَى فِي السَّاعَةِ الرَّاهِنَةِ، وَهَذَا السِّرُّ مَا سَرَى فِي أَحَدٍ مِنْ ذُرِّيَّتِهِ إِلَّا كَانَتْ عَاقِبَتُهُ إِلَى خَيْرٍ فِي دُنْيَاهُ وَأُخْرَاهُ.',
    '«قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ» وَهَذَا خِطَابٌ لِآدَمَ وَحَوَّاءَ وَإِبْلِيسَ، قِيلَ وَالْحَيَّةُ مَعَهم، أمروا أَن يهطبوا مِنَ الْجَنَّةِ فِي حَالِ كَوْنِهِمْ مُتَعَادِينَ مُتَحَارِبِينَ.',
    '«فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ۝ قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ۝ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ»',
    'وَقَالَ تَعَالَى:',
    '«وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ ۝ ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ»',
  ];

  static const List<String> _p2 = [
    'قَالَ اللَّهُ تَعَالَى: «وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا ۝ وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا» فَإِدْرِيسُ عَلَيْهِ السَّلَامُ قَدْ أَثْنَى اللَّهُ عَلَيْهِ وَوَصَفَهُ بِالنُّبُوَّةِ وَالصِّدِّيقِيَّةِ، وَهُوَ خَنُوخُ هَذَا.',
    'وَهُوَ فِي عَمُودِ نَسَبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مَا ذَكَرَهُ غَيْرُ وَاحِدٍ مِنْ عُلَمَاءِ النَّسَبِ. وَكَانَ أَوَّلَ بَنِي آدَمَ أَعْطِيَ النُّبُوَّةَ بَعْدَ آدَمَ وَشِيثَ عَلَيْهِمَا السَّلَامُ.',
    'وَقَوْلُهُ تَعَالَى: «وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا» هُوَ كَمَا ثَبَتَ فِي الصَّحِيحَيْنِ فِي حَدِيثِ الْإِسْرَاءِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِهِ وَهُوَ فِي السَّمَاءِ الرَّابِعَةِ.',
    'وَالْحَدِيثُ الْمُتَّفَقُ عَلَيْهِ مِنْ أَنَّهُ فِي السَّمَاءِ الرَّابِعَةِ أَصَحُّ، وَهُوَ قَوْلُ مُجَاهِدٍ وَغَيْرُ وَاحِدٍ.',
  ];

  static const List<String> _p8 = [
    '«وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا ۝ وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا»',
    'فَذَكَرَ اللَّهُ عَنْهُ كُلَّ صِفَةٍ جَمِيلَةٍ، وَجَعَلَهُ نَبِيَّهُ وَرَسُولَهُ، وَبَرَّأَهُ مِنْ كُلِّ مَا نَسَبَ إِلَيْهِ الْجَاهِلُونَ، وَأَمَرَ بِأَنْ يُؤْمِنَ بِمَا أُنْزِلَ عَلَيْهِ عِبَادُهُ الْمُؤْمِنُونَ.',
    'وَكَانَ إِسْمَاعِيلُ عَلَيْهِ السَّلَامُ رَسُولًا إِلَى أَهْلِ تِلْكَ النَّاحِيَة وَمَا والاها ; من قبائل جزهم وَالْعَمَالِيقِ وَأَهْلِ الْيَمَنِ، صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِ.',
    'وَدفن نبى الله إِسْمَاعِيلُ نَبِيُّ اللَّهِ بِالْحِجْرِ مَعَ أُمِّهِ هَاجَرَ، وَكَانَ عُمُرُهُ يَوْمَ مَاتَ مِائَةً وَسَبْعًا وَثَلَاثِينَ سَنَةً. وَعَرَبُ الْحِجَازِ كلهم ينتسبون إِلَى ولديه: نابت، وقيذار.',
  ];

  static const List<String> _p10 = [
    'قَالَ اللَّهُ تَعَالَى:',
    '«وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ ۝ وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ ۝ وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ»',
    '«وَمَن يَرۡغَبُ عَن مِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ ۝ إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ ۝ وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ۝ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ۝ تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ ۝ وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ۝ قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ۝ فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ۝ صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ ۝ قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ ۝ أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ۝ تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ»',
    'فنزه الله عزوجل خَلِيلَهُ عَلَيْهِ السَّلَامُ عَنْ أَنْ يَكُونَ يَهُودِيًّا أَوْ نَصْرَانِيًّا، وَبَيَّنَ أَنَّهُ إِنَّمَا كَانَ حَنِيفًا مُسْلِمًا وَلَمْ يَكُنْ مِنَ الْمُشْرِكِينَ.',
    'وَلِهَذَا قَالَ تَعَالَى: «إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ» يَعْنِي الَّذِينَ كَانُوا عَلَى مِلَّتِهِ مِنْ أَتْبَاعِهِ فِي زَمَانِهِ، وَمَنْ تَمَسَّكَ بِدِينِهِ مِنْ بَعْدِهِمْ.',
    '«وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ ۝ إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةٖ ذِكۡرَى ٱلدَّارِ ۝ وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَيۡنَ ٱلۡأَخۡيَارِ ۝ وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ»',
    'فَالظَّاهِرُ مِنْ ذِكْرِهِ فِي الْقُرْآنِ الْعَظِيمِ بِالثَّنَاءِ عَلَيْهِ مَقْرُونًا مَعَ هَؤُلَاءِ السَّادَةِ الْأَنْبِيَاءِ أَنَّهُ نبى، على مِنْ رَبِّهِ الصَّلَاةُ وَالسَّلَامُ.',
    '«إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ ۝ قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ۝ وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ»',
    'وَلِهَذَا جَاءَ فِي بَعْضِ الْآثَارِ: “اسْتَعِينُوا عَلَى قَضَاءِ حَوَائِجِكُمْ بِكِتْمَانِهَا، فَإِن كَانَ ذِي نِعْمَةٍ مَحْسُودٌ”.',
    '«كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ» أَيْ يُنْعِمُ عَلَيْكَ وَيُحْسِنُ إِلَيْكَ بِالنُّبُوَّةِ، كَمَا أَعْطَاهَا أَبَاك يَعْقُوب، وَجدك إِسْحَق، وَوَالِدَ جَدِّكَ إِبْرَاهِيمَ الْخَلِيلَ، «إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ» كَمَا قَالَ تَعَالَى: «ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ».',
    '«قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ»',
    'وَلِهَذَا «قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ».',
    'فَلَمَّا جَاءَ روبيل آخِرِ النَّهَارِ لِيُخْرِجَ يُوسُفَ لَمْ يَجِدْهُ، فَصَاحَ وشق ثِيَابه، وَعَمَدَ أُولَئِكَ إِلَى جَدْيٍ فَذَبَحُوهُ، وَلَطَّخُوا مِنْ دَمِهِ جُبَّةَ يُوسُفَ، فَلَمَّا عَلِمَ يَعْقُوبُ شَقَّ ثِيَابَهُ، وَلَبِسَ مِئْزَرًا أَسْوَدَ وَحَزِنَ عَلَى ابْنِهِ أَيَّامًا كَثِيرَةً.',
    '«قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ۝ وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ ۝ قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ ۝ قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝ يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ»',
    '“فَهُوَ كظيم” أَي مكظم مِنْ كَثْرَةِ حُزْنِهِ وَأَسَفِهِ وَشَوْقِهِ إِلَى يُوسُفَ.',
    'فَلَمَّا رأى بنوه مَا يقاسيه من الوجد وَأَلَمِ الْفِرَاقِ “قَالُوا” لَهُ عَلَى وَجْهِ الرَّحْمَةِ لَهُ والرأفة بِهِ والحرص عَلَيْهِ «تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ».',
    'يَقُولُونَ: لَا تَزَالُ تَتَذَكَّرُهُ حَتَّى يَنْحَلَ جَسَدُكَ وَتَضْعُفَ قُوَّتُكَ، فَلَوْ رَفَقْتَ بِنَفْسِكَ كَانَ أَوْلَى بِكَ.',
    '«قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ»',
    'يَقُولُ لِبَنِيهِ: لَسْتُ أَشْكُو إِلَيْكُمْ وَلَا إِلَى أَحَدٍ مِنَ النَّاسِ مَا أَنَا فِيهِ، إِنَّمَا أشكوه إِلَى اللَّهِ عَزَّ وَجَلَّ، وَأَعْلَمُ أَنَّ اللَّهَ سَيَجْعَلُ لِي مِمَّا أَنَا فِيهِ فَرَجًا وَمَخْرَجًا، وَأعلم أَن رُؤْيا يُوسُف لابد أَن تقع، ولابد أَنْ أَسْجُدَ لَهُ أَنَا وَأَنْتُمْ حَسَبَ مَا رأى.',
    '«فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ۝ قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ۝ وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَٰٓأَبَانَا مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرٖۖ ذَٰلِكَ كَيۡلٞ يَسِيرٞ ۝ قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ ۝ وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ۝ وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ»',
    '«وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ ۝ قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ ۝ فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝ قَالُواْ يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ ۝ قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ»',
    'فَأَجَابَهُمْ أَبُوهُمْ إِلَى مَا سَأَلُوا، وَمَا عَلَيْهِ عَوَّلُوا قَائِلًا: «سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ».',
    'وَثَبَتَ فِي الصَّحِيحَيْنِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنه قَالَ: “يَنْزِلُ رَبُّنَا كُلَّ لَيْلَةٍ إِلَى سَمَاءِ الدُّنْيَا فَيَقُولُ: هَلْ مِنْ تَائِبٍ فَأَتُوبَ عَلَيْهِ؟ هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ؟ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ؟”.',
  ];

  static const List<String> _p13 = [
    'كَانَ أَهْلُ مَدْيَنَ قَوْمًا عَرَبًا يَسْكُنُونَ مَدِينَتَهُمْ “مَدين” الَّتِى هِيَ قريبَة مِنْ أَرْضِ مُعَانٍ مِنْ أَطْرَافِ الشَّامِ، مِمَّا يَلِي نَاحيَة الْحجاز قَرِيبا',
    'وَكَانَ أَهْلُ مَدْيَنَ كُفَّارًا يَقْطَعُونَ السَّبِيلَ وَيُخِيفُونَ الْمَارَّةَ، وَيَعْبُدُونَ الْأَيْكَةَ، وَهِيَ شَجَرَةٌ مِنَ الْأَيْكِ حَوْلَهَا غَيْضَةٌ ملتفة بهَا. وَكَانُوا من أسوإ النَّاسِ مُعَامَلَةً ; يَبْخَسُونَ الْمِكْيَالَ وَالْمِيزَانَ، وَيُطَفِّفُونَ فِيهِمَا، يَأْخُذُونَ بِالزَّائِدِ ويدفعون بالناقس. فَبَعَثَ اللَّهُ فِيهِمْ رَجُلًا مِنْهُمْ وَهُوَ رَسُولُ اللَّهِ شُعَيْبٌ عَلَيْهِ السَّلَامُ فَدَعَاهُمْ إِلَى عِبَادَةِ اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ، وَنَهَاهُمْ عَنْ تَعَاطِي هَذِهِ الْأَفَاعِيلِ الْقَبِيحَةِ مِنْ بَخْسِ النَّاسِ أَشْيَاءَهُمْ وَإِخَافَتِهِمْ لَهُمْ فِي سُبُلِهِمْ وَطُرُقَاتِهِمْ، فَآمَنَ بِهِ بَعْضُهُمْ وَكَفَرَ أَكْثَرُهُمْ، حَتَّى أَحَلَّ اللَّهُ بهم الْبَأْس الشَّديد.',
    'قَالَ اللَّهُ تَعَالَى فِي سُورَةِ الْأَعْرَافِ:',
    '«وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ۝ وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ۝ وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ۝ ۞ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ ۝ قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ ۝ وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ ۝ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ۝ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ ۝ فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ»',
    'وَقَالَ فِي سُورَةِ هُودٍ:',
    '«وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ ۝ وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ۝ بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ ۝ قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ ۝ قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ۝ وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ ۝ وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ ۝ قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ ۝ قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ ۝ وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ ۝ وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ۝ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ ۝ وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ»',
    'أَمَرَهُمْ بِالْعَدْلِ وَنَهَاهُمْ عَنِ الظُّلْمِ، وَتَوَعَّدَهُمْ عَلَى خِلَافِ ذَلِكَ فَقَالَ: «ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ۝ وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ» أَيْ طَرِيقٍ “تُوعِدُونَ” أَيْ تَتَوَعَّدُونَ النَّاسَ بِأَخْذِ أَمْوَالِهِمْ مِنْ مُكُوسٍ',
    'هَذَا تَلَطُّفٌ مَعَهُمْ فِي الْعِبَارَةِ، وَدَعْوَةٌ لَهُمْ إِلَى الْحَقِّ بِأَبْيَنِ إِشَارَةٍ.',
    'أَنَّهُمْ أَصَابَهُمْ حَرٌّ شَدِيدٌ، وَأَسْكَنَ اللَّهُ هُبُوبَ الْهَوَاءِ عَنْهُمْ سَبْعَةَ أَيَّامٍ، فَكَانَ لَا يَنْفَعُهُمْ مَعَ ذَلِكَ مَاءٌ وَلَا ظِلٌّ، وَلَا دُخُولُهُمْ فِي الْأَسْرَابِ، فَهَرَبُوا مِنْ مَحَلَّتِهِمْ إِلَى الْبَرِّيَّةِ، فأظلتهم سَحَابَة، فَاجْتمعُوا تحتهَا ليستظطلوا بظلها، فَلَمَّا تكاملوا فِيهِ أرسلها الله ترميهم بشرر وشهب، وَرَجَفَتْ بِهِمُ الْأَرْضُ، وَجَاءَتْهُمْ صَيْحَةٌ مِنَ السَّمَاءِ، فَأَزْهَقَتِ الْأَرْوَاحَ، وَخَرَّبَتِ الْأَشْبَاحَ. «فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ۝ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ» وَنَجَّى اللَّهُ شُعَيْبًا وَمَنْ مَعَهُ مِنَ الْمُؤْمِنِينَ، كَا قَالَ تَعَالَى وَهُوَ أَصْدَقُ الْقَائِلِينَ: «وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ۝ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ» وَقَالَ تَعَالَى: «وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ ۝ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ۝ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ» وَهَذَا فِي مُقَابَلَةِ قَوْلِهِمْ: «لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ».',
    'ثُمَّ ذَكَرَ تَعَالَى عَنْ نَبِيِّهِمْ: أَنَّهُ نَعَاهُمْ إِلَى أَنْفُسِهِمْ مُوَبِّخًا وَمُؤَنِّبًا وَمُقَرِّعًا، فَقَالَ تَعَالَى: «فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ». أَيْ أَعْرَضَ عَنْهُمْ مُوَلِّيًا عَنْ مَحَلَّتِهِمْ بَعْدَ هلكتهم قَائِلًا: «وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ».',
    'أَي قد أدّيت مَا كَانَ وَاجِبًا عَلَيَّ مِنَ الْبَلَاغِ التَّامِّ وَالنُّصْحِ الْكَامِلِ، وَحَرَصْتُ عَلَى هِدَايَتِكُمْ بِكُلِّ مَا أَقْدِرُ عَلَيْهِ وَأَتَوَصَّلُ إِلَيْهِ، فَلَمْ يَنْفَعْكُمْ ذَلِكَ، لِأَنَّ اللَّهَ لَا يهدى من يضل ومالهم مِنْ نَاصِرِينَ. فَلَسْتُ أَتَأَسَّفُ بَعْدَ هَذَا عَلَيْكُمْ، لِأَنَّكُمْ لَمْ تَكُونُوا تَقْبَلُونَ النَّصِيحَةَ، وَلَا تَخَافُونَ يَوْم الفضيحة. وَلِهَذَا قَالَ: “فَكيف آسى” أَي أَحْزَن «عَلَىٰ قَوۡمٖ كَٰفِرِينَ» أَي لَا يقبلُونَ الْحق وَلَا يرجعُونَ إِلَيْهِ وَلَا يلتفتون إِلَيْهِ فَحَلَّ بِهِمْ مِنْ بَأْسِ اللَّهِ الَّذِي لَا يرد مَا لَا يدْفع وَلَا يُمَانَعُ، وَلَا مَحِيدَ لِأَحَدٍ أُرِيدَ بِهِ عَنهُ، وَلَا مناص عَنهُ.',
  ];

  static const List<String> _p15 = [
    'ثُمَّ قَالَ مُوسَى عَلَيْهِ السَّلَامُ: «وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ۝ هَٰرُونَ أَخِي ۝ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ۝ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ۝ كَيۡ نُسَبِّحَكَ كَثِيرٗا ۝ وَنَذۡكُرَكَ كَثِيرًا ۝ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ۝ قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ» أَيْ قَدْ أَجَبْنَاكَ إِلَى جَمِيعِ مَا سَأَلْتَ، وَأَعْطَيْنَاكَ الَّذِي طَلَبْتَ. وَهَذَا مِنْ وَجَاهَتِهِ عِنْدَ ربه عزوجل، حِينَ شَفَعَ أَنْ يُوحِيَ اللَّهُ إِلَى أَخِيهِ فَأَوْحَى إِلَيْهِ. وَهَذَا جَاهٌ عَظِيمٌ، قَالَ اللَّهُ تَعَالَى: «وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا».',
    '«وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا»',
    'وَقَدْ سَمِعَتْ أُمُّ الْمُؤْمِنِينَ عَائِشَةُ رَجُلًا يَقُولُ لاناس وهم سائرون فِي طَرِيقِ الْحَجِّ: أَيُّ أَخٍ أَمَنُّ عَلَى أَخِيهِ؟ فَسَكَتَ الْقَوْمُ، فَقَالَتْ عَائِشَةُ لِمَنْ حَوْلَ هَوْدَجِهَا: هُوَ مُوسَى بْنُ عِمْرَانَ حِينَ شَفَعَ فِي أَخِيه هرون فَأوحى إِلَيْهِ.',
    'قَالَ الله تَعَالَى: «وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ» أَيْ إِنَّمَا قَدَّرَ اللَّهُ أَمَرَ هَذَا الْعِجْلِ وَجَعَلَهُ يَخُورُ فِتْنَةً وَاخْتِبَارًا لَكُمْ، «وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ» أَي لَا هَذَا “فَاتبعُوني” أَيْ فِيمَا أَقُولُ لَكُمْ «وَأَطِيعُوٓاْ أَمۡرِي ۝ قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ» يشْهد الله لهرون عَلَيْهِ السَّلَامُ «وَكَفَىٰ بِٱللَّهِ شَهِيدٗا» أَنَّهُ نَهَاهُمْ وَزَجَرَهُمْ عَنْ ذَلِكَ فَلَمْ يُطِيعُوهُ وَلَمْ يَتَّبِعُوهُ.',
  ];

  static const List<String> _p16 = [
    'قَالَ اللَّهُ تَعَالَى بَعْدَ قِصَّةِ أَيُّوبَ فِي سُورَةِ الْأَنْبِيَاءِ: «وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّٰبِرِينَ ۝ وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ».',
    'فَالظَّاهِرُ مِنْ ذِكْرِهِ فِي الْقُرْآنِ الْعَظِيمِ بِالثَّنَاءِ عَلَيْهِ مَقْرُونًا مَعَ هَؤُلَاءِ السَّادَةِ الْأَنْبِيَاءِ أَنَّهُ نبى، على مِنْ رَبِّهِ الصَّلَاةُ وَالسَّلَامُ. وَهَذَا هُوَ الْمَشْهُورُ.',
    'وَقَدْ زَعَمَ آخَرُونَ أَنَّهُ لَمْ يَكُنْ نَبِيًّا، وَإِنَّمَا كَانَ رَجُلًا صَالِحًا وَحَكَمًا مُقْسِطًا عَادِلًا. وَتَوَقَّفَ ابْنُ جَرِيرٍ فِي ذَلِكَ، فَاللَّهُ أَعْلَمُ. وروى ابْن جرير وَأَبُو نَجِيحٍ عَنْ مُجَاهِدٍ: أَنَّهُ لَمْ يَكُنْ نَبِيًّا وَإِنَّمَا كَانَ رَجُلًا صَالِحًا. وَكَانَ قَدْ تَكَفَّلَ لبنى قومه أَن يكفيهم أَمرهم، وَيقْضى بَينهم بِالْعَدْلِ فَفعل فَسمى ذاالكفل.',
  ];

  static const List<String> _p17 = [
    'قَالَ اللَّهُ تَعَالَى:',
    '«وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ ۝ أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ» وَقَالَ تَعَالَى: «وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ ۝ وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ»',
    'وَقَدْ ثَبَتَ فِي الْحَدِيثِ أَنَّ أَطْيَبَ مَا أَكَلَ الرَّجُلُ مِنْ كَسْبِهِ وَإِنَّ نَبِيَّ اللَّهِ دَاوُدَ كَانَ يَأْكُلُ مِنْ كَسْبِ يَدِهِ.',
