    'يَعْنِي ذَا قُوَّةٍ فِي الْعِبَادَةِ وَالْعَمَلِ الصَّالِحِ.',
    'وَقَدْ ثَبَتَ فِي الصَّحِيحَيْنِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: “أَحَبُّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ دَاوُدَ وَأَحَبُّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ دَاوُدَ كَانَ يَنَامُ نِصْفَ اللَّيْلِ وَيَقُومُ ثُلُثَهُ وَيَنَامُ سُدُسَهُ، وَكَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا وَلَا يَفِرُّ إِذَا لَاقَى”.',
    'قَالَهُ ابْنُ عَبَّاسٍ وَمُجَاهِدٌ وَغَيْرُ وَاحِدٍ فِي تَفْسِيرِ هَذِهِ الْآيَةِ «إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ» أَيْ عِنْدَ آخَرِ النَّهَارِ وَأَوَّلِهِ، وَذَلِكَ أَنَّهُ كَانَ اللَّهُ تَعَالَى قَدْ وَهَبَهُ مِنَ الصَّوْتِ الْعَظِيم مَا لم يُعْطه أحد بِحَيْثُ إِنَّهُ كَانَ إِذَا تَرَنَّمَ بِقِرَاءَةِ كِتَابِهِ يَقِفُ الطَّيْرُ فِي الْهَوَاءِ يُرَجِّعُ بِتَرْجِيعِهِ وَيُسَبَّحُ بتسبيحه وَكَذَلِكَ الْجِبَالُ تُجِيبُهُ وَتُسَبِّحُ مَعَهُ كُلَّمَا سَبَّحَ بُكْرَةً وَعَشِيًّا، صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِ.',
    'وَقَوله: «وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ» أَيْ أَعْطَيْنَاهُ مُلْكًا عَظِيمًا وَحُكْمًا نَافِذًا.',
    '«وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ ٱلۡمِحۡرَابَ ۝ إِذۡ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُواْ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضٖ فَٱحۡكُم بَيۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ ۝ إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعٞ وَتِسۡعُونَ نَعۡجَةٗ وَلِيَ نَعۡجَةٞ وَٰحِدَةٞ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ ۝ قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ۝ فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ»',
    'تَرَكْنَا إِيرَادَهَا فِي كِتَابِنَا قَصْدًا اكْتِفَاءً وَاقْتِصَارًا عَلَى مُجَرَّدِ تِلَاوَةِ الْقِصَّةِ مِنَ الْقُرْآنِ الْعَظِيمِ، وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ.',
  ];

  static const List<String> _p18 = [
    'قَالَ اللَّهُ تَعَالَى:',
    '«وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ» أَيْ وَرِثَهُ فِي النُّبُوَّةِ وَالْمُلْكِ، وَلَيْسَ الْمُرَادُ وَرثهُ فِي الْمَالِ، لِأَنَّهُ قَدْ كَانَ لَهُ بَنُونَ غَيْرُهُ، فَمَا كَانَ لِيُخَصَّ بِالْمَالِ دُونَهُمْ، وَلِأَنَّهُ قَدْ ثَبَتَ فِي الصِّحَاحِ مِنْ غَيْرِ وَجْهٍ عَنْ جَمَاعَةٍ مِنَ الصَّحَابَةِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا نُورَثُ مَا تَرَكْنَا فَهُوَ صَدَقَةٌ وَفِي لَفْظَة: نَحن مَعَاشِرَ الْأَنْبِيَاءِ لَا نُورَثُ فَأَخْبَرَ الصَّادِقُ الْمَصْدُوقُ أَنَّ الْأَنْبِيَاءَ لَا تُورَثُ أَمْوَالُهُمْ عَنْهُمْ كَمَا يُورَثُ غَيْرُهُمْ، بَلْ تَكُونُ أَمْوَالُهُمْ صَدَقَةً مِنْ بَعْدِهِمْ عَلَى الْفُقَرَاءِ وَالْمَحَاوِيجِ لَا يَخُصُّونَ بِهَا أقرباؤهم، لِأَنَّ الدُّنْيَا كَانَتْ أَهْوَنَ عَلَيْهِمْ وَأَحْقَرَ عِنْدَهُمْ مِنْ ذَلِكَ كَمَا هِيَ عِنْدَ الَّذِي أَرْسَلَهُمْ وَاصْطَفَاهُمْ وَفَضَّلَهُمْ. وَقَالَ: «وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ» يَعْنِي أَنَّهُ عَلَيْهِ السَّلَامُ كَانَ يَعْرِفُ مَا يتخاطب بِهِ الطُّيُورُ بِلُغَاتِهَا وَيُعَبِّرُ لِلنَّاسِ عَنْ مَقَاصِدِهَا وإرادتها',
    'يُخْبِرُ تَعَالَى عَنْ عَبْدِهِ وَنَبِيِّهِ وَابْنِ نَبِيِّهِ سُلَيْمَانَ بْنِ دَاوُدَ عَلَيْهِمَا الصَّلَاةُ وَالسَّلَامُ أَنَّهُ رَكِبَ يَوْمًا فِي جَيْشِهِ جَمِيعِهِ مِنَ الْجِنِّ وَالْإِنْسِ وَالطَّيْرِ، فَالْجِنُّ وَالْإِنْسُ يَسِيرُونَ مَعَهُ وَالطَّيْرُ سَائِرَةٌ مَعَهُ تُظِلُّهُ بِأَجْنِحَتِهَا مِنَ الْحَرِّ وَغَيْرِهِ وَعَلَى كُلٍّ مِنْ هَذِهِ الْجُيُوشِ الثَّلَاثَةِ وَزَعَةٌ أَيْ نُقَبَاءُ يَرُدُّونَ أَوَّلَهُ عَلَى آخِرِهِ، فَلَا يَتَقَدَّمُ أَحَدٌ عَنْ مَوْضِعِهِ الَّذِي يَسِيرُ فِيهِ وَلَا يَتَأَخَّرُ عَنْهُ قَالَ اللَّهُ تَعَالَى «حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ» فَأَمَرَتْ وَحَذَّرَتْ وَاعْتَذَرَتْ عَنْ سُلَيْمَانَ وَجُنُودِهِ بِعَدَمِ الشُّعُورِ.',
    'وَالْمَقْصُودُ أَنَّ سُلَيْمَانَ عَلَيْهِ السَّلَامُ فَهِمَ مَا خَاطَبَتْ بِهِ تِلْكَ النَّمْلَةُ لِأُمَّتِهَا مِنَ الرَّأْيِ السَّدِيدِ وَالْأَمْرِ الْحَمِيدِ وَتَبَسَّمَ مِنْ ذَلِكَ عَلَى وَجْهِ الِاسْتِبْشَارِ وَالْفَرَحِ وَالسُّرُورِ بِمَا أَطْلَعَهُ اللَّهُ عَلَيْهِ دُونَ غَيْرِهِ، وَلَيْسَ كَمَا يَقُولُهُ بَعْضُ الجهلة من',
    '«وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَالِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ ۝ لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ۝ فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ ۝ إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ ۝ وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ ۝ أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ ۝ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩ ۝ ۞ قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ ۝ ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ ۝ قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبٞ كَرِيمٌ ۝ إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ۝ أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ ۝ قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ ۝ قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ ۝ قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةٗۚ وَكَذَٰلِكَ يَفۡعَلُونَ ۝ وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ۝ فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ ۝ ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم بِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةٗ وَهُمۡ صَٰغِرُونَ»',
    'فَلَمَّا تَطَلَّبَهُ سُلَيْمَانُ عَلَيْهِ السَّلَامُ ذَاتَ يَوْمٍ فَقَدَهُ وَلَمْ يَجِدْهُ فِي مَوْضِعه من مَحل',
    'وَقَدْ ثَبَتَ فِي صَحِيحِ الْبُخَارِيِّ مِنْ حَدِيثِ عَوْفٍ، عَنِ الْحَسَنِ، عَنْ أَبِي بَكْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا بَلَّغَهُ أَنَّ أَهْلَ فَارِسَ مَلَّكُوا عَلَيْهِمُ ابْنَةَ كِسْرَى قَالَ: “لَنْ يُفْلِحَ قَوْمٌ وَلَّوْا أَمْرَهُمُ امْرَأَةً”.',
    'وَقَوْلُهُ: «وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ» أَيْ مِمَّا مِنْ شَأْنِهِ أَنْ تُؤْتَاهُ الْمُلُوكُ «وَلَهَا عَرۡشٌ عَظِيمٞ» يَعْنِي سَرِيرَ مَمْلَكَتِهَا كَانَ مُزَخْرَفًا بِأَنْوَاعِ الْجَوَاهِرِ واللآلئ وَالذَّهَب والحلى الباهر.',
    'ثُمَّ ذَكَرَ كُفْرَهُمْ بِاللَّهِ وَعِبَادَتَهُمُ الشَّمْسَ مِنْ دُونِ اللَّهِ وَإِضْلَالَ الشَّيْطَانِ لَهُمْ وَصَدَّهُ إِيَّاهُمْ عَن عِبَادَةِ اللَّهِ تَعَالَى وَحْدَهُ لَا شَرِيكَ لَهُ، الَّذِي يخرج الخبء فِي السَّمَوَات والارض وَيعلم مَا يخفون وَمَا يعلنون، أَيْ يَعْلَمُ السَّرَائِرَ وَالظَّوَاهِرَ مِنَ الْمَحْسُوسَاتِ وَالْمَعْنَوِيَّاتِ «ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩» أَيْ لَهُ الْعَرْشُ الْعَظِيمُ الَّذِي لَا أَعْظَمَ مِنْهُ فِي الْمَخْلُوقَاتِ.',
    'يَذْكُرُ تَعَالَى مَا كَانَ مِنْ أَمْرِ سُلَيْمَانَ وَالْهُدْهُدِ، وَذَلِكَ أَنَّ الطُّيُورَ كَانَ عَلَى كُلِّ صنف مِنْهَا مقدمون يقدمُونَ بِمَا يُطْلَبُ مِنْهُمْ وَيَحْضُرُونَ عِنْدَهُ بِالنَّوْبَةِ كَمَا هِيَ عَادَةُ الْجُنُودِ مَعَ الْمُلُوكِ، وَكَانَتْ وَظِيفَةُ الْهُدْهُدِ عَلَى مَا ذَكَرَهُ ابْنُ عَبَّاسٍ وَغَيْرُهُ أَنَّهُمْ كَانُوا إِذَا أَعْوَزُوا الْمَاءَ فِي الْقِفَارِ فِي حَال الاسفار يجِئ فَيَنْظُرُ لَهُمْ هَلْ بِهَذِهِ الْبِقَاعِ مِنْ مَاءٍ، وَفِيهِ مِنَ الْقُوَّةِ الَّتِي أَوْدَعَهَا اللَّهُ تَعَالَى فِيهِ أَنْ يَنْظُرَ إِلَى الْمَاءِ تَحْتَ تُخُومِ الْأَرْضِ، فَإِذَا دَلَّهُمْ عَلَيْهِ حَفَرُوا عَنْهُ وَاسْتَنْبَطُوهُ وَأَخْرَجُوهُ وَاسْتَعْمَلُوهُ لِحَاجَتِهِمْ. فَلَمَّا تَطَلَّبَهُ سُلَيْمَانُ عَلَيْهِ السَّلَامُ ذَاتَ يَوْمٍ فَقَدَهُ وَلَمْ يَجِدْهُ فِي مَوْضِعه من مَحل',
    '«قَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ ۝ قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ ۝ قَالَ نَكِّرُواْ لَهَا عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِيٓ أَمۡ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهۡتَدُونَ ۝ فَلَمَّا جَآءَتۡ قِيلَ أَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِينَ ۝ وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمٖ كَٰفِرِينَ»',
    '«فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ» أَيْ فَلَمَّا رَأَى عَرْشَ بَلْقِيسَ مُسْتَقِرًّا عِنْدَهُ فِي هَذِهِ الْمُدَّةِ الْقَرِيبَةِ مِنْ بِلَادِ الْيَمَنِ إِلَى بَيْتِ الْمَقْدِسِ فِي طَرْفَةِ عَيْنٍ «قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ» أَيْ هَذَا مِنْ فَضْلِ اللَّهِ عَلَيَّ وَفَضْلِهِ عَلَى عَبِيدِهِ لِيَخْتَبِرَهُمْ عَلَى الشُّكْرِ أَوْ خِلَافِهِ «وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ» أَيْ إِنَّمَا يَعُودُ نَفْعُ ذَلِكَ عَلَيْهِ «وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ» أَيْ غَنِيٌّ عَنْ شُكْرِ الشَّاكِرِينَ وَلَا يَتَضَرَّرُ بِكُفْرِ الْكَافِرِينَ.',
    '«فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ» أَيْ فَلَمَّا رَأَى عَرْشَ بَلْقِيسَ مُسْتَقِرًّا عِنْدَهُ فِي هَذِهِ الْمُدَّةِ الْقَرِيبَةِ مِنْ بِلَادِ الْيَمَنِ إِلَى بَيْتِ الْمَقْدِسِ فِي طَرْفَةِ عَيْنٍ «قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ» أَيْ هَذَا مِنْ فَضْلِ اللَّهِ عَلَيَّ وَفَضْلِهِ عَلَى عَبِيدِهِ لِيَخْتَبِرَهُمْ عَلَى الشُّكْرِ أَوْ خِلَافِهِ «وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ» أَيْ إِنَّمَا يَعُودُ نَفْعُ ذَلِكَ عَلَيْهِ «وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ» أَيْ غَنِيٌّ عَنْ شُكْرِ الشَّاكِرِينَ وَلَا يَتَضَرَّرُ بِكُفْرِ الْكَافِرِينَ.',
    '«وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ ۝ إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ ۝ فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ ۝ رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ ۝ وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدٗا ثُمَّ أَنَابَ ۝ قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ۝ فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ ۝ وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٖ وَغَوَّاصٖ ۝ وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ ۝ هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ ۝ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ»',
    'ثُمَّ ذَكَرَ تَعَالَى مَا كَانَ مِنْ أَمْرِهِ فِي الْخَيْلِ الصَّافِنَاتِ وَهِيَ الَّتِي تَقِفُ عَلَى ثَلَاثٍ وَطَرَفِ حَافِرِ الرَّابِعَةِ، الْجِيَادِ وَهِيَ الْمُضَمَّرَةُ السِّرَاعُ.',
    'فَقَالَ: «إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ» يَعْنِي الشَّمْسَ.',
    'قَالَ بَعْضُ الْعُلَمَاءِ لَمَّا تَرَكَ الْخَيْلَ لِلَّهِ عَوَّضَهُ اللَّهُ عَنْهَا بِمَا هُوَ خَيْرٌ لَهُ مِنْهَا، وَهُوَ الرّيح الَّتِي كَانَت غدوها شهر ورواحها شهر، كَمَا سَيَأْتِي الْكَلَامُ عَلَيْهَا.',
    'وَمَضْمُونُ مَا ذَكَرُوهُ أَنَّ سُلَيْمَانَ عَلَيْهِ السَّلَامُ غَابَ عَنْ سَرِيرِهِ أَرْبَعِينَ يَوْمًا ثُمَّ عَادَ إِلَيْهِ، وَلَمَّا عَادَ أَمَرَ بِبِنَاءِ بَيْتِ الْمَقْدِسِ فَبَنَاهُ بِنَاءً مُحْكَمًا.',
    'يَذْكُرُ تَعَالَى أَنَّهُ وَهَبَ لِدَاوُدَ سُلَيْمَانَ عَلَيْهِمَا السَّلَامُ، ثُمَّ أَثْنَى اللَّهُ تَعَالَى عَلَيْهِ فَقَالَ: «نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ» أَيْ رَجَّاعٌ مُطِيعٌ لِلَّهِ.',
    'وَقَرِيبٌ مِنْ هَذَا مَا ثَبَتَ فِي الصَّحِيحَيْنِ مِنْ حَدِيثِ أَبِي الزِّنَادِ، عَنِ الْأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: “بَيْنَمَا امْرَأَتَانِ مَعَهُمَا ابْنَاهُمَا إِذْ عَدَا الذِّئْبُ فَأَخَذَ ابْنَ إِحْدَاهُمَا فَتَنَازَعَتَا فِي الْآخَرِ فَقَالَتِ الْكُبْرَى: إِنَّمَا ذهب بابنك؟ وَقَالَت الصُّغْرَى: بل إِنَّمَا ذَهَبَ بِابْنِكِ. فَتَحَاكَمَتَا إِلَى دَاوُدَ فَحَكَمَ بِهِ لِلْكُبْرَى، فَخَرَجَتَا عَلَى سُلَيْمَانَ فَقَالَ: ائْتُونِي بِالسِّكِّينِ أَشُقُّهُ نِصْفَيْنِ لِكُلِّ وَاحِدَةٍ مِنْكُمَا نِصْفُهُ؟ فَقَالَت الصُّغْرَى يَرْحَمُكَ اللَّهُ هُوَ ابْنُهَا. فَقَضَى بِهِ لَهَا”.',
    'وَلَعَلَّ كُلًّا مِنَ الْحُكْمَيْنِ كَانَ سَائِغًا فِي شَرِيعَتِهِمْ، وَلَكِنْ مَا قَالَهُ سُلَيْمَانُ أَرْجَحُ، وَلِهَذَا أَثْنَى اللَّهُ عَلَيْهِ بِمَا أَلْهَمَهُ إِيَّاهُ وَمَدَحَ بَعْدَ ذَلِكَ أَبَاهُ.',
  ];

  static const List<String> _p19 = [
    '«وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ ۝ إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ ۝ أَتَدۡعُونَ بَعۡلٗا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ ۝ ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ۝ فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ ۝ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ۝ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ۝ سَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ ۝ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ۝ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ»',
    'قَالُوا وَكَانَ إرْسَاله إِلَى أهل بعلبك غربي دمشق، فَدَعَاهُمْ إِلَى الله عزوجل وَأَن يتْركُوا عبَادَة صنم لَهُم كَانُوا يسمونه “بعلا”.',
    'والاول أصح وَلِهَذَا قَالَ لَهُم: «أَلَا تَتَّقُونَ ۝ أَتَدۡعُونَ بَعۡلٗا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ ۝ ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ».',
    'فَكَذَّبُوهُ وَخَالَفُوهُ وَأَرَادُوا قَتْلَهُ.',
    'وَقَوْلُهُ تَعَالَى: «فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ» أَي للعذاب، إِمَّا فِي الدُّنْيَا وَالْآخِرَة، أَو فِي الْآخِرَةِ. وَالْأَوَّلُ أَظْهَرُ عَلَى مَا ذَكَرَهُ الْمُفَسِّرُونَ والمؤرخون وَقَوله: «إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ» أَيْ إِلَّا مَنْ آمَنُ مِنْهُمْ.',
  ];

  static const List<String> _p20 = [
    'وَقَدْ ذَكَرَهُ اللَّهُ تَعَالَى مَعَ الْأَنْبِيَاءِ فِي سُورَةِ الْأَنْعَامِ فِي قَوْلِهِ «وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ» وَقَالَ تَعَالَى فِي سُورَةِ ص: «وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ»',
  ];

  static const List<String> _p3 = [
    'وَالْمَقْصُودُ أَنَّ الْفَسَادَ لَمَّا انْتَشَرَ فِي الْأَرْضِ وَعم الْبلَاء بِعبَادة الْأَصْنَامِ فِيهَا، بَعَثَ اللَّهُ عَبْدَهُ وَرَسُولَهُ نُوحًا عَلَيْهِ السَّلَامُ، يَدْعُو إِلَى عِبَادَةِ اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ، وَيَنْهَى عَنْ عِبَادَةِ مَا سواهُ.',
    'فَكَانَ أَوَّلَ رَسُولٍ بَعَثَهُ اللَّهُ إِلَى أَهْلِ الْأَرْضِ، كَمَا ثَبَتَ فِي الصَّحِيحَيْنِ فِي حَدِيثِ الشَّفَاعَةِ.',
    'وَبِالْجُمْلَةِ فَنُوحٌ عَلَيْهِ السَّلَامُ إِنَّمَا بَعَثَهُ اللَّهُ تَعَالَى لَمَّا عُبِدَتِ الْأَصْنَامُ وَالطَّوَاغِيتُ، وَشَرَعَ النَّاسُ فِي الضَّلَالَةِ وَالْكُفْرِ، فَبَعْثَهُ اللَّهُ رَحْمَةً لِلْعِبَادِ فَكَانَ أَوَّلَ رَسُولٍ بُعِثَ إِلَى أَهْلِ الْأَرْضِ، كَمَا يَقُولُ أَهْلُ الْمَوْقِفِ يَوْمَ الْقِيَامَةِ.',
    'فَقَالَ فِي سُورَةِ الْأَعْرَافِ:',
    '«لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ۝ قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ ۝ قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ۝ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝ أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ ۝ فَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ»',
    'فَلَمَّا بَعَثَ اللَّهُ نُوحًا عَلَيْهِ السَّلَام، دعاهم إِلَى إِفْرَاد عبَادَة الله وَحده لَا شريك لَهُ، وَألا يعبدوا مَعَه صنما وَلَا تمثالا وَلَا طوغوتا وَأَنْ يَعْتَرِفُوا بِوَحْدَانِيَّتِهِ، وَأَنَّهُ لَا إِلَهَ غَيْرُهُ وَلَا رَبَّ سِوَاهُ، كَمَا أَمَرَ اللَّهُ تَعَالَى مَنْ بَعْدَهُ مِنَ الرُّسُلِ الَّذِينَ هُمْ كُلُّهُمْ مِنْ ذُرِّيَّتِهِ، كَمَا قَالَ تَعَالَى: «وَجَعَلۡنَا ذُرِّيَّتَهُۥ هُمُ ٱلۡبَاقِينَ».',
    'وَقَالَ فِيهِ وَفِي إِبْرَاهِيمَ «وَجَعَلۡنَا فِي ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَۖ» أَيْ كُلُّ نَبِيٍّ مِنْ بَعْدِ نُوحٍ فَمِنْ ذُريَّته.',
    'وَنَصَبُوا لَهُ الْعَدَاوَةَ فِي كُلِّ وَقْتٍ وَأَوَانٍ، وَتَنَقَّصُوهُ وَتَنَقَّصُوا مَنْ آمن بِهِ، وتوعدهم بِالرَّجْمِ وَالْإِخْرَاجِ، وَنَالُوا مِنْهُمْ وَبَالَغُوا فِي أَمْرِهِمْ.',
    '«قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ» أَيِ السَّادَةُ الْكُبَرَاءُ مِنْهُمْ: «إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ».',
    '«قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ»',
    'وَهَذَا شَأْنُ الرَّسُولِ أَنْ يَكُونَ بَلِيغًا، أَيْ فصيحا ناصحا، أعلم النَّاس بِاللَّه عزوجل.',
    'وَقَالُوا لَهُ فِيمَا قَالُوا: «مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ».',
    'تعجبوا أَن يكون بشرا رَسُولا، وتنقصوا من اتَّبَعَهُ وَرَأَوْهُمْ أَرَاذِلَهُمْ.',
    'وَهَذَا الذى رموهم بِهِ هُوَ عَيْنُ مَا يُمْدَحُونَ بِسَبَبِهِ رَضِيَ اللَّهُ عَنْهُمْ: فَإِنَّ الْحَقَّ الظَّاهِرَ لَا يَحْتَاجُ إِلَى رَوِيَّةٍ وَلَا فِكْرٍ وَلَا نَظَرٍ، بَلْ يَجِبُ اتِّبَاعُهُ وَالِانْقِيَادُ لَهُ مَتَى ظَهَرَ.',
    'وَقَوْلُ كَفَرَةِ قَوْمِ نُوحٍ لَهُ وَلِمَنْ آمَنَ بِهِ: «وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ» أَيْ لَمْ يَظْهَرْ لَكُمْ أَمْرٌ بَعْدَ اتِّصَافِكُمْ بالايمان وَلَا مرية عَلَيْنَا «بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ ۝ قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ».',
    'وَقَالَ تَعَالَى فِي سُورَةِ هُودٍ:',
    '«وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ ۝ أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ ۝ فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ»',
    '«قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ ۝ وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ۝ وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ ۝ وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ ۝ قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ۝ قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ ۝ وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ ۝ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءٞ مِّمَّا تُجۡرِمُونَ»',
    '«وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ ۝ وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ۝ وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ ۝ فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ»',
    '«حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ ۝ ۞ وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ ۝ وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ ۝ قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ ۝ وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ»',
    '«وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ ۝ قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ ۝ قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ ۝ قِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ وَأُمَمٞ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٞ ۝ تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ»',
    'وَكَانَ كُلَّمَا انْقَرَضَ جِيلٌ وَصَّوْا مَنْ بَعْدَهُمْ بِعَدَمِ الْإِيمَانِ بِهِ وَمُحَارَبَتِهِ وَمُخَالَفَتِهِ.',
    'وَكَانَ الْوَالِدُ إِذَا بَلَغَ وَلَدُهُ وَعَقَلَ عَنْهُ كَلَامَهُ، وَصَّاهُ فِيمَا بَيْنَهُ وَبَيْنَهُ، أَلا يُؤْمِنَ بِنُوحٍ أَبَدًا مَا عَاشَ وَدَائِمًا مَا بقى.',
    'وَلِهَذَا: «قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ۝ قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ» أَي إِنَّمَا يقدر على ذَلِك الله عزوجل، فَإِنَّهُ الذى لَا يعجزه شئ وَلَا يكترثه أَمر، بل هُوَ الذى يَقُول للشئ كن فَيكون.',
    '«وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ» أَيْ مَنْ يُرِدِ اللَّهُ فِتْنَتَهُ فَلَنْ يَمْلِكَ أَحَدٌ هِدَايَتَهُ، هُوَ الَّذِي يَهْدِي مَنْ يَشَاءُ وَيُضِلُّ مَنْ يَشَاءُ، وَهُوَ الْفَعَّالُ لِمَا يُرِيدُ، وَهُوَ الْعَزِيزُ الْحَكِيمُ، الْعَلِيمُ بِمَنْ يَسْتَحِقُّ الْهِدَايَةَ وَمَنْ يَسْتَحِقُّ الْغِوَايَةَ، وَلَهُ الْحِكْمَةُ الْبَالِغَةُ وَالْحُجَّةُ الدَّامِغَةُ.',
    '«وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ».',
    'وَذَلِكَ أَنَّ نُوحًا عَلَيْهِ السَّلَامُ لَمَّا يَئِسَ مِنْ صَلَاحِهِمْ وَفَلَاحِهِمْ، وَرَأَى أَنَّهُمْ لَا خَيْرَ فِيهِمْ، وَتَوَصَّلُوا إِلَى أَذِيَّتِهِ وَمُخَالَفَتِهِ وَتَكْذِيبِهِ بِكُلِّ طَرِيقٍ، مِنْ فِعَالٍ وَمَقَالٍ، دَعَا عَلَيْهِمْ دَعْوَةَ غضب الله عَلَيْهِم فَلَبَّى اللَّهُ دَعْوَتَهُ وَأَجَابَ طِلْبَتَهُ قَالَ اللَّهُ تَعَالَى: «وَلَقَدۡ نَادَىٰنَا نُوحٞ فَلَنِعۡمَ ٱلۡمُجِيبُونَ ۝ وَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ».',
    'وَقَالَ تَعَالَى: «وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ».',
    'وَقَالَ تَعَالَى «قَالَ رَبِّ إِنَّ قَوۡمِي كَذَّبُونِ ۝ فَٱفۡتَحۡ بَيۡنِي وَبَيۡنَهُمۡ فَتۡحٗا وَنَجِّنِي وَمَن مَّعِيَ مِنَ ٱلۡمُؤۡمِنِينَ» وَقَالَ تَعَالَى: «فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ» وَقَالَ تَعَالَى: «قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ».',
    'فَعِنْدَ ذَلِك أمره الله تَعَالَى أَن يصنع الْفلك، وهى السَّفِينَة الْعَظِيمَة الَّتِى لم يكن لَهَا نَظِير قبلهَا وَلَا يكون بعْدهَا مثلهَا.',
    'وَقدم الله تَعَالَى إِلَيْهِ أَنه إِذا جَاءَ أمره، وَحل بهم بَأْسَهُ الَّذِي لَا يُرَدُّ عَنِ الْقَوْمِ الْمُجْرِمِينَ، أَنه لَا يعاوده فيهم وَلَا يُرَاجِعهُ ; فَإِنَّهُ لَعَلَّه قد تُدْرِكهُ رقة على قومه عِنْد مُعَاينَة الْعَذَاب النَّازِل بهم، فَإِنَّهُ لَيْسَ الْخَبَر كالمعاينة.',
    '«وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ» أَيْ يَسْتَهْزِئُونَ بِهِ اسْتِبْعَادًا لِوُقُوعِ مَا تَوَعَّدَهُمْ بِهِ، «قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ» أَيْ نَحْنُ الَّذِينَ نَسْخَرُ مِنْكُمْ وَنَتَعَجَّبُ مِنْكُمْ فِي اسْتِمْرَارِكُمْ عَلَى كُفْرِكُمْ وَعِنَادِكُمُ الَّذِي يَقْتَضِي وُقُوعَ الْعَذَابِ بِكُمْ وَحُلُولَهُ عَلَيْكُمْ.',
    '«فَسَوۡفَ تَعۡلَمُونَ ۝ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ».',
    'وَقَدْ كَانَتْ سَجَايَاهُمُ الْكُفْرَ الْغَلِيظَ وَالْعِنَادَ الْبَالِغَ فِي الدُّنْيَا، وَهَكَذَا فِي الْآخِرَةِ فَإِنَّهُمْ يَجْحَدُونَ أَيْضا أَن يكون جَاءَهُم رَسُولٌ.',
    'فَيَقُولُ لِأُمَّتِهِ هَلْ بَلَّغَكُمْ؟ فَيَقُولُونَ: لَا مَا جَاءَنَا مِنْ نَبِيٍّ، فَيَقُولُ لِنُوحٍ: مَنْ يَشْهَدُ لَكَ؟ فَيَقُولُ: مُحَمَّدٌ وَأُمَّتُهُ، فَتَشْهَدُ أَنَّهُ قَدْ بَلَّغَ «إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ۝ وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ».',
    'فَهَذِهِ الْأُمَّةُ تَشْهَدُ عَلَى شَهَادَةِ نَبِيِّهَا الصَّادِقِ الْمَصْدُوقِ، بِأَنَّ اللَّهَ قَدْ بَعَثَ نُوحًا بِالْحَقِّ، وَأَنْزَلَ عَلَيْهِ الْحَقَّ وَأَمَرَهُ بِهِ، وَأَنَّهُ بَلَّغَهُ إِلَى أُمَّتِهِ عَلَى أَكْمَلِ الْوُجُوهِ وَأَتَمِّهَا، وَلَمْ يَدَعْ شَيْئًا مِمَّا يَنْفَعُهُمْ فِي دِينِهِمْ إِلَّا وَقَدْ أَمَرَهُمْ بِهِ، وَلَا شَيْئًا مِمَّا قَدْ يَضُرُّهُمْ إِلَّا وَقَدْ نَهَاهُمْ عَنْهُ، وحذرهم مِنْهُ.',
    'وَقَالَ تَعَالَى فِي سُورَةِ الْمُؤْمِنُونَ:',
    '«وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ۝ فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ۝ إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ ۝ قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ۝ فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ۝ فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ۝ وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ ۝ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ»',
    'وَقَدْ تَطَاوَلَ الزَّمَانُ وَالْمُجَادَلَةُ بَيْنَهُ وَبَيْنَهُمْ كَمَا قَالَ تَعَالَى: «فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ» أَيْ وَمَعَ هَذِهِ الْمُدَّةِ الطَّوِيلَةِ فَمَا آمَنَ بِهِ إِلَّا الْقَلِيلُ مِنْهُمْ.',
  ];

  static const List<String> _p7 = [
    'فَقَالَ تَعَالَى فِي سُورَةِ الْأَعْرَافِ:',
    '«وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ۝ إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ۝ وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ۝ فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ۝ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ»',
    'وَقَالَ تَعَالَى فِي سُورَةِ الشُّعَرَاءِ:',
    '«كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ ۝ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ ۝ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ۝ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ۝ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ۝ أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ ۝ وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ ۝ قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ ۝ قَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ ۝ رَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ ۝ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ ۝ إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ ۝ ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ ۝ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ ۝ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ۝ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ»',
    'وَذَلِكَ أَنَّ لُوطًا عَلَيْهِ السَّلَامُ لَمَّا دَعَاهُمْ إِلَى عِبَادَةِ اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ، وَنَهَاهُمْ عَنْ تَعَاطِي مَا ذَكَرَ اللَّهُ عَنْهُمْ مِنَ الْفَوَاحِشِ، لم يَسْتَجِيبُوا لَهُ وَلَمْ يُؤْمِنُوا بِهِ حَتَّى وَلَا رَجُلٌ وَاحِدٌ مِنْهُمْ، وَلَمْ يَتْرُكُوا مَا عَنْهُ نُهُوا. بَلِ اسْتَمَرُّوا عَلَى حَالِهِمْ، وَلِمَ يَرْعَوُوا عَنْ غَيِّهِمْ وَضَلَالِهِمْ، وَهَمُّوا بِإِخْرَاجِ رَسُولِهِمْ مِنْ بَيْنِ ظَهْرَانَيْهِمْ.',
    'إِلَّا أَنْ قَالُوا: «أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ» فَجَعَلُوا غَايَةَ الْمَدْحِ ذَمًّا يَقْتَضِي الْإِخْرَاجَ! وَمَا حَمَلَهُمْ عَلَى مَقَالَتِهِمْ هَذِهِ إِلَّا الْعِنَادُ وَاللَّجَاجُ. فَطَهَّرَهُ اللَّهُ وَأَهْلَهُ إِلَّا امْرَأَتَهُ، وَأَخْرَجَهُمْ مِنْهَا أَحْسَنَ إِخْرَاجٍ، وَتَرَكَهُمْ فِي مَحَلَّتِهِمْ خَالِدِينَ، لَكِنْ بَعْدَ مَا صَيَّرَهَا عَلَيْهِمْ بَحْرَةً مُنْتِنَةً ذَاتَ أَمْوَاجٍ، لَكِنَّهَا عَلَيْهِمْ فِي الْحَقِيقَةِ نَارٌ تَأَجَّجُ، وَحَرٌّ يَتَوَهَّجُ، وَمَاؤُهَا مِلْحٌ أُجَاجٌ.',
    'وَقَالُوا لَهُ فِيمَا قَالُوا: «ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ» فَطَلَبُوا مِنْهُ وُقُوعَ مَا حَذَّرَهُمْ عَنْهُ مِنَ الْعَذَاب الاليم، وحلول الْبَأْس الْعَظِيم. فَعِنْدَ ذَلِكَ دَعَا عَلَيْهِمْ نَبِيُّهُمُ الْكَرِيمُ، فَسَأَلَ مِنْ رَبِّ الْعَالَمِينَ وَإِلَهِ الْمُرْسَلِينَ أَنْ يَنْصُرَهُ عَلَى الْقَوْمِ الْمُفْسِدِينَ. فَغَارَ اللَّهُ لِغَيْرَتِهِ، وَغَضِبَ لِغَضْبَتِهِ ; وَاسْتَجَابَ لِدَعْوَتِهِ، وَأَجَابَهُ إِلَى طِلْبَتِهِ، وَبَعَثَ رُسُلَهُ الْكِرَامَ، وَمَلَائِكَتَهُ الْعِظَامَ، فَمَرُّوا عَلَى الْخَلِيلِ إِبْرَاهِيمَ وَبَشَّرُوهُ بِالْغُلَامِ الْعَلِيمِ، وَأَخْبَرُوهُ بِمَا جَاءُوا لَهُ مِنَ الْأَمْرِ الْجَسِيمِ وَالْخَطْبِ الْعَمِيمِ:',
    '«قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ ۝ قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ ۝ لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةٗ مِّن طِينٖ ۝ مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِينَ» وَقَالَ: «وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ ۝ قَالَ إِنَّ فِيهَا لُوطٗاۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ»',
    'قَالَ اللَّهُ تَعَالَى: “” «وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ»',
    'قَالَ الْمُفَسِّرُونَ: لَمَّا فَصَلَتِ الْمَلَائِكَةُ مِنْ عِنْدِ إِبْرَاهِيمَ - وَهُمْ جِبْرِيلُ وَمِيكَائِيلُ وَإِسْرَافِيلُ - أَقْبَلُوا حَتَّى أَتَوا أَرض سدوم، فِي صور شُبَّانٍ حِسَانٍ، اخْتِبَارًا مِنَ اللَّهِ تَعَالَى لِقَوْمِ لُوطٍ وَإِقَامَةً لِلْحُجَّةِ عَلَيْهِمْ.',
    'وَقَوْلُهُ: «فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ» نهى لَهُم عَن تعاطى مَالا يَلِيقُ مِنَ الْفَاحِشَةِ، وَشَهَادَةٌ عَلَيْهِمْ بِأَنَّهُ لَيْسَ فِيهِمْ رَجُلٌ لَهُ مُسْكَةٌ وَلَا فِيهِ خَيْرٌ، بل الْجَمِيع سُفَهَاء، فجرة أقوياء، كفرة أغبياء.',
    'فَقَالَ قَوْمُهُ، عَلَيْهِمْ لَعْنَةُ اللَّهِ الْحَمِيدِ الْمَجِيدِ، مُجِيبِينَ لِنَبِيِّهِمْ فِيمَا أَمَرَهُمْ بِهِ مِنَ الْأَمْرِ السَّدِيدِ: «لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ». يَقُولُونَ - عَلَيْهِم لعائن الله - لقد علمت يالوط إِنَّهُ لَا أَرَبَ لَنَا فِي نِسَائِنَا، وَإِنَّكَ لتعلم مرادنا وغرضنا. وَاجَهُوا بِهَذَا الْكَلَامِ الْقَبِيحِ رَسُولَهُمُ الْكَرِيمَ، وَلَمْ يَخَافُوا سَطْوَةَ الْعَظِيمِ، ذِي الْعَذَابِ الْأَلِيمِ.',
    'وَلِهَذَا قَالَ عَلَيْهِ السَّلَامُ: «لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ». وَدَّ أَنْ لَوْ كَانَ لَهُ بِهِمْ قُوَّةٌ، أَوله مَنْعَة وشعيرة يَنْصُرُونَهُ عَلَيْهِمْ، لِيُحِلَّ بِهِمْ مَا يَسْتَحِقُّونَهُ مِنَ الْعَذَابِ عَلَى هَذَا الْخِطَابِ.',
    'وَقَالَ تَعَالَى: «وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ ۝ قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ ۝ وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ ۝ قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ ۝ قَالَ هَٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ»',
    'فَأَمَرَهُمْ بِقُرْبَانِ نِسَائِهِمْ، وَحَذَّرَهُمُ الِاسْتِمْرَارَ عَلَى طَرِيقَتِهِمْ وسيآتهم.',
    'فَذَلِك أَن الْمَلَائِكَة تقدّمت إِلَى لوط، عَلَيْهِ السَّلَامُ، آمِرِينَ لَهُ بِأَنْ يَسْرِيَ هُوَ وَأَهْلُهُ مِنْ آخِرِ اللَّيْلِ.',
    'فَلَمَّا خَلَصُوا مِنْ بِلَادهمْ وطلعت الشَّمْس فَكَانَت عِنْدَ شُرُوقِهَا، جَاءَهُمْ مِنْ أَمْرِ اللَّهِ مَا لايرد، وَمِنَ الْبَأْسِ الشَّدِيدِ مَا لَا يُمْكِنُ أَنْ يُصَدَّ.',
    'قَالَ اللَّهُ تَعَالَى:',
    'قَالَ اللَّهُ تَعَالَى: “” «فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ ۝ مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٖ»',
  ];

  static const List<String> _p9 = [
    'قَدْ قَدَّمْنَا أَنَّهُ وُلِدَ وَلِأَبِيهِ مِائَةُ سَنَةٍ، بَعْدَ أَخِيهِ إِسْمَاعِيلَ بِأَرْبَعَ عَشْرَةَ سَنَةً. وَكَانَ عُمُرُ أُمِّهِ سَارَّةَ حِينَ بُشِّرَتْ بِهِ تِسْعِينَ سَنَةً.',
    'قَالَ اللَّهُ تَعَالَى:',
    'قَالَ اللَّهُ تَعَالَى: “” «وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ ۝ وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ»',
    'وَقَدْ ذَكَرَهُ اللَّهُ تَعَالَى بِالثَّنَاءِ عَلَيْهِ فِي غَيْرِ مَا آيَةٍ مِنْ كِتَابِهِ الْعَزِيزِ.',
    'وَقَدَّمْنَا فِي حَدِيثِ أَبِي هُرَيْرَةَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: “إِن الْكَرِيم ابْن الْكَرِيمِ ابْنِ الْكَرِيمِ ابْنِ الْكَرِيمِ يُوسُفُ بْنُ يَعْقُوبَ بْنِ إِسْحَاقَ بْنِ إِبْرَاهِيمَ”.',
  ];

  static const List<String> _p11 = [
    'قَالَ اللَّهُ تَعَالَى فِي سُورَةِ يُوسُفَ:',
    '«إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ ۝ قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ۝ وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ»',
    'فَلَمَّا اسْتَيْقَظَ قَصَّهَا عَلَى أَبِيهِ، فَعَرَفَ أَبُوهُ أَنَّهُ سَيَنَالُ مَنْزِلَةً عَالِيَةً وَرِفْعَةً عَظِيمَةً فِي الدُّنْيَا وَالْآخِرَةِ، بِحَيْثُ يَخْضَعُ لَهُ أَبَوَاهُ وَإِخْوَته فِيهَا.',
    'فَأمره يكتمانها وَأَنْ لَا يَقُصَّهَا عَلَى إِخْوَتِهِ ; كَيْلَا يَحْسُدُوهُ وَيَبْغُوا لَهُ الْغَوَائِلَ وَيَكِيدُوهُ بِأَنْوَاعِ الْحِيَلِ وَالْمَكْرِ.',
    '«لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ ۝ إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ ۝ ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ ۝ قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ»',
    'يُنَبه تَعَالَى على مَا فِي هَذِه الْقِصَّة من الْآيَات وَالْحكم، والدلالات والمواعظ والبينات.',
    'ثمَّ ذكر حسد إخْوَة يُوسُف لَهُ على محبَّة أَبِيه لَهُ ولاخيه - يعنون شقيقه لامه بنيامين - أَكثر مِنْهُم، وهم عصبَة أَي جمَاعَة يَقُولُونَ: فَكُنَّا نَحن أَحَق بالمحبة من هذَيْن «إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ»',
    'ثُمَّ اشْتَوَرُوا فِيمَا بَيْنَهُمْ فِي قَتْلِ يُوسُفَ أَوْ إِبْعَادِهِ إِلَى أَرْضٍ لَا يَرْجِعُ مِنْهَا، لِيَخْلُوَ لَهُمْ وَجْهُ أَبِيهِم أَيْ لِتَتَمَحَّضَ مَحَبَّتُهُ لَهُمْ وَتَتَوَفَّرَ عَلَيْهِمْ، وَأَضْمَرُوا التَّوْبَةَ بَعْدَ ذَلِكَ.',
    'فَأَجْمَعُوا رَأْيَهُمْ عَلَى هَذَا، فَعِنْدَ ذَلِك قَالُوا يَا أَبَانَا مَالك لَا تأمنا على يُوسُف وَإِنَّا لَهُ الناصحون ۝ أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لحافظون ۝ قَالَ إنى ليحزني أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝ قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنحن عصبَة إِنَّا إِذا لخاسرون',
    'طَلَبُوا مِنْ أَبِيهِمْ أَنْ يُرْسِلُ مَعَهُمْ أَخَاهُمْ يُوسُفَ، وَأَظْهَرُوا لَهُ أَنَّهُمْ يُرِيدُونَ أَنْ يَرْعَى مَعَهُمْ، وَأَنْ يَلْعَبَ وَيَنْبَسِطَ، وَقَدْ أَضْمَرُوا لَهُ مَا اللَّهُ بِهِ عَلِيمٌ.',
    'فَأَجَابَهُمُ الشَّيْخُ، عَلَيْهِ مِنَ اللَّهِ أَفْضَلُ الصَّلَاةِ وَالتَّسْلِيمِ: يَا بَنِيَّ يَشُقُّ عَلَيَّ أَنْ أُفَارِقَهُ سَاعَةً مِنَ النَّهَارِ، وَمَعَ هَذَا أَخْشَى أَنْ تَشْتَغِلُوا فِي لَعِبِكُمْ وَمَا أَنْتُمْ فِيهِ، فَيَأْتِيَ الذِّئْبُ فَيَأْكُلَهُ، وَلَا يَقْدِرُ عَلَى دَفْعِهِ عَنْهُ لِصِغَرِهِ',
    '«قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذٗا لَّخَٰسِرُونَ» أَيْ لَئِنْ عَدَا عَلَيْهِ الذِّئْبُ فَأَكَلَهُ مِنْ بَيْنِنَا، أَوِ اشْتَغَلْنَا عَنْهُ حَتَّى وَقَعَ هَذَا وَنحن جمَاعَة، إِنَّا إِذا لخاسرون، أَيْ عَاجِزُونَ هَالِكُونَ.',
    '«فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ ۝ وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ ۝ قَالُواْ يَٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنٖ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ ۝ وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ»',
    'لَمْ يَزَالُوا بِأَبِيهِمْ حَتَّى بَعَثَهُ مَعَهُمْ، فَمَا كَانَ إِلَّا أَنْ غَابُوا عَنْ عَيْنَيْهِ، فَجَعَلُوا يَشْتُمُونَهُ وَيُهِينُونَهُ بِالْفَعَالِ وَالْمَقَالِ، وَأَجْمَعُوا عَلَى إِلْقَائِهِ فِي غَيَابَةِ الْجُبِّ، أَيْ فِي قَعْرِهِ عَلَى رَاعُوفَتِهِ، وَهِيَ الصَّخْرَةُ الَّتِي تَكُونُ فِي وَسَطِهِ يَقِفُ عَلَيْهَا الْمَائِحُ، وَهُوَ الَّذِي يَنْزِلُ لِيَمْلَأَ الدِّلَاءَ إِذَا قَلَّ الْمَاءُ، وَالَّذِي يَرْفَعُهَا بِالْحَبْلِ يُسَمَّى الْمَاتِحَ.',
    'فَلَمَّا أَلْقَوْهُ فِيهِ، أَوْحَى اللَّهُ إِلَيْهِ: أَنه لابد لَكَ مِنْ فَرَجٍ وَمَخْرَجٍ مِنْ هَذِهِ الشِّدَّةِ الَّتِي أَنْتَ فِيهَا، وَلَتُخْبِرَنَّ إِخْوَتَكَ بِصَنِيعِهِمْ هَذَا فِي حَالٍ أَنْتَ فِيهَا عَزِيزٌ، وَهُمْ مُحْتَاجُونَ إِلَيْك خائفون مِنْك، «وَهُمۡ لَا يَشۡعُرُونَ».',
    'فَلَمَّا وَضَعُوهُ فِيهِ وَرَجَعُوا عَنْهُ، أَخَذُوا قَمِيصَهُ فَلَطَّخُوهُ بشئ مِنْ دَمٍ، وَرَجَعُوا إِلَى أَبِيهِمْ عِشَاءً وَهُمْ يَبْكُونَ، أَيْ عَلَى أَخِيهِمْ.',
    '«وَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ ۝ وَشَرَوۡهُ بِثَمَنِۭ بَخۡسٖ دَرَٰهِمَ مَعۡدُودَةٖ وَكَانُواْ فِيهِ مِنَ ٱلزَّٰهِدِينَ ۝ وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ۝ وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ»',
    'قَالَ أَهْلُ الْكِتَابِ: كَانَتْ بِضَاعَتُهُمْ من الفتسق وَالصَّنَوْبَرِ وَالْبُطْمِ قَاصِدِينَ دِيَارَ مِصْرَ مِنَ الشَّامِ، فَأَرْسَلُوا بَعْضَهُمْ لِيَسْتَقُوا مِنْ ذَلِكَ الْبِئْرِ، فَلَمَّا أَدْلَى أَحَدُهُمْ دَلْوَهُ تَعَلَّقَ فِيهِ يُوسُفُ.',
    'وَمَعَ هَذَا لَا يُغَيِّرُهُ تَعَالَى، لِمَا لَهُ فِي ذَلِكَ مِنَ الْحِكْمَةِ الْعَظِيمَةِ وَالْقَدَرِ السَّابِقِ وَالرَّحْمَة بِأَهْل مِصْرَ ; بِمَا يُجْرِي اللَّهُ عَلَى يَدَيْ هَذَا الْغُلَامِ الَّذِي يَدْخُلُهَا فِي صُورَةِ أَسِيرٍ رَقِيقٍ، ثُمَّ بَعْدَ هَذَا يُمَلِّكُهُ أَزِمَّةِ الْأُمُورِ وَيَنْفَعُهُمُ اللَّهُ بِهِ فِي دُنْيَاهُمْ وَأُخْرَاهُمْ، بِمَا لَا يُحَدُّ وَلَا يُوصَفُ.',
    '«وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ ۝ وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ ۝ وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ ۝ قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدٞ مِّنۡ أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٖ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَٰذِبِينَ ۝ وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٖ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّٰدِقِينَ ۝ فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٖ قَالَ إِنَّهُۥ مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمٞ ۝ يُوسُفُ أَعۡرِضۡ عَنۡ هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ»',
    'يَذْكُرُ تَعَالَى مَا كَانَ مِنْ مُرَاوَدَةِ امْرَأَةِ الْعَزِيزِ لِيُوسُفَ عَلَيْهِ السَّلَامُ عَنْ نَفْسِهِ وَطَلَبِهَا مِنْهُ مَالا يَلِيقُ بِحَالِهِ وَمَقَامِهِ، وَهِيَ فِي غَايَةِ الْجَمَالِ وَالْمَالِ.',
    'وَكَيْفَ غَلَّقَتِ الْأَبْوَابَ عَلَيْهَا وَعَلَيْهِ، وَتَهَيَّأَتْ لَهُ وَتَصَنَّعَتْ، وَلَبِسَتْ أَحْسَنَ ثِيَابِهَا وَأَفْخَرَ لِبَاسِهَا، وَهِيَ مَعَ هَذَا كُلِّهِ امْرَأَةُ الْوَزير.',
    'وَهَذَا كُلُّهُ مَعَ أَنَّ يُوسُفَ عَلَيْهِ السَّلَامُ شَابٌّ بَدِيعُ الْجَمَالِ وَالْبَهَاءِ، إِلَّا أَنَّهُ نَبِيٌّ مِنْ سُلَالَةِ الْأَنْبِيَاءِ، فَعَصَمَهُ رَبُّهُ عَنِ الْفَحْشَاء، وحماه عَن مَكْرِ النِّسَاءِ، فَهُوَ سَيِّدُ السَّادَةِ النُّجَبَاءِ، السَّبْعَةِ الْأَتْقِيَاءِ، الْمَذْكُورِينَ فِي الصَّحِيحَيْنِ عَنْ خَاتَمِ الْأَنْبِيَاءِ، فِي قَوْلِهِ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ مِنْ رَبِّ الْأَرْضِ وَالسَّمَاءِ: “سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: إِمَامٌ عَادِلٌ وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ، وَرَجُلٌ مُعَلّق قبله بِالْمَسْجِدِ إِذَا خَرَجَ مِنْهُ حَتَّى يَعُودَ إِلَيْهِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرجل تصدق بِصَدقَة فأخفاها حَتَّى لاتعلم شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ إِنِّي أَخَافُ اللَّهَ”.',
    '«وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ ۝ فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ ۝ قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّٰغِرِينَ ۝ قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ ۝ فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ»',
    'يَذْكُرُ تَعَالَى مَا كَانَ مِنْ قِبَلِ نِسَاءِ الْمَدِينَة، مِنْ نِسَاءِ الْأُمَرَاءِ وَبَنَاتِ الْكُبَرَاءِ فِي الطَّعْنِ عَلَى امْرَأَةِ الْعَزِيزِ وَعَيْبِهَا، وَالتَّشْنِيعِ عَلَيْهَا فِي مراودتها فتاها، وحبها الشَّديد لَهُ، وَهُوَ لَا يُسَاوِي هَذَا ; لِأَنَّهُ مَوْلًى مِنَ الْمَوَالِي وَلَيْسَ مِثْلُهُ أَهْلًا لِهَذَا.',
    'وَلِهَذَا قُلْنَ: «إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ» أَي فِي وَضعهَا الشئ فِي غير مَحَله.',
    '«فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ» أَيْ بِتَشْنِيعِهِنَّ عَلَيْهَا وَالتَّنَقُّصِ لَهَا، وَالْإِشَارَةِ إِلَيْهَا بِالْعَيْبِ وَالْمَذَمَّةِ بِحُبِّ مَوْلَاهَا وَعِشْقِ فَتَاهَا، فَأَظْهَرْنَ ذَمًّا وَهِيَ مَعْذُورَةٌ فِي نَفْسِ الْأَمْرِ، فَلِهَذَا أَحَبَّتْ أَنْ تَبْسُطَ عُذْرَهَا عِنْدَهُنَّ، وَتُبَيِّنَ أَنَّ هَذَا الْفَتَى لَيْسَ كَمَا حَسِبْنَ، وَلَا مِنْ قبيل مالديهن.',
    'فَأَرْسَلَتْ إِلَيْهِنَّ فَجَمَعَتْهُنَّ فِي مَنْزِلِهَا، وَأَعْتَدَتْ لَهُنَّ ضِيَافَةَ مِثْلِهِنَّ، وَأَحْضَرَتْ فِي جُمْلَةِ ذَلِكَ شَيْئًا مِمَّا يُقْطَعُ بِالسَّكَاكِينِ، كَالْأُتْرُجِّ وَنَحْوِهِ، وَآتَتْ كُلَّ وَاحِدَة مِنْهُنَّ سكينا، وَكَانَتْ قَدْ هَيَّأَتْ يُوسُفَ عَلَيْهِ السَّلَامُ، وَأَلْبَسَتْهُ أَحْسَنَ الثِّيَابِ وَهُوَ فِي غَايَةِ طَرَاوَةِ الشَّبَابِ وَأَمَرَتْهُ بِالْخُرُوجِ عَلَيْهِنَّ بِهَذِهِ الْحَالَةِ، فَخَرَجَ وَهُوَ أحسن من الْبَدْر لَا محَالة.',
    '«فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ» أَيْ أَعْظَمْنَهُ وَأَجْلَلْنَهُ وَهِبْنَهُ، وَمَا ظَنَنَّ أَنْ يكون مثلا هَذَا فِي بَنِي آدَمَ، وَبَهَرَهُنَّ حُسْنُهُ حَتَّى اشْتَغَلْنَ عَنْ أَنْفُسِهِنَّ، وَجَعَلْنَ يَحْزُزْنَ فِي أَيْدِيهِنَّ بِتِلْكَ السَّكَاكِينِ وَلَا يَشْعُرْنَ بِالْجِرَاحِ، وَقُلْنَ حَاشَ لِلَّهِ مَا هَذَا بَشَرًا إِنْ هَذَا إِلَّا ملك كريم.',
    'وَلِهَذَا قَالَ تَعَالَى: «فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ۝ ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ حَتَّىٰ حِينٖ ۝ وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ۝ قَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ۝ وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ مَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ۝ يَٰصَٰحِبَيِ ٱلسِّجۡنِ ءَأَرۡبَابٞ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ۝ مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءٗ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ۝ يَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا فَيَسۡقِي رَبَّهُۥ خَمۡرٗاۖ وَأَمَّا ٱلۡأٓخَرُ فَيُصۡلَبُ فَتَأۡكُلُ ٱلطَّيۡرُ مِن رَّأۡسِهِۦۚ قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ»',
    'يَذْكُرُ تَعَالَى عَنِ الْعَزِيزِ وَامْرَأَتِهِ أَنَّهُمْ بَدَا لَهُمْ، أَيْ ظَهَرَ لَهُمْ مِنَ الرَّأْيِ بَعْدَ مَا عَلِمُوا بَرَاءَةَ يُوسُفَ أَنْ يَسْجُنُوهُ إِلَى وَقْتٍ ; لِيَكُونَ ذَلِكَ أَقَلَّ لِكَلَامِ النَّاسِ فِي تِلْكَ الْقَضِيَّة، وَأحمد لِأَمْرِهَا، وَلِيُظْهِرُوا أَنَّهُ رَاوَدَهَا عَنْ نَفْسِهَا فَسُجِنَ بِسَبَبِهَا، فَسَجَنُوهُ ظُلْمًا وَعُدْوَانًا.',
    'وَكَانَ هَذَا مِمَّا قَدَّرَ اللَّهُ لَهُ، وَمِنْ جُمْلَةِ مَا عَصَمَهُ بِهِ ; فَإِنَّهُ أَبْعَدُ لَهُ عَنْ مُعَاشَرَتِهِمْ وَمُخَالَطَتِهِمْ.',
    'فَلَمَّا رَأَيَا يُوسُفَ فِي السجْن أعجبهما سمته وهديه، ودله وطريقته، قَوْله وَفِعْلُهُ، وَكَثْرَةُ عِبَادَتِهِ رَبَّهُ، وَإِحْسَانُهُ إِلَى خَلْقِهِ، فَرَأى كل وَاحِد مهما رُؤْيَا تُنَاسِبُهُ.',
    'أَمَّا السَّاقِي فَرَأَى كَأَنَّ ثَلَاثَ قضبان من حبلة وَقد أَوْرَقَتْ وَأَيْنَعَتْ عَنَاقِيدُ الْعِنَبِ، فَأَخَذَهَا فَاعْتَصَرَهَا فِي كَأْسِ الْمَلِكِ وَسَقَاهُ.',
    'وَرَأَى الْخَبَّازُ عَلَى رَأْسِهِ ثَلَاثَ سِلَالٍ مِنْ خُبْزٍ، وَضَوَارِي الطُّيُورِ تَأْكُلُ من السل الاعلى.',
    'فقصاها عَلَيْهِ وطلبا مِنْهُ أَن يعبرها لَهما وَقَالا: «إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ» فَأَخْبرهُمَا أَنه عليم بتعبيرها خَبِير بأمرها، «قَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ».',
    'وَقَالَ لَهُمَا: إِنَّ هَذَا مِنْ تَعْلِيمِ اللَّهِ إِيَّايَ، لِأَنِّي مُؤْمِنٌ بِهِ مُوَحِّدٌ لَهُ، مُتَّبِعٌ مِلَّةَ آبَائِي الْكِرَامِ: إِبْرَاهِيمَ الْخَلِيلِ وَإِسْحَاقَ وَيَعْقُوبَ.',
    '«مَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا» أَي بِأَن هدَانَا لهَذَا، “وعَلى النَّاس” أَيْ بِأَنْ أَمَرَنَا أَنْ نَدْعُوَهُمْ إِلَيْهِ وَنُرْشِدَهُمْ وَنَدُلَّهُمْ عَلَيْهِ.',
    'وَهُوَ فِي فِطَرِهِمْ مَرْكُوزٌ، وَفِي جِبِلَّتِهِمْ مَغْرُوزٌ «وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ».',
    'ثُمَّ دَعَاهُمْ إِلَى التَّوْحِيدِ وَذَمَّ عِبَادَةَ مَا سوى الله عزوجل، وَصغر أَمر الاوثان وحقرها، وَضعف أمرهَا فَقَالَ: «يَٰصَٰحِبَيِ ٱلسِّجۡنِ ءَأَرۡبَابٞ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ۝ مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءٗ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ» أَي الْمُتَصَرِّفُ فِي خَلْقِهِ الْفَعَّالُ لِمَا يُرِيدُ، الَّذِي يَهْدِي مَنْ يَشَاءُ وَيُضِلُّ مَنْ يَشَاءُ «أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ» أَي وَحده لَا شريك لَهُ و «ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ» أَيِ الْمُسْتَقِيمُ وَالصِّرَاطُ الْقَوِيمُ «وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ»',
    '«وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ يَٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ ۝ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمٖۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ ۝ وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ ۝ يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ ۝ قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ ۝ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ ۝ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ»',
    'ثمَّ نَام فَرَأى سبع سنبلات خضر فِي قَصَبَة وَاحِدَة، وَإِذا سبع أخر دقاق يَا بسات فأكلنهن، فَاسْتَيْقَظَ مذعورا.',
    'فَلَمَّا قصها على ملئه وَقَومه لم يكن فيهم من يحسن تعبيرها، بل «قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ» أَيْ أَخْلَاطُ أَحْلَامٍ مِنَ اللَّيْلِ، لَعَلَّهَا لَا تَعْبِيرَ لَهَا، وَمَعَ هَذَا فَلَا خِبْرَةَ لَنَا بِذَلِكَ.',
    'وَلِهَذَا قَالُوا: «وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ» فَعِنْدَ ذَلِكَ تَذَكَّرَ النَّاجِي مِنْهُمَا، الَّذِي وَصَّاهُ يُوسُف بِأَن يذكرهُ عِنْد ربه فنسيه إِلَى حِينِهِ هَذَا، وَذَلِكَ عَنْ تَقْدِيرِ اللَّهِ عزوجل وَلَهُ الْحِكْمَةُ فِي ذَلِكَ.',
    'فَلَمَّا سَمِعَ رُؤْيَا الْمَلِكِ، وَرَأَى عَجْزَ، النَّاسِ عَنْ تَعْبِيرِهَا، تَذَكَّرَ أَمْرَ يُوسُفَ، وَمَا كَانَ أَوْصَاهُ بِهِ مِنَ التَّذْكَارِ.',
    'وَلِهَذَا قَالَ تَعَالَى: «وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ» أَي تذكر “بعد أمة” أَيْ بَعْدَ مُدَّةٍ مِنَ الزَّمَانِ، وَهُوَ بِضْعُ سِنِين.',
    'فَبَذَلَ يُوسُفُ عَلَيْهِ السَّلَامُ مَا عِنْدَهُ مِنَ الْعِلْمِ بِلَا تَأَخُّرٍ وَلَا شَرْطٍ، وَلَا طَلَبَ الْخُرُوجَ سَرِيعًا ; بَلْ أَجَابَهُمْ إِلَى مَا سَأَلُوا، وَعَبَّرَ لَهُمْ مَا كَانَ مِنْ مَنَامِ الْمَلِكِ، الدَّالِّ عَلَى وُقُوعِ سَبْعِ سِنِينَ مِنَ الْخِصْبِ وَيَعْقُبُهَا سَبْعٌ جُدْبٌ «ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ» يَعْنِي يَأْتِيهِمُ الْغَيْثُ وَالْخِصْبُ وَالرَّفَاهِيَةُ “وَفِيهِ يَعْصِرُونَ” يَعْنِي مَا كَانُوا يَعْصِرُونَهُ مِنَ الْأَقْصَابِ وَالْأَعْنَابِ وَالزَّيْتُونِ وَالسِّمْسِمِ وَغَيْرِهَا.',
    '«وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ ۝ قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ ۝ ذَٰلِكَ لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ ۝ ۞ وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ»',
    'لَمَّا أَحَاطَ الْمَلِكُ عِلْمًا بِكَمَالِ عِلْمِ يُوسُفَ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ، وَتَمَامِ عَقْلِهِ، وَرَأْيِهِ السَّدِيدِ وَفَهْمِهِ، أَمَرَ بِإِحْضَارِهِ إِلَى حَضْرَتِهِ ; لِيَكُونَ مِنْ جُمْلَةِ خَاصَّتِهِ.',
    'فَلَمَّا جَاءَهُ الرَّسُولُ بِذَلِكَ، أَحَبَّ أَنْ لَا يَخْرُجَ حَتَّى يَتَبَيَّنَ لِكُلِّ أَحَدٍ أَنه حبس ظلما وعدوانا، وَأَنه برِئ السَّاحَةِ مِمَّا نَسَبُوهُ إِلَيْهِ بُهْتَانًا.',
    '«قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ» يَعْنِي الْمَلِكَ «فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ» قيل مَعْنَاهُ: إِن سيدى الْعَزِيز يعلم برأتي مِمَّا نُسِبَ إِلَيَّ ; أَيْ فَمُرِ الْمَلِكَ فَلْيَسْأَلْهُنَّ: كَيْفَ كَانَ امْتِنَاعِي الشَّدِيدُ عِنْدَ مُرَاوَدَتِهِنَّ إِيَّايَ؟ وَحَثِّهِنَّ لِي عَلَى الْأَمْرِ الَّذِي لَيْسَ بِرَشِيدٍ وَلَا سديد؟',
    'فَلَمَّا سُئِلْنَ عَنْ ذَلِكَ اعْتَرَفْنَ بِمَا وَقَعَ من الْأَمْرِ، وَمَا كَانَ مِنْهُ مِنَ الْأَمْرِ الْحَمِيدِ و «قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ».',
    '«أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ» أَي فِيمَا يَقُوله ; وَمن أَنَّهُ بَرِئٌ وَأَنَّهُ لَمْ يُرَاوِدْنِي، وَأَنَّهُ حُبِسَ ظُلْمًا وَعُدْوَانًا، وَزُورًا وَبُهْتَانًا.',
    '«قَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ ۝ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَشَآءُۚ نُصِيبُ بِرَحۡمَتِنَا مَن نَّشَآءُۖ وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ۝ وَلَأَجۡرُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ»',
    'لما ظهر للْملك بَرَاءَة عرضه، ونزاهة ساحته عَمَّا كَانُوا أظهرُوا عَنهُ مِمَّا نسبوه إِلَيْهِ، «ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ لِنَفۡسِيۖ» أَيْ أَجْعَلْهُ مِنْ خَاصَّتِي، وَمِنْ أَكَابِرِ دَوْلَتِي، وَمِنْ أَعْيَانِ حَاشِيَتِي، فَلَمَّا كَلَّمَهُ وَسَمِعَ مَقَالَهُ وَتَبَيَّنَ حَالَهُ «قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ» أَيْ ذُو مَكَانَةٍ وَأَمَانَةٍ.',
    '«فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ۝ قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ۝ وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَٰٓأَبَانَا مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرٖۖ ذَٰلِكَ كَيۡلٞ يَسِيرٞ ۝ قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ ۝ وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ۝ وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ»',
    'يَذْكُرُ تَعَالَى مَا كَانَ مِنْ أَمْرِهِمْ بَعْدَ رجوعهم إِلَى أَبِيهِم وَقَوْلهمْ لَهُ: «مُنِعَ مِنَّا ٱلۡكَيۡلُ» أَيْ بَعْدَ عَامِنَا هَذَا إِنْ لَمْ تُرْسِلْ مَعَنَا أَخَانَا، فَإِنْ أَرْسَلْتَهُ مَعَنَا لَمْ يُمْنَعْ مِنَّا.',
    '«وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَٰٓأَبَانَا مَا نَبۡغِيۖ» أَي شئ نُرِيدُ وَقَدْ رُدَّتْ إِلَيْنَا بِضَاعَتُنَا؟ “وَنَمِيرُ أَهْلَنَا” أَيْ نَمْتَارُ لَهُمْ وَنَأْتِيهِمْ بِمَا يُصْلِحُهُمْ فِي سنتهمْ ومحلهم، «وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ» بِسَبَبِهِ',
    'قَالَ اللَّهُ تَعَالَى: «ذَٰلِكَ كَيۡلٞ يَسِيرٞ» أَيْ فِي مُقَابَلَةِ ذَهَابِ وَلَدِهِ الْآخَرِ.',
    'وَكَانَ يَعْقُوب عَلَيْهِ السَّلَام أضن شئ بِوَلَدِهِ بِنْيَامِينَ ; لِأَنَّهُ كَانَ يَشُمُّ فِيهِ رَائِحَةَ أَخِيهِ وَيَتَسَلَّى بِهِ عَنْهُ، وَيَتَعَوَّضُ بِسَبَبِهِ مِنْهُ.',
    'فَلِهَذَا قَالَ: «لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ» أَيْ إِلَّا أَنْ تُغْلَبُوا كُلُّكُمْ عَنِ الْإِتْيَانِ بِهِ.',
    '«فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ».',
    'أَكَّدَ الْمَوَاثِيقَ وَقَرَّرَ الْعُهُودَ، وَاحْتَاطَ لِنَفْسِهِ فِي وَلَدِهِ، وَلَنْ يُغْنِيَ حَذَرٌ مِنْ قَدَرٍ! وَلَوْلَا حَاجَتُهُ وَحَاجَةُ قَوْمِهِ إِلَى الْمِيرَةِ، لَمَا بَعَثَ الْوَلَدَ الْعَزِيزَ، وَلَكِنَّ الْأَقْدَارَ لَهَا أَحْكَامٌ، وَالرَّبُّ تَعَالَى يُقَدِّرُ مَا يَشَاءُ وَيَخْتَارُ مَا يُرِيدُ، وَيَحْكُمُ مَا يَشَاءُ وَهُوَ الْحَكِيمُ الْعَلِيمُ.',
    'ثُمَّ أَمَرَهُمْ أَنْ لَا يَدْخُلُوا الْمَدِينَةَ مِنْ بَابٍ وَاحِدٍ، وَلَكِنْ لِيَدْخُلُوا مِنْ أَبْوَابٍ مُتَفَرِّقَةٍ.',
    '«وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ قَالَ إِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ ۝ فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ ۝ قَالُواْ وَأَقۡبَلُواْ عَلَيۡهِم مَّاذَا تَفۡقِدُونَ ۝ قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرٖ وَأَنَا۠ بِهِۦ زَعِيمٞ ۝ قَالُواْ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ ۝ قَالُواْ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ ۝ قَالُواْ جَزَٰٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ ۝ فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَآءِ أَخِيهِۚ كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ ۝ ۞ قَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ ۝ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبٗا شَيۡخٗا كَبِيرٗا فَخُذۡ أَحَدَنَا مَكَانَهُۥٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ۝ قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذٗا لَّظَٰلِمُونَ»',
    'يَذْكُرُ تَعَالَى مَا كَانَ مِنْ أَمْرِهِمْ حِينَ دَخَلُوا بِأَخِيهِمْ بِنْيَامِينَ عَلَى شَقِيقِهِ يُوسُفَ، وَإِيوَائِهِ إِلَيْهِ، وَإِخْبَارِهِ لَهُ سِرًّا عَنْهُمْ بِأَنَّهُ أَخُوهُ، وَأَمْرِهِ بِكَتْمِ ذَلِكَ عَنْهُمْ.',
    'ثُمَّ احْتَالَ عَلَى أَخْذِهِ مِنْهُمْ وَتَرْكِهِ إِيَّاهُ عِنْدَهُ دُونَهُمْ، فَأَمَرَ فِتْيَانَهُ بِوَضْعِ سِقَايَتِهِ، وَهِيَ الَّتِي كَانَ يَشْرَبُ بهَا ويكيل بهَا للنَّاس الطَّعَام، عَن غرَّة فِي مَتَاعِ بِنْيَامِينَ، ثُمَّ أَعْلَمَهُمْ بِأَنَّهُمْ قَدْ سَرَقُوا صُوَاعَ الْمَلِكِ، وَوَعَدَهُمْ جِعَالَةً عَلَى رَدِّهِ، حِمْلَ بَعِيرٍ، وَضَمِنَهُ الْمُنَادِي لَهُمْ.',
    'فَأَقْبَلُوا عَلَى مَنِ اتَّهَمَهُمْ بِذَلِكَ فَأَنَّبُوهُ وَهَجَّنُوهُ فِيمَا قَالَهُ لَهُم: «قَالُواْ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ» يَقُولُونَ: أَنْتُمْ تَعْلَمُونَ مِنَّا خِلَافَ مَا رَمَيْتُمُونَا بِهِ مِنَ السَّرِقَةِ.',
    '«قَالُواْ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ ۝ قَالُواْ جَزَٰٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ» وَهَذِهِ كَانَتْ شَرِيعَتَهُمْ: أَنَّ السَّارِقَ يُدْفَعُ إِلَى الْمَسْرُوقِ مِنْهُ.',
    'قَالَ اللَّهُ تَعَالَى: «فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَآءِ أَخِيهِۚ» لِيَكُونَ ذَلِكَ أَبْعَدَ لِلتُّهْمَةِ وَأَبْلَغَ فِي الْحِيلَةِ، ثمَّ قَالَ اللَّهُ تَعَالَى: «كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ» أَيْ لَوْلَا اعْتِرَافُهُمْ بِأَنَّ جَزَاءَهُ مَنْ وُجِدَ فِي رَحْلِهِ فَهُوَ جَزَاؤُهُ، لَمَا كَانَ يَقْدِرُ يُوسُفُ عَلَى أَخْذِهِ مِنْهُمْ فِي سِيَاسَةِ مَلِكِ مِصْرَ، «إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ» أَيْ فِي الْعِلْمِ «وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ».',
    'وَذَلِكَ لِأَنَّ يُوسُفَ كَانَ أَعْلَمَ مِنْهُمْ، وَأَتَمَّ رَأْيًا وَأَقْوَى عَزْمًا وَحَزْمًا، وَإِنَّمَا فَعَلَ مَا فَعَلَ عَنْ أَمْرِ اللَّهِ لَهُ فِي ذَلِكَ ; لِأَنَّهُ يَتَرَتَّبُ عَلَى هَذَا الْأَمْرِ مَصْلَحَةٌ عَظِيمَةٌ بَعْدَ ذَلِكَ: مِنْ قُدُومِ أَبِيهِ وَقَوْمِهِ عَلَيْهِ وَوُفُودِهِمْ إِلَيْهِ.',
    'فَلَمَّا عَايَنُوا اسْتِخْرَاجَ الصُّوَاعِ مِنْ حِمْلِ بِنْيَامِينَ «قَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ» يَعْنُونَ يُوسُفَ.',
    '«فَلَمَّا ٱسۡتَيۡـَٔسُواْ مِنۡهُ خَلَصُواْ نَجِيّٗاۖ قَالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَمُوٓاْ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَيۡكُم مَّوۡثِقٗا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِي يُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ يَأۡذَنَ لِيٓ أَبِيٓ أَوۡ يَحۡكُمَ ٱللَّهُ لِيۖ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ۝ ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ ۝ وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ وَإِنَّا لَصَٰدِقُونَ ۝ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ۝ وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ ۝ قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ ۝ قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝ يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ»',
    '«ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ» أَيْ أَخْبِرُوهُ بِمَا رَأَيْتُمْ مِنَ الْأَمْرِ فِي ظَاهِرِ الْمُشَاهَدَةِ «وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ ۝ وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ»، أَيْ فَإِنَّ هَذَا الَّذِي أَخْبَرْنَاكَ بِهِ - مِنْ أَخْذِهِمْ أَخَانَا لِأَنَّهُ سَرَقَ - أَمْرٌ اشْتَهَرَ بِمِصْرَ وَعَلِمَهُ الْعِيرُ الَّتِي كُنَّا نَحْنُ وَهُمْ هُنَاكَ، “وَإِنَّا لَصَادِقُونَ” «قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ» أَيْ لَيْسَ الْأَمْرُ كَمَا ذَكَرْتُمْ، لَمْ يَسْرِقْ فَإِنَّهُ لَيْسَ سجية لَهُ وَلَا خُلُقَهُ.',
    'وَهَذَا كَمَا قَالَ بَعْضُ السَّلَفِ: إِنَّ مِنْ جَزَاءِ السَّيِّئَةِ السَّيِّئَةَ بَعْدَهَا! ثُمَّ قَالَ: «عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ» يَعْنِي يُوسُفَ وَبِنْيَامِينَ وَرُوبِيلَ، «إِنَّهُۥ هُوَ ٱلۡعَلِيمُ» أَيْ بِحَالِي وَمَا أَنَا فِيهِ مِنْ فِرَاقِ الْأَحِبَّةِ “الْحَكِيمُ” فِيمَا يُقَدِّرُهُ وَيَفْعَلُهُ، وَلَهُ الْحِكْمَةُ الْبَالِغَة وَالْحجّة القاطعة.',
    '“وَتَوَلَّى عَنْهُم” أَيْ أَعْرَضَ عَنْ بَنِيهِ «وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ» ذَكَّرَهُ حُزْنُهُ الْجَدِيدُ بِالْحُزْنِ الْقَدِيمِ، وَحَرَّكَ مَا كَانَ كامنا، كَمَا قَالَ بَعضهم:',
    '«فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ ۝ قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ ۝ قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ۝ قَالُواْ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا وَإِن كُنَّا لَخَٰطِـِٔينَ ۝ قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ۝ ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا وَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ»',
    'يُخْبِرُ تَعَالَى عَنْ رُجُوعِ إِخْوَةِ يُوسُفَ إِلَيْهِ وَقُدُومِهِمْ عَلَيْهِ، وَرَغْبَتِهِمْ فِيمَا لَدَيْهِ مِنَ الْمِيرَةِ، وَالصَّدَقَةِ عَلَيْهِمْ بِرَدِّ أَخِيهِمْ بِنْيَامِينَ إِلَيْهِمْ: «فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ» أَيْ مِنَ الْجَدْبِ وَضِيقِ الْحَالِ وَكَثْرَةِ الْعِيَالِ، «وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ» أَيْ ضَعِيفَةٍ لَا يُقْبَلُ مِثْلُهَا مِنَّا إِلَّا أَن تتجاوز عَنَّا.',
    '«فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ».',
    'فَلَمَّا رَأَى مَا هُمْ فِيهِ مِنَ الْحَالِ وَمَا جَاءُوا بِهِ مِمَّا لَمْ يَبْقَ عِنْدَهُمْ سِوَاهُ مِنْ ضَعِيفِ الْمَالِ، تَعَرَّفَ إِلَيْهِمْ وَعَطَفَ عَلَيْهِمْ، قَائِلًا لَهُمْ عَنْ أَمْرِ رَبِّهِ وَرَبِّهِمْ، وَقَدْ حَسَرَ لَهُمْ عَنْ جَبينه الشريف، وَمَا يحويه من الْحَال الذى يعْرفُونَ فِيهِ: «هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ».',
    '“قَالُوا” وتجبوا كُلَّ الْعَجَبِ، وَقَدْ تَرَدَّدُوا إِلَيْهِ مِرَارًا عَدِيدَةً وهم لَا يعْرفُونَ أَنه هُوَ: «أَءِنَّكَ لَأَنتَ يُوسُفُۖ».',
    'يَعْنِي أَنَا يُوسُفُ الَّذِي صَنَعْتُمْ مَعَهُ مَا صَنَعْتُمْ، وَسَلَفَ مِنْ أَمْرِكُمْ فِيهِ مَا فَرَّطْتُمْ.',
    '«وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ ۝ قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ ۝ فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝ قَالُواْ يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ ۝ قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ»',
    'وَقَوله: «لَوۡلَآ أَن تُفَنِّدُونِ» أَيْ تَقُولُونَ إِنَّمَا قُلْتَ هَذَا مِنَ الْفَنَدِ، وَهُوَ الْخَرَفُ وَكِبَرُ السِّنِّ.',
    'قَالَ اللَّهُ تَعَالَى: «فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ» أَيْ بِمُجَرَّدِ مَا جَاءَ أَلْقَى الْقَمِيصَ عَلَى وَجْهِ يَعْقُوبَ فَرَجَعَ مِنْ فَوْرِهِ بَصِيرًا بَعْدَ ماكان ضَرِيرًا.',
    'وَقَالَ لِبَنِيهِ عِنْدَ ذَلِكَ: «أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ» أَيْ أَعْلَمُ أَنَّ اللَّهَ سَيَجْمَعُ شَمْلِي بِيُوسُفَ، وَسَتَقَرُّ عَيْنِي بِهِ، وَسَيُرِينِي فِيهِ وَمِنْهُ مَا يَسُرُّنِي.',
    'فَعِنْدَ ذَلِكَ «قَالُواْ يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ».',
    'طلبُوا مِنْهُ أَن يسْتَغْفر لَهُم الله عزوجل عَمَّا كَانُوا فَعَلُوا وَنَالُوا مِنْهُ وَمِنِ ابْنِهِ، وَمَا كَانُوا عَزَمُوا عَلَيْهِ، وَلَمَّا كَانَ مِنْ نِيَّتِهِمُ التَّوْبَةُ قَبْلَ الْفِعْلِ، وَفَّقَهُمُ اللَّهُ لِلِاسْتِغْفَارِ عِنْدَ وُقُوعِ ذَلِكَ مِنْهُمْ.',
    '«فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ وَقَالَ ٱدۡخُلُواْ مِصۡرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ ۝ وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ۝ ۞ رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ»',
    'قَالَ: وَأَهْلُ الْكِتَابِ يَزْعُمُونَ أَنَّهُ غَابَ عَنْهُ أَرْبَعِينَ سَنَةً.',
    'وَظَاهِرُ سِيَاقِ الْقِصَّةِ يُرْشِدُ إِلَى تَحْدِيدِ الْمُدَّةِ تَقْرِيبًا ; فَإِنَّ الْمَرْأَةَ رَاوَدَتْهُ وَهُوَ شَابٌّ ابْنُ سَبْعَ عَشْرَةَ سَنَةً، فِيمَا قَالَه غير وَاحِد، فَامْتنعَ.',
    'ثُمَّ أُخْرِجَ فَكَانَتْ سَنَوَاتُ الْخِصْبِ السَّبْعُ، ثُمَّ لَمَّا أَمْحَلَ النَّاسُ فِي السَّبْعِ البواقى، جَاءَ إخْوَته يمتارون فِي السَّنَةَ الْأُولَى وَحْدَهُمْ، وَفِي الثَّانِيَةِ وَمَعَهُمْ أَخُوهُ بِنْيَامِينُ وَفِي الثَّالِثَةِ تَعَرَّفَ إِلَيْهِمْ وَأَمَرَهُمْ بِإِحْضَارِ أَهْلِهِمْ أَجْمَعِينَ، فَجَاءُوا كُلُّهُمْ.',
    '«فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ» وَاجْتمعَ بِهِمَا خُصُوصًا وَحْدَهُمَا دُونَ إِخْوَتِهِ، «وَقَالَ ٱدۡخُلُواْ مِصۡرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ».',
    'قيل هَذَا من الْمُقدم والمؤخر ; تَقْدِيره قَالَ: ادْخُلُوا، مِصْرَ وَآوَى إِلَيْهِ أَبَوَيْهِ.',
    'وَكَانَ جُمْلَةُ مَنْ قَدِمَ مَعَ يَعْقُوبَ مِنْ بَنِيهِ وَأَوْلَادِهِمْ - فِيمَا قَالَهُ أَبُو إِسْحَاقَ السَّبِيعِيُّ عَنْ أَبِي عُبَيْدَةَ عَنِ ابْنِ مَسْعُودٍ - ثَلَاثَةً وَسِتِّينَ إِنْسَانًا.',
  ];

  static const List<String> _p14 = [
    'قَالَ اللَّهُ تَعَالَى فِي سُورَةِ الْقَصَصِ:',
    '«إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ ۝ وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ ۝ وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ»',
    'وَالْمَقْصُودُ أَنَّ فِرْعَوْنَ احْتَرَزَ كُلَّ الِاحْتِرَازِ أَنْ لَا يُوجَدَ مُوسَى، حَتَّى جَعَلَ رِجَالًا وَقَوَابِلَ يَدُورُونَ عَلَى الْحَبَالَى، وَيَعْلَمُونَ مِيقَاتَ وَضْعِهِنَّ، فَلَا تَلِدُ امْرَأَةٌ ذَكَرًا إِلَّا ذَبَحَهُ أُولَئِكَ الذَّبَّاحُونَ من سَاعَته.',
    'قَالَ اللَّهُ تَعَالَى: “” «وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ۝ فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ ۝ وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ»',
    'فَلَمَّا فَتَحَتِ الْبَابَ وَكَشَفَتِ الْحِجَابَ، رَأَتْ وَجْهَهُ يَتَلَأْلَأُ بِتِلْكَ الْأَنْوَارِ النَّبَوِيَّةِ وَالْجَلَالَةِ الْمُوسَوِيَّةِ، فَلَمَّا رَأَتْهُ وَوَقَعَ نَظَرُهَا عَلَيْهِ أَحَبَّتْهُ حبا شَدِيدا جدا. فَلَمَّا جَاءَ فِرْعَوْنُ قَالَ: مَا هَذَا؟ وَأَمَرَ بِذَبْحِهِ، فَاسْتَوْهَبَتْهُ مِنْهُ وَدَفَعَتْ عَنْهُ وَقَالَتْ: «قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ». فَقَالَ لَهَا فِرْعَوْن: أما لَك فَنعم وأمالي فَلَا. أَيْ لَا حَاجَةَ لِي بِهِ. وَالْبَلَاءُ مُوكل بالْمَنْطق! وَقَوْلها: «عَسَىٰٓ أَن يَنفَعَنَآ» قد أَنَالَهَا اللَّهُ مَا رَجَتْ مِنَ النَّفْعِ: أَمَّا فِي الدُّنْيَا فَهَدَاهَا اللَّهُ بِهِ، وَأَمَّا فِي الْآخِرَةِ فَأَسْكَنَهَا جَنَّتَهُ بِسَبَبِهِ.',
    'وَقَالَ اللَّهُ تَعَالَى: “” «وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ۝ وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ ۝ ۞ وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ ۝ فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ»',
    'وَلِهَذَا قَالَ: «وَهُمۡ لَا يَشۡعُرُونَ»، وَذَلِكَ لِأَنَّ مُوسَى عَلَيْهِ السَّلَامُ لَمَّا اسْتَقَرَّ بِدَارِ فِرْعَوْنَ أَرَادُوا أَنْ يُغَذُّوهُ بِرَضَاعَةٍ فَلَمْ يَقْبَلْ ثَدْيًا وَلَا أَخَذَ طَعَامًا، فَحَارُوا فِي أمره، واجتهدوا عَلَى تَغْذِيَتِهِ بِكُلِّ مُمْكِنٍ فَلَمْ يَفْعَلْ، كَمَا قَالَ تَعَالَى: «وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ» فَأَرْسَلُوهُ مَعَ الْقَوَابِلِ وَالنِّسَاءِ إِلَى السُّوقِ، لَعَلَّهُمْ يَجِدُونَ مَنْ يُوَافِقُ رَضَاعَتَهُ. فَبَيْنَمَا هُمْ وُقُوفٌ بِهِ وَالنَّاسُ عُكُوفٌ عَلَيْهِ إِذْ بَصُرَتْ بِهِ أُخْتُهُ، فَلَمْ تُظْهِرْ أَنَّهَا تَعْرِفُهُ بَلْ قَالَتْ: «هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ».',
    'فَأَطْلَقُوهَا وَذَهَبُوا مَعَهَا إِلَى مَنْزِلِهِمْ، فَأَخَذَتْهُ أُمُّهُ. فَلَمَّا أَرْضَعَتْهُ الْتَقَمَ ثَدْيَهَا وَأَخَذَ يَمْتَصُّهُ وَيَرْتَضِعُهُ، فَفَرِحُوا بِذَلِكَ فَرَحًا شَدِيدًا، وَذهب البشير إِلَى “آسِيَةَ” يُعْلِمُهَا بِذَلِكَ، فَاسْتَدْعَتْهَا إِلَى مَنْزِلِهَا وَعَرَضَتْ عَلَيْهَا أَنْ تَكُونَ عِنْدَهَا، وَأَنَّ تُحْسِنَ إِلَيْهَا، فَأَبَتْ عَلَيْهَا وَقَالَتْ: إِنَّ لِي بَعْلًا وَأَوْلَادًا، وَلَسْتُ أَقْدِرُ عَلَى هَذَا إِلَّا أَنْ تُرْسِلِيهِ مَعِي. فَأَرْسَلَتْهُ مَعَهَا، وَرَتَّبَتْ لَهَا رَوَاتِبَ، وَأَجْرَتْ عَلَيْهَا النَّفَقَاتِ وَالْكُسَاوى وَالْهِبَاتِ، فَرَجَعَتْ بِهِ تَحُوزُهُ إِلَى رَحْلِهَا وَقَدْ جَمَعَ اللَّهُ شَمَلَهُ بِشَمْلِهَا. قَالَ اللَّهُ تَعَالَى: «فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ» أَيْ كَمَا وَعَدْنَاهَا بِرَدِّهِ وَرِسَالَتِهِ، فَهَذَا رَدُّهُ، وَهُوَ دَلِيلٌ عَلَى صِدْقِ الْبِشَارَةِ بِرِسَالَتِهِ.',
    '«وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ۝ وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ۝ قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ۝ قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ» لَمَّا ذَكَرَ تَعَالَى أَنَّهُ أَنْعَمَ عَلَى أُمِّهِ برده لَهَا وَإِحْسَانِهِ بِذَلِكَ وَامْتِنَانِهِ عَلَيْهَا، شَرَعَ فِي ذِكْرِ أَنَّهُ لَمَّا بَلَغَ أَشُدَّهُ وَاسْتَوَى، وَهُوَ احْتِكَامُ الْخَلْقِ وَالْخُلُقِ، وَهُوَ سِنُّ الْأَرْبَعِينَ فِي قَوْلِ الْأَكْثَرِينَ، آتَاهُ اللَّهُ حُكْمًا وَعِلْمًا، وَهُوَ النُّبُوَّةُ والرسالة الَّتِى كَانَ بشر بهَا أمه حِين قَالَ: «إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ»',
    'قَالَ اللَّهُ تَعَالَى: “فَسَقَى لَهُمَا”. قَالَ الْمُفَسِّرُونَ: وَذَلِكَ أَنَّ الرِّعَاءَ كَانُوا إِذَا فَرَغُوا مِنْ وِرْدِهِمْ، وضعُوا على فَم الْبِئْر صَخْرَة عَظِيمَة، فتجئ هَاتَانِ الْمَرْأَتَانِ فَيَشْرَعَانِ غَنَمَهُمَا فِي فَضْلِ أَغْنَامِ النَّاسِ، فَلَمَّا كَانَ ذَلِكَ الْيَوْمُ، جَاءَ مُوسَى فَرفع تِلْكَ الصَّخْرَة وَحْدَهُ، ثُمَّ اسْتَقَى لَهُمَا وَسَقَى غَنَمَهُمَا، ثُمَّ رد الْحجر كَمَا كَانَ.',
    '«فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ۝ قَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ۝ قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ ۝ قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ».',
    'وَالْمَقْصُودُ: أَنَّهُ لَمَّا أَضَافَهُ وَأَكْرَمَ مَثْوَاهُ، وَقَصَّ عَلَيْهِ مَا كَانَ مِنْ أَمْرِهِ بَشَّرَهُ بِأَنَّهُ قَدْ نَجَا، فَعِنْدَ ذَلِكَ قَالَتْ إِحْدَى الْبِنْتَيْنِ لِأَبِيهَا: “يَا أَبَتِ اسْتَأْجرهُ” أَيْ لِرَعْيِ غَنَمِكَ، ثُمَّ مَدَحَتْهُ بِأَنَّهُ قَوِيٌّ أَمِينٌ. «قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ».',
    'ثُمَّ قَالَ تَعَالَى: «ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ» «وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ»، يَقُولُ: إِنَّ مُوسَى قَالَ لِصِهْرِهِ: الْأَمْرُ عَلَى مَا قُلْتَ، فَأَيُّهُمَا قَضَيْتُ فَلَا عُدْوَانَ عَلَيَّ وَاللَّهُ عَلَى مَقَالَتِنَا سَامِعٌ وَشَاهِدٌ، وَوَكِيلٌ عَلِيَّ وَعَلَيْكَ، وَمَعَ هَذَا فَلَمْ يَقْضِ مُوسَى إِلَّا أَكْمَلَ الْأَجَلَيْنِ وَأَتَمَّهُمَا وَهُوَ الْعَشْرُ سِنِينَ كَوَامِلَ تَامَّةً.',
    'قَالَ الله: «فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارٗاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةٖ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ ۝ فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ۝ وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ ۝ ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَٰنِكَ بُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ» تَقَدَّمَ أَنَّ مُوسَى قَضَى أَتَمَّ الْأَجَلَيْنِ وَأَكْمَلَهُمَا، وَقَدْ يُؤْخَذُ هَذَا مِنْ قَوْلِهِ: «فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ» وَعَنْ مُجَاهِدٍ أَنَّهُ أَكْمَلَ عَشْرًا وَعَشْرًا بَعْدَهَا.',
    'قَالَ اللَّهُ تَعَالَى: “” «فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ»',
    'وَقَالَ فِي سُورَةِ طه: «فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ ۝ إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى ۝ وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ ۝ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ ۝ إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ ۝ فَلَا يَصُدَّنَّكَ عَنۡهَا مَن»',
    'ثُمَّ خَاطَبَهُ تَعَالَى كَمَا يَشَاءُ قَائِلًا لَهُ: «إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ» «إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ» أَي أَنا رَبُّ الْعَالَمِينَ الَّذِي لَا إِلَهَ إِلَّا هُوَ، الَّذِي لَا تَصْلُحُ الْعِبَادَةُ وَإِقَامَةُ الصَّلَاةِ إِلَّا لَهُ. ثُمَّ أَخْبَرَهُ أَنَّ هَذِهِ الدُّنْيَا لَيْسَتْ بِدَارِ قَرَار، وَإِنَّمَا الدَّار الْبَاقِيَة يَوْم الْقِيَامَة، الَّتِي لابد مِنْ كَوْنِهَا وَوُجُودِهَا «لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ» أَيْ مِنْ خَيْرٍ وَشَرٍّ. وَحَضَّهُ وَحَثَّهُ عَلَى الْعَمَلِ لَهَا، وَمُجَانَبَةِ مَنْ لَا يُؤْمِنُ بِهَا مِمَّنْ عَصَى مَوْلَاهُ وَاتَّبَعَ هَوَاهُ. ثُمَّ قَالَ لَهُ مُخَاطِبًا وَمُؤَانِسًا وَمُبَيِّنًا لَهُ أَنَّهُ الْقَادِر على كل شئ، الَّذِي يَقُول للشئ كن فَيكون: «وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ» أَيْ أَمَّا هَذِهِ عَصَاكَ الَّتِي تَعْرِفُهَا مُنْذُ صحبتهَا؟ «قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ». أَي بلَى هَذِهِ عَصَايَ الَّتِي أَعْرِفُهَا وَأَتَحَقَّقُهَا، «قَالَ أَلۡقِهَا يَٰمُوسَىٰ ۝ فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ» وَهَذَا خَارِقٌ عَظِيمٌ وَبُرْهَانٌ قَاطِعٌ عَلَى أَنَّ الَّذِي يكلمهُ هُوَ الَّذِي يَقُول للشئ كُنْ فَيَكُونُ، وَأَنَّهُ الْفَعَّالُ بِالِاخْتِيَارِ.',
    'فَلَمَّا عَايَنَهَا مُوسَى عَلَيْهِ السَّلَامُ “وَلَّى مُدَبِّرًا” أَيْ هَارِبًا مِنْهَا، لِأَنَّ طَبِيعَتَهُ الْبَشَرِيَّةَ تَقْتَضِي ذَلِكَ “وَلَمْ يُعَقِّبْ” أَيْ وَلَمْ يلْتَفت، فناداه ربه قَائِلا لَهُ: «يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ». فَلَمَّا رَجَعَ أَمَرَهُ اللَّهُ تَعَالَى أَنْ يُمْسِكَهَا «قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ» فَيُقَالُ إِنَّهُ هَابَهَا شَدِيدًا، فَوَضَعَ يَدَهُ فِي كُمِّ مِدْرَعَتِهِ، ثُمَّ وَضَعَ يَدَهُ فِي وَسَطِ فمها.',
    'وَقَالَ فِي سُورَةِ النَّمْلِ: «وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ»',
    'وَالْمَقْصُودُ أَنَّ اللَّهَ سُبْحَانَهُ لَمَّا أَمَرَ مُوسَى عَلَيْهِ السَّلَامُ بِالذَّهَابِ إِلَى فِرْعَوْنَ «قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ أَن يَقۡتُلُونِ ۝ وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ۝ قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ». يَقُولُ تَعَالَى مُخْبِرًا عَنْ عَبْدِهِ وَرَسُولِهِ وَكَلِيمِهِ مُوسَى عَلَيْهِ السَّلَام، فِي جَوَابه لرَبه عزوجل حِينَ أَمَرَهُ بِالذَّهَابِ إِلَى عَدُوِّهِ الَّذِي خَرَجَ مِنْ دِيَارِ مِصْرَ فِرَارًا مِنْ سَطْوَتِهِ وَظُلْمِهِ، حِينَ كَانَ مِنْ أَمْرِهِ مَا كَانَ فِي قَتْلِ ذَلِكَ الْقِبْطِيِّ وَلِهَذَا «قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ أَن يَقۡتُلُونِ ۝ وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ» أَيْ اجْعَلْهُ مَعِي مُعِينًا وَرِدْءًا وَوَزِيرًا يُسَاعِدُنِي، وَيُعِينُنِي عَلَى أَدَاءِ رِسَالَتِكَ إِلَيْهِمْ فَإِنَّهُ أَفْصَحُ مِنِّي لِسَانًا وَأَبْلَغُ بَيَانًا. قَالَ اللَّهُ تَعَالَى مُجِيبًا لَهُ إِلَى سُؤَالِهِ: «سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا» أَي برهانا «فَلَا يَصِلُونَ إِلَيۡكُمَا» أَيْ فَلَا يَنَالُونَ مِنْكُمَا مَكْرُوهًا بِسَبَبِ قِيَامِكُمَا بِآيَاتِنَا، وَقِيلَ بِبَرَكَةِ آيَاتِنَا. «أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ».',
    'وَقَالَ فِي سُورَةِ طه: «ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ۝ قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ۝ وَيَسِّرۡ لِيٓ أَمۡرِي ۝ وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ۝ يَفۡقَهُواْ قَوۡلِي» قِيلَ إِنَّهُ أَصَابَهُ فِي لِسَانِهِ لُثْغَةٌ، بِسَبَبِ تِلْكَ الْجَمْرَة الَّتِي وَضعهَا على لِسَانه،',
    'ثُمَّ قَالَ مُوسَى عَلَيْهِ السَّلَامُ: «وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ۝ هَٰرُونَ أَخِي ۝ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ۝ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ۝ كَيۡ نُسَبِّحَكَ كَثِيرٗا ۝ وَنَذۡكُرَكَ كَثِيرًا ۝ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ۝ قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ» أَيْ قَدْ أَجَبْنَاكَ إِلَى جَمِيعِ مَا سَأَلْتَ، وَأَعْطَيْنَاكَ الَّذِي طَلَبْتَ. وَهَذَا مِنْ وَجَاهَتِهِ عِنْدَ ربه عزوجل، حِينَ شَفَعَ أَنْ يُوحِيَ اللَّهُ إِلَى أَخِيهِ فَأَوْحَى إِلَيْهِ. وَهَذَا جَاهٌ عَظِيمٌ، قَالَ اللَّهُ تَعَالَى: «وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا».',
    'وَقَالَ تَعَالَى فِي سُورَةِ الشُّعَرَاءِ: «وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ۝ قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ ۝ قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ۝ وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ۝ وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ۝ قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ ۝ فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ۝ أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ ۝ قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ ۝ وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ» تَقْدِير الْكَلَام: فَأتيَاهُ فَقَالَا لَهُ ذَلِك، وبلغاه مَا أرسلا بِهِ مِنْ دَعْوَتِهِ إِلَى عِبَادَةِ اللَّهِ تَعَالَى وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنْ يَفُكَّ أُسَارَى بَنِي إِسْرَائِيلَ مِنْ قَبْضَتِهِ وَقَهْرِهِ وَسَطْوَتِهِ، وَيَتْرُكُهُمْ يَعْبُدُونَ رَبَّهُمْ حَيْثُ شَاءُوا، وَيَتَفَرَّغُونَ لِتَوْحِيدِهِ وَدُعَائِهِ وَالتَّضَرُّعِ لَدَيْهِ. فَتَكَبَّرَ فِرْعَوْنُ فِي نَفْسِهِ وَعَتَا وطغى، وَنظر إِلَى مُوسَى بِعَين الازدراء والتقص قَائِلًا لَهُ: «أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ» أَيْ أَمَا أَنْتَ الَّذِي رَبَّيْنَاهُ فِي مَنْزِلِنَا؟ وَأَحْسَنَّا إِلَيْهِ وَأَنْعَمْنَا عَلَيْهِ مُدَّةً مِنَ الدَّهْرِ؟.',
    '«قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ ۝ قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ ۝ فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ ۝ قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ ۝ وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ». لما اصطف السَّحَرَة ووقف مُوسَى وهرون عَلَيْهِمَا السَّلَامُ تُجَاهَهُمْ - قَالُوا لَهُ إِمَّا أَنْ تُلْقِيَ قَبْلَنَا، وَإِمَّا أَنْ نُلْقِيَ قَبْلَكَ «قَالَ بَلۡ أَلۡقُواْۖ» أَنْتُمْ، وَكَانُوا قَدْ عَمَدُوا إِلَى حِبَالٍ وَعِصِيٍّ، فَأَوْدَعُوهَا الزِّئْبَقَ وَغَيْرِهِ، مِنَ الْآلَاتِ الَّتِي تضطرب بسبها تِلْكَ الْحِبَالُ وَالْعِصِيُّ اضْطِرَابًا يُخَيَّلُ لِلرَّائِي أَنَّهَا تَسْعَى بِاخْتِيَارِهَا، وَإِنَّمَا تَتَحَرَّكُ بِسَبَبِ ذَلِكَ، فَعِنْدَ ذَلِكَ سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ، وَأَلْقَوْا حِبَالَهُمْ وَعِصِيَّهُمْ، وَهُمْ يَقُولُونَ: «بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ».',
    'قَالَ اللَّهُ تَعَالَى: «فَلَمَّآ أَلۡقَوۡاْ سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَآءُو بِسِحۡرٍ عَظِيمٖ». وَقَالَ تَعَالَى: «فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ ۝ فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ» أَيْ خَافَ عَلَى النَّاسِ أَنْ يَفْتَتِنُوا بِسِحْرِهِمْ وَمِحَالِهِمْ، قَبْلَ أَنْ يُلْقِيَ مَا فِي يَدِهِ، فَإِنَّهُ لَا يصنع شَيْئًا قَبْلَ أَنْ يُؤْمَرَ فَأَوْحَى اللَّهُ إِلَيْهِ فِي السَّاعَةِ الرَّاهِنَةِ: «لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ ۝ وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ» فَعِنْدَ ذَلِكَ أَلْقَى مُوسَى عَصَاهُ وَقَالَ: «مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ ۝ وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ».',
    'وَقَالَ تَعَالَى: «وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ ۝ فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُواْ يَعۡمَلُونَ ۝ فَغُلِبُواْ هُنَالِكَ وَٱنقَلَبُواْ صَٰغِرِينَ ۝ وَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ ۝ قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ ۝ رَبِّ مُوسَىٰ وَهَٰرُونَ». وَذَلِكَ أَن مُوسَى عَلَيْهِ السَّلَام لما أَلْقَاهَا، صَارَتْ حَيَّةً عَظِيمَةً ذَاتَ قَوَائِمَ، فِيمَا ذَكَرَهُ غَيْرُ وَاحِدٍ مِنْ عُلَمَاءِ السَّلَفِ، وَعُنُقٍ عَظِيمٍ وَشَكْلٍ هَائِلٍ مُزْعِجٍ، بِحَيْثُ إِنَّ النَّاسَ انْحَازُوا مِنْهَا وَهَرَبُوا سِرَاعًا، وَتَأَخَّرُوا عَنْ مَكَانِهَا وَأَقْبَلَتْ هِيَ عَلَى مَا أَلْقَوْهُ مِنَ الْحِبَالِ وَالْعِصِيِّ، فَجَعَلَتْ تَلَقَّفَهُ وَاحِدًا وَاحِدًا فِي أَسْرَعِ مَا يَكُونُ مِنَ الْحَرَكَةِ، وَالنَّاسُ يَنْظُرُونَ إِلَيْهَا وَيَتَعَجَّبُونَ مِنْهَا، وَأَمَّا السَّحَرَةُ فَإِنَّهُمْ رَأَوْا مَا هَالَهُمْ وَحَيَّرَهُمْ فِي أَمْرِهِمْ، وَاطَّلَعُوا عَلَى أَمْرٍ لَمْ يَكُنْ فِي خَلَدِهِمْ وَلَا بَالِهِمْ وَلَا يَدْخُلُ تَحت صناعاتهم وأشغالهم، فَعِنْدَ ذَلِك وهنالك تَحَقَّقُوا بِمَا عِنْدَهُمْ مِنَ الْعِلْمِ أَنَّ هَذَا لَيْسَ بِسحر وَلَا شعوذة، وَلَا مِحَالٍ وَلَا خَيَالٍ، وَلَا زُورٍ وَلَا بُهْتَانٍ وَلَا ضَلَالٍ، بَلْ حَقٌّ لَا يَقْدِرُ عَلَيْهِ إِلَّا الْحَقُّ، الَّذِي ابْتَعَثَ هَذَا الْمُؤَيَّدَ بِهِ بِالْحَقِّ. وَكَشَفَ اللَّهُ عَنْ قُلُوبِهِمْ غِشَاوَةَ الْغَفْلَةِ، وَأَنَارَهَا بِمَا خَلَقَ فِيهَا مِنَ الْهُدَى وأراح عَنْهَا الْقَسْوَةَ، وَأَنَابُوا إِلَى رَبِّهِمْ وَخَرُّوا لَهُ سَاجِدِينَ، وَقَالُوا جَهْرَةً لِلْحَاضِرِينَ وَلَمْ يَخْشَوْا عُقُوبَةً وَلَا بلوى: «ءَامَنَّا بِرَبِّ هَٰرُونَ» كَمَا قَالَ تَعَالَى: «فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ ۝ قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ ۝ قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ ۝ إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ ۝ إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ۝ وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ ۝ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ».',
    '«قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ» أَيْ لَنْ نُطِيعَكَ وَنَتْرُكَ مَا وَقَرَ فِي قُلُوبِنَا مِنَ الْبَيِّنَاتِ وَالدَّلَائِلِ الْقَاطِعَاتِ “وَالَّذِي فَطَرَنَا”. قِيلَ مَعْطُوفٌ، وَقِيلَ قَسَمٌ «فَٱقۡضِ مَآ أَنتَ قَاضٍۖ» أَيْ فَافْعَلْ مَا قَدَرْتَ عَلَيْهِ «إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ» أَيْ إِنَّمَا حُكْمُكَ عَلَيْنَا فِي هَذِهِ الْحَيَاةِ الدُّنْيَا، فَإِذَا انْتَقَلْنَا مِنْهَا إِلَى الدَّارِ الْآخِرَةِ صِرْنَا إِلَى حُكْمِ الَّذِي أَسْلَمْنَا لَهُ وَاتَّبَعْنَا رُسُلَهُ «إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ» أَي ثَوَابه خَيْرٌ مِمَّا وَعَدَتْنَا بِهِ مِنَ التَّقْرِيبِ وَالتَّرْغِيبِ، “وَأَبْقَى” أَيْ وَأَدْوَمُ مِنْ هَذِهِ الدَّارِ الْفَانِيَةِ. وَفِي الْآيَةِ الْأُخْرَى: «قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ۝ إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ» أَيْ مَا اجْتَرَمْنَاهُ مِنَ الْمَآثِمِ وَالْمَحَارِمِ «أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ» أَيْ مِنَ الْقِبْطِ، بِمُوسَى وهرون عَلَيْهِمَا السَّلَام. وَقَالُوا لَهُ أَيْضًا: «وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ» أَيْ لَيْسَ لَنَا عِنْدَكَ ذَنْبٌ إِلَّا إِيمَانُنَا (١ بِمَا جَاءَنَا بِهِ رَسُولُنَا، وَاتِّبَاعُنَا آيَاتِ رَبِّنَا لما جاءتنا «رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا» أَيْ ثَبِّتْنَا عَلَى مَا ابْتُلِينَا بِهِ مِنْ عُقُوبَةِ هَذَا الْجَبَّارِ الْعَنِيدِ، وَالسُّلْطَانِ الشَّدِيدِ، بَلِ الشَّيْطَانِ الْمَرِيدِ، “وَتَوَفَّنَا مُسْلِمِينَ”. وَقَالُوا أَيْضًا يَعِظُونَهُ وَيُخَوِّفُونَهُ بِأْسَ رَبِّهِ الْعَظِيمِ: «إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ» يَقُولُونَ لَهُ: فَإِيَّاكَ أَنْ تَكُونَ مِنْهُمْ.',
    '«وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ ۝ يَٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ».',
    'قَالَ عُلَمَاءُ التَّفْسِيرِ: لَمَّا رَكِبَ فِرْعَوْنُ فِي جُنُودِهِ طَالِبًا بَنِي إِسْرَائِيلَ يَقْفُو أَثَرَهُمْ كَانَ فِي جَيْشٍ كَثِيفٍ عَرَمْرَمٍ، حَتَّى قِيلَ كَانَ فِي خُيُولِهِ مِائَةُ أَلْفِ فَحْلٍ أَدْهَمَ، وَكَانَتْ عِدَّةُ جُنُودِهِ تَزِيدُ عَلَى أَلْفِ أَلْفٍ وَسِتِّمِائَةِ أَلْفٍ، فَاللَّهُ أَعْلَمُ. وَالْمَقْصُودُ أَنَّ فِرْعَوْنَ لَحِقَهُمْ بِالْجُنُودِ، فَأَدْرَكَهُمْ عِنْدَ شُرُوقِ الشَّمْسِ، وَتَرَاءَى الْجَمْعَانِ، وَلَمْ يَبْقَ ثَمَّ رَيْبٌ وَلَا لَبْسٌ، وَعَايَنَ كُلٌّ مِنَ الْفَرِيقَيْنِ صَاحِبَهُ وَتَحَقَّقَهُ وَرَآهُ، وَلَمْ يبْق إِلَّا الْمُقَاتلَة والمجادلة وَالْمُحَامَاةُ. فَعِنْدَهَا قَالَ أَصْحَابُ مُوسَى وَهُمْ خَائِفُونَ: “إِنَّا لمدركون” وَذَلِكَ لِأَنَّهُمُ اضْطُرُّوا فِي طَرِيقِهِمْ إِلَى الْبَحْرِ فَلَيْسَ لَهُمْ طَرِيقٌ وَلَا مَحِيدٌ إِلَّا سُلُوكُهُ وَخَوْضُهُ، وَهَذَا مَا لَا يَسْتَطِيعُهُ أَحَدٌ وَلَا يَقْدِرُ عَلَيْهِ، وَالْجِبَالُ عَنْ يَسْرَتِهِمْ وَعَنْ أَيْمَانِهِمْ وَهِيَ شَاهِقَةٌ مُنِيفَةٌ، وَفِرْعَوْنُ قَدْ غَالَقَهُمْ وَوَاجَهَهُمْ، وَعَايَنُوهُ فِي جُنُودِهِ وَجُيُوشِهِ وَعَدَدِهِ وَعُدَدِهِ، وَهُمْ مِنْهُ فِي غَايَةِ الْخَوْفِ وَالذُّعْرِ، لِمَا قَاسَوْا فِي سُلْطَانه من الاهانة وَالْمَكْر. فَشَكَوْا إِلَى نَبِيِّ اللَّهِ مَا هُمْ فِيهِ مِمَّا قد شاهدوه وعاينوه. فَقَالَ لَهُم الرَّسُولُ الصَّادِقُ الْمَصْدُوقُ: «كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ» وَكَانَ فِي السَّاقَةِ، فَتَقَدَّمَ إِلَى الْمُقَدِّمَةِ، وَنَظَرَ إِلَى الْبَحْرِ وَهُوَ يَتَلَاطَمُ بِأَمْوَاجِهِ، وَيَتَزَايَدُ زَبَدُ أجاجه، وَهُوَ يَقُول: هَا هُنَا أمرت.',
    'فَلَمَّا تَفَاقَمَ الْأَمْرُ وَضَاقَ الْحَالُ وَاشْتَدَّ الْأَمْرُ، وَاقْتَرَبَ فِرْعَوْنُ وَجُنُودُهُ فِي جِدِّهِمْ وَحَدِّهِمْ وَحَدِيدِهِمْ، وَغَضَبِهِمْ وَحَنَقِهِمْ، وَزَاغَتِ الْأَبْصَارُ وَبَلغت الْقُلُوب الْحَنَاجِر، عِنْد ذَلِكَ أَوْحَى الْحَلِيمُ الْعَظِيمُ الْقَدِيرُ، رَبُّ الْعَرْشِ الْكَرِيمِ، إِلَى مُوسَى الْكَلِيمِ: «أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ». فَلَمَّا ضَرَبَهُ، يُقَالُ إِنَّهُ قَالَ لَهُ: انْفَلِقْ بِإِذْنِ اللَّهِ. قَالَ اللَّهُ تَعَالَى: «فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ».',
    'قَالَ اللَّهُ تَعَالَى:',
    '«وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ ۝ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ ۝ وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ»',
    'فَلَمَّا جازوه وجاوزوه وَخَرَجَ آخِرُهُمْ مِنْهُ، وَانْفَصَلُوا عَنْهُ، كَانَ ذَلِكَ عِنْدَ قُدُومِ أَوَّلِ جَيْشِ فِرْعَوْنَ إِلَيْهِ، فَلَمَّا تَرَكَهُ عَلَى هَيْئَتِهِ وَحَالَتِهِ وَانْتَهَى فِرْعَوْنُ، فَرَأَى مَا رَأَى وَعَايَنَ مَا عَايَنَ، هَالَهُ هَذَا الْمَنْظَرُ الْعَظِيمُ، وَتَحَقَّقَ مَا كَانَ يَتَحَقَّقُهُ قَبْلَ ذَلِكَ مِنْ أَنَّ هَذَا مِنْ فِعْلِ رَبِّ الْعَرْشِ الْكَرِيمِ، فَأَحْجَمَ وَلَمْ يَتَقَدَّمْ، وَنَدِمَ فِي نَفْسِهِ عَلَى خُرُوجِهِ فِي طَلَبِهِمْ وَالْحَالَةُ هَذِهِ حَيْثُ لَا يَنْفَعُهُ النَّدَمُ، لَكِنَّهُ أَظْهَرَ لِجُنُودِهِ تَجَلُّدًا وَعَامَلَهُمْ مُعَامَلَةَ الْعِدَا، وَحَمَلَتْهُ النَّفْسُ الْكَافِرَةُ وَالسَّجِيَّةُ الْفَاجِرَةُ عَلَى',
    'أَنْ قَالَ لِمَنِ اسْتَخَفَّهُمْ فَأَطَاعُوهُ، وَعَلَى بَاطِلِهِ تَابَعُوهُ: انْظُرُوا كَيْفَ انْحَسَرَ الْبَحْرُ لِي لِأُدْرِكَ عَبِيدِي الآبقين من يَدي، الخارجين على طَاعَتِي وَبَلَدِي؟',
    'قَالَ اللَّهُ تَعَالَى:',
    '«وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ ۝ ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ ۝ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ۝ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ»',
    '«وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ ۝ ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ ۝ فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ»',
    'فَلَمَّا عَايَنَ فِرْعَوْنُ الْهَلَكَةَ وَأُحِيطَ بِهِ، وَبَاشَرَ سَكَرَاتِ الْمَوْتِ أَنَابَ حِينَئِذٍ وَتَابَ، وَآمَنَ حِينَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا، كَمَا قَالَ تَعَالَى: «إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ ۝ وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ». وَقَالَ تَعَالَى: «فَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ ۝ فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَٰفِرُونَ».',
    'وَقَوْلُهُ تَعَالَى: «ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ» اسْتِفْهَامُ إِنْكَارٍ، وَنَصٌّ عَلَى عَدَمِ قَبُولِهِ تَعَالَى مِنْهُ ذَلِكَ، لِأَنَّهُ - وَاللَّهُ أَعْلَمُ - لَوْ رُدَّ إِلَى الدُّنْيَا كَمَا كَانَ لَعَادَ إِلَى مَا كَانَ عَلَيْهِ، كَمَا أَخْبَرَ تَعَالَى عَنِ الْكُفَّارِ إِذَا عَايَنُوا النَّارَ وَشَاهَدُوهَا أَنَّهُمْ يَقُولُونَ: «فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ» قَالَ الله: «بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ». مِنْ مَلَابِسِهِ، لِيَتَحَقَّقُوا بِذَلِكَ هَلَاكَهُ، وَيَعْلَمُوا قُدْرَةَ اللَّهِ عَلَيْهِ. وَلِهَذَا قَالَ: «فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ» أَيْ مُصَاحِبًا دِرْعَكَ الْمَعْرُوفَةَ بِكَ، “لِتَكُونَ” أَيْ أَنْت آيَة “لمن خَلفك” أَي من بني إِسْرَائِيل، ودليلا على قدرَة الله الَّذِي أهْلكك، وَلِهَذَا قَرَأَ بَعْضُ السَّلَفِ: «لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ». وَقَدْ كَانَ هَلَاكُهُ وَجُنُودِهِ فِي يَوْمِ عَاشُورَاءَ.',
  ];

  static const List<String> _p6 = [
    'وَأَمَّا أَهْلُ بَابِلَ فَكَانُوا يَعْبُدُونَ الْأَصْنَامَ، وَهُمُ الَّذِينَ نَاظَرَهُمْ فِي عِبَادَتِهَا وَكَسَرَهَا عَلَيْهِمْ، وَأَهَانَهَا وَبَيَّنَ بُطْلَانَهَا.',
    'وَقَالَ تَعَالَى فِي سُورَةِ الْأَنْبِيَاءِ:',
    '«وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ ۝ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ ۝ قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ ۝ قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ ۝ قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ ۝ قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ ۝ وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ ۝ فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ ۝ قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ ۝ قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ ۝ قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ ۝ قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ ۝ قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ ۝ فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ ۝ ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ ۝ قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ ۝ أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ ۝ قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ ۝ قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ ۝ وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ»',
    'وَقَالَ فِي سُورَةِ الشُّعَرَاءِ:',
    '«وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ ۝ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ ۝ قَالُواْ نَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ ۝ قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ ۝ أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ ۝ قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ ۝ قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ ۝ أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ ۝ فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ ۝ ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ ۝ وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ ۝ وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ۝ وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ ۝ وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ ۝ رَبِّ هَبۡ لِي حُكۡمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ»',
    'وَقَالَ تَعَالَى فِي سُورَةِ الصَّافَّاتِ:',
    '«وَإِنَّ مِن شِيعَتِهِۦ لَإِبۡرَٰهِيمَ ۝ إِذۡ جَآءَ رَبَّهُۥ بِقَلۡبٖ سَلِيمٍ ۝ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ ۝ أَئِفۡكًا ءَالِهَةٗ دُونَ ٱللَّهِ تُرِيدُونَ ۝ فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ ۝ فَنَظَرَ نَظۡرَةٗ فِي ٱلنُّجُومِ ۝ فَقَالَ إِنِّي سَقِيمٞ ۝ فَتَوَلَّوۡاْ عَنۡهُ مُدۡبِرِينَ ۝ فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ ۝ مَا لَكُمۡ لَا تَنطِقُونَ ۝ فَرَاغَ عَلَيۡهِمۡ ضَرۡبَۢا بِٱلۡيَمِينِ ۝ فَأَقۡبَلُوٓاْ إِلَيۡهِ يَزِفُّونَ ۝ قَالَ أَتَعۡبُدُونَ مَا تَنۡحِتُونَ ۝ وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ ۝ قَالُواْ ٱبۡنُواْ لَهُۥ بُنۡيَٰنٗا فَأَلۡقُوهُ فِي ٱلۡجَحِيمِ ۝ فَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَسۡفَلِينَ»',
    'يُخْبِرُ اللَّهُ تَعَالَى عَنْ إِبْرَاهِيمَ خَلِيلِهِ عَلَيْهِ السَّلَام، أَنه أنكر على قومه عبَادَة لاوثان وَحَقَّرَهَا عِنْدَهُمْ وَصَغَّرَهَا وَتَنَقَّصَهَا، فَقَالَ: «مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ»؟ أَيْ مُعْتَكِفُونَ عِنْدَهَا وَخَاضِعُونَ لَهَا، قَالُوا: «وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ». مَا كَانَ حُجَّتَهُمْ إِلَّا صَنِيعُ الْآبَاءِ وَالْأَجْدَادِ، وَمَا كَانُوا عَلَيْهِ مِنْ عِبَادَةِ الْأَنْدَادِ.',
    'وَكَانَ لَهُمْ عِيدٌ يَذْهَبُونَ إِلَيْهِ فِي كُلِّ عَامٍ مَرَّةً إِلَى ظَاهِرِ الْبَلَدِ، فَدَعَاهُ أَبُوهُ لِيَحْضُرَهُ فَقَالَ إِنِّي سَقِيمٌ.',
    'فَلَمَّا خَرَجُوا إِلَى عِيدِهِمْ، وَاسْتَقَرَّ هُوَ فِي بلدهم «فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ» أَيْ ذَهَبَ إِلَيْهَا مُسْرِعًا مُسْتَخْفِيًا، فَوَجَدَهَا فِي بَهْوٍ عَظِيمٍ، وَقَدْ وَضَعُوا بَيْنَ أَيْدِيَهَا أَنْوَاعًا مِنَ الْأَطْعِمَةِ قُرْبَانًا إِلَيْهَا فَقَالَ لَهَا عَلَى سَبِيل التهكم والازدراء «أَلَا تَأۡكُلُونَ ۝ مَا لَكُمۡ لَا تَنطِقُونَ ۝ فَرَاغَ عَلَيۡهِمۡ ضَرۡبَۢا بِٱلۡيَمِينِ» لِأَنَّهَا أَقْوَى وَأَبْطَشُ وَأَسْرَعُ وَأَقْهَرُ، فَكَسَّرَهَا بِقَدُومٍ فِي يَدِهِ كَمَا قَالَ تَعَالَى: “فَجَعَلَهُمْ جُذَاذًا” أَيْ حُطَامًا، كَسَّرَهَا كُلَّهَا «إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ».',
    'وَهَذَا فِيهِ دَلِيلٌ ظَاهِرٌ لَهُمْ لَوْ كَانُوا يَعْقِلُونَ، وَهُوَ مَا حَلَّ بِآلِهَتِهِمُ الَّتِي كَانُوا يَعْبُدُونَهَا، فَلَوْ كَانَتْ آلِهَةً لَدَفَعَتْ عَنْ أَنْفُسِهَا مَنْ أَرَادَهَا بِسُوءٍ لَكِنَّهُمْ قَالُوا مِنْ جَهْلِهِمْ وَقِلَّةِ عَقْلِهِمْ وَكَثْرَةِ ضَلَالِهِمْ وَخَبَالِهِمْ: «مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ».',
    '«قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ» أَيْ فِي الْمَلَأِ الْأَكْبَرِ عَلَى رُءُوسِ الْأَشْهَادِ، لَعَلَّهُمْ يَشْهَدُونَ مَقَالَتَهُ وَيَسْمَعُونَ كَلَامَهُ، وَيُعَايِنُونَ مَا يَحِلُّ بِهِ مِنَ الِاقْتِصَاصِ مِنْهُ. وَكَانَ هَذَا أَكْبَرَ مَقَاصِدِ الْخَلِيلِ عَلَيْهِ السَّلَامُ أَنْ يَجْتَمِعَ النَّاسُ كُلُّهُمْ، فَيُقِيمَ عَلَى جَمِيع عباد الاصنام الْحجَّة على بطلَان ماهم عَلَيْهِ، كَمَا قَالَ مُوسَى عَلَيْهِ السَّلَامُ لِفِرْعَوْنَ: «مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى».',
    'فَلَمَّا اجْتَمَعُوا وَجَاءُوا بِهِ كَمَا ذَكَرُوا «قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ ۝ قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا». قيل مَعْنَاهُ: هُوَ الْحَامِل لى على تكسيرهم، وَإِنَّمَا عَرَّضَ لَهُمْ فِي الْقَوْلِ «فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ» وتإنما أَرَادَ بِقَوْلِهِ هَذَا أَنْ يُبَادِرُوا إِلَى الْقَوْلِ بِأَن هَذِهِ لَا تَنْطِقُ، فَيَعْتَرِفُوا بِأَنَّهَا جَمَادٌ كَسَائِرِ الْجَمَادَاتِ.',
    '«فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ» أَيْ فَعَادُوا عَلَى أَنْفُسِهِمْ بِالْمَلَامَةِ، فَقَالُوا إِنَّكُمْ أَنْتُم الظَّالِمُونَ. أَيْ فَأَطْرَقُوا ثُمَّ قَالُوا: «لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ» أَيْ لَقَدْ عَلِمْتَ يَا إِبْرَاهِيمُ أَنَّ هَذِهِ لَا تَنْطِقُ، فَكَيْفَ تَأْمُرُنَا بِسُؤَالِهَا!. فَعِنْدَ ذَلِكَ قَالَ لَهُمُ الْخَلِيلُ عَلَيْهِ السَّلَامُ: «أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ ۝ أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ».',
    'قَالَ: «أَتَعۡبُدُونَ مَا تَنۡحِتُونَ» أَيْ كَيْفَ تَعْبُدُونَ أَصْنَامًا أَنْتُمْ تَنْحِتُونَهَا مِنَ الْخَشَبِ وَالْحِجَارَةِ، وَتُصَوِّرُونَهَا وَتُشَكِّلُونَهَا كَمَا تُرِيدُونَ «وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ».',
    'عَدَلُوا عَنِ الْجِدَالِ وَالْمُنَاظَرَةِ لَمَّا انْقَطَعُوا وَغُلِبُوا، وَلَمْ تَبْقَ لَهُمْ حَجَّةٌ وَلَا شُبْهَةٌ إِلَى اسْتِعْمَال قوتهم وسلطانهم، لينصروا ماهم عَلَيْهِ مِنْ سَفَهِهِمْ وَطُغْيَانِهِمْ، فَكَادَهُمُ الرَّبُّ جَلَّ جَلَالُهُ ; وَأَعْلَى كَلِمَتَهُ وَدِينَهُ وَبُرْهَانَهُ.',
    'كَمَا قَالَ تَعَالَى:',
    '«قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ ۝ قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ ۝ وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ»',
    'وَذَلِكَ أَنَّهُمْ شَرَعُوا يَجْمَعُونَ حَطَبًا مِنْ جَمِيعِ مَا يُمْكِنُهُمْ مِنَ الْأَمَاكِنِ، فَمَكَثُوا مُدَّةً يَجْمَعُونَ لَهُ حَتَّى إِنَّ الْمَرْأَةَ مِنْهُمْ كَانَتْ إِذَا مَرِضَتْ تَنْذِرُ لَئِنْ عُوفِيَتْ لَتَحْمِلَنَّ حَطَبًا لِحَرِيقِ إِبْرَاهِيمَ.',
    'ثُمَّ أَخَذُوا يُقَيِّدُونَهُ وَيُكَتِّفُونَهُ وَهُوَ يَقُولُ: لَا إِلَه إِلَّا أَنْت سُبْحَانَكَ رب الْعَالمين لَكَ الْحَمْدُ وَلَكَ الْمُلْكُ، لَا شَرِيكَ لَكَ. فَلَمَّا وُضِعَ الْخَلِيلُ عَلَيْهِ السَّلَامُ فِي كِفَّةِ الْمَنْجَنِيقِ مُقَيَّدًا مَكْتُوفًا ثُمَّ أَلْقَوْهُ مِنْهُ إِلَى النَّارِ قَالَ: حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ.',
    'كَمَا رَوَى الْبُخَارِيُّ عَنِ ابْنِ عَبَّاسٍ أَنَّهُ قَالَ: حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ. قَالَهَا إِبْرَاهِيمُ حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ حِينَ قِيلَ لَهُ: «إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ۝ فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ» الْآيَةَ.',
    'فَأَرَادُوا أَنْ يَنْتَصِرُوا فَخُذِلُوا، وَأَرَادُوا أَنْ يَرْتَفِعُوا فَاتَّضَعُوا، وَأَرَادُوا أَنْ يَغْلِبُوا فَغُلِبُوا.',
    'وَأَمَّا فِي الْآخِرَةِ فَإِنَّ نَارَهُمْ لَا تَكُونُ عَلَيْهِمْ بَرْدًا وَلَا سَلَامًا، وَلَا يُلَقَّوْنَ فِيهَا تَحِيَّةً وَلَا سَلَامًا، بَلْ هِيَ كَمَا قَالَ تَعَالَى: «إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا».',
    '«فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ۝ وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ وَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ»',
    'لَمَّا هَجَرَ قَوْمَهُ فِي اللَّهِ، وَهَاجَرَ مِنْ بَيْنِ أَظْهُرِهِمْ، وَكَانَتِ امْرَأَتُهُ عَاقِرًا لَا يُولَدُ لَهَا، وَلَمْ يَكُنْ لَهُ مِنَ الْوَلَدِ أَحَدٌ، بَلْ مَعَهُ ابْنُ أَخِيهِ لُوطُ بْنُ هَارَانَ بْنِ آزَرَ، وَهَبَهُ اللَّهُ تَعَالَى بَعْدَ ذَلِكَ الْأَوْلَادَ الصَّالِحِينَ، وَجَعَلَ فِي ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَابَ. فَكُلُّ نَبِيٍّ بُعِثَ بَعْدَهُ فَهُوَ مِنْ ذُرِّيَّتِهِ، وَكُلُّ كِتَابٍ نَزَلَ مِنَ السَّمَاءِ عَلَى نَبِيٍّ مِنَ الْأَنْبِيَاءِ مِنْ بَعْدِهِ، فَعَلَى أَحَدِ نَسْلِهِ وَعَقِبِهِ ; خِلْعَةً مِنَ اللَّهِ وَكَرَامَةً لَهُ، حِينَ تَرَكَ بِلَادَهُ وَأَهْلَهُ وَأَقْرِبَاءَهُ، وَهَاجَرَ إِلَى بَلَدٍ يتَمَكَّن فِيهَا من عبَادَة ربه عزوجل وَدَعْوَةِ الْخَلْقِ إِلَيْهِ. وَالْأَرْضُ الَّتِي قَصَدَهَا بِالْهِجْرَةِ أَرض الشَّام، وهى الَّتِى قَالَ الله عزوجل: «إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ».',
    'ثُمَّ جَاءَ بِهَا إِبْرَاهِيمُ وَبِابْنِهَا إِسْمَاعِيلَ وَهِيَ تُرْضِعُهُ، حَتَّى وَضَعَهُمَا عِنْدَ الْبَيْتِ عِنْدَ دَوْحَةٍ فَوْقَ زَمْزَمَ فِي أَعْلَى الْمَسْجِدِ وَلَيْسَ بِمَكَّةَ يَوْمَئِذٍ أَحَدٌ وَلَيْسَ بِهَا مَاءٌ. فَوَضَعَهُمَا هُنَالِكَ وَوَضَعَ عِنْدَهُمَا جِرَابًا فِيهِ تَمْرٌ، وَسِقَاءً فِيهِ مَاءٌ.',
    'ثُمَّ قَفَّى إِبْرَاهِيمُ مُنْطَلِقًا فَتَبِعَتْهُ أُمُّ إِسْمَاعِيلَ، فَقَالَتْ: يَا إِبْرَاهِيمُ أَيْنَ تَذْهَبُ وَتَتْرُكُنَا بِهَذَا الْوَادِي الَّذِي لَيْسَ بِهِ أنيس وَلَا شئ؟ فَقَالَتْ لَهُ ذَلِكَ مِرَارًا وَجَعَلَ لَا يَلْتَفِتُ إِلَيْهَا، فَقَالَتْ لَهُ: آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ: نَعَمْ. قَالَتْ: إِذًا لَا يُضَيِّعُنَا.',
    'فَانْطَلَقَ إِبْرَاهِيمُ، حَتَّى إِذَا كَانَ عِنْدَ الثَّنِيَّةِ حَيْثُ لَا يَرَوْنَهُ اسْتَقْبَلَ بِوَجْهِهِ الْبَيْتَ، ثُمَّ دَعَا بهؤلاء الدَّعْوَات وَرَفَعَ يَدَيْهِ فَقَالَ: «رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ».',
    'وَجَعَلَتْ أُمُّ إِسْمَاعِيلَ تُرْضِعُ إِسْمَاعِيلَ وَتَشْرَبُ مِنْ ذَلِك المَاء، حَتَّى إِذا نفد مَا فِي السِّقَاءِ عَطِشَتْ وَعَطِشَ ابْنُهَا، وَجَعَلَتْ تَنْظُرُ إِلَيْهِ يَتَلَوَّى - أَوْ قَالَ يَتَلَبَّطُ - فَانْطَلَقَتْ كَرَاهِيَةَ أَنْ تَنْظُرَ إِلَيْهِ، فَوَجَدَتِ الصَّفَا أَقْرَبَ جَبَلٍ فِي الْأَرْضِ يَلِيهَا فَقَامَتْ عَلَيْهِ ثُمَّ اسْتَقْبَلَتِ الْوَادِيَ تَنْظُرُ هَلْ تَرَى أَحَدًا، فَلَمْ تَرَ أَحَدًا. فَهَبَطَتْ مِنَ الصَّفَا حَتَّى إِذَا بلغت بطن الْوَادِيَ رَفَعَتْ طَرَفَ دِرْعِهَا، ثُمَّ سَعَتْ سَعْيَ الانسان المجهود حَتَّى جَاوَزَتِ الْوَادِيَ ثُمَّ أَتَتِ الْمَرْوَةَ فَقَامَتْ عَلَيْهَا، وَنَظَرَتْ هَلْ تَرَى أَحَدًا؟ فَلَمْ تَرَ أَحَدًا، فعلت ذَلِكَ سَبْعَ مَرَّاتٍ.',
    'فَلَمَّا أَشْرَفَتْ عَلَى الْمَرْوَةِ سَمِعَتْ صَوْتًا فَقَالَتْ: صَهٍ، تُرِيدُ نَفْسَهَا. ثُمَّ تَسَمَّعَتْ فَسَمِعَتْ أَيْضًا، فَقَالَتْ: قَدْ أَسْمَعْتَ إِنْ كَانَ عِنْدَكَ غُوَاثٌ. فَإِذَا هِيَ بِالْمَلَكِ عِنْدَ مَوْضِعِ زَمْزَمَ، فَبَحَثَ بِعَقِبِهِ - أَوْ قَالَ بِجَنَاحِهِ - حَتَّى ظهر المَاء، فَجعلت تحوضه وَتَقُولُ بِيَدِهَا هَكَذَا. وَجَعَلَتْ تَغْرِفُ مِنَ الْمَاءِ فِي سِقَائِهَا وَهُوَ يَفُورُ بَعْدَ مَا تَغْرِفُ.',
    'قَالَ ابْنُ عَبَّاسٍ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: “يَرْحَمُ اللَّهُ أُمَّ إِسْمَاعِيلَ! لَوْ تَرَكَتْ زَمْزَمَ، أَوْ قَالَ لَوْ لَمْ تَغْرِفْ مِنَ الْمَاءِ، لَكَانَتْ زَمْزَمُ عَيْنًا مَعِينًا” قَالَ: فَشَرِبت وأرضعت وَلَدهَا. فَقَالَ لَهَا الْملك: لَا تخافى الضَّيْعَة فَإِن هَاهُنَا بَيْتا لله يبنيه هَذَا الْغُلَامُ وَأَبُوهُ، وَإِنَّ اللَّهَ لَا يُضَيِّعُ أَهْلَهُ.',
    'وَكَانَ الْبَيْتُ مُرْتَفِعًا مِنَ الْأَرْضِ كَالرَّابِيَةِ، تَأْتِيهِ السُّيُولُ فَتَأْخُذُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ، فَكَانَتْ كَذَلِكَ حَتَّى مَرَّتْ بِهِمْ رُفْقَةٌ مِنْ جُرْهُمٍ، أَوْ أَهْلُ بَيْتٍ مِنْ جُرْهُمٍ، مُقْبِلِينَ من طَرِيق كداء، فنزلوا فِي أفسل مَكَّة فَرَأَوْا طائا عَائِفًا، فَقَالُوا: إِنَّ هَذَا الطَّائِرَ لَيَدُورُ عَلَى مَاء، لَعَهْدُنَا بِهَذَا الْوَادِي وَمَا فِيهِ مَاءٌ. فَأَرْسَلُوا جَريا أَو جريين فَإِذا هم بالماه، فَرَجَعُوا فَأَخْبَرُوهُمْ بِالْمَاءِ فَأَقْبَلُوا. قَالَ: وَأُمُّ إِسْمَاعِيلَ عِنْد المَاء، فَقَالُوا: أَتَأْذَنِينَ لَنَا أَنْ نَنْزِلَ عِنْدَكِ؟ قَالَتْ: نَعَمْ. وَلَكِنْ لَا حق لكم فِي المَاء عندنَا قَالُوا: نَعَمْ.',
    'فَنَزَلُوا ورسلوا إِلَى أَهْلِيهِمْ فَنَزَلُوا مَعَهُمْ حَتَّى إِذَا كَانَ بِهَا أَهْلُ أَبْيَاتٍ مِنْهُمْ. وَشَبَّ الْغُلَامُ وَتَعَلَّمَ الْعَرَبِيَّةَ مِنْهُمْ، وَأَنْفَسَهُمْ وَأَعْجَبَهُمْ حِينَ شَبَّ.',
    'ثُمَّ لَبِثَ عَنْهُمْ مَا شَاءَ الله، ثمَّ جَاءَ بعد ذَلِك وإسمعيل يبرى نبلاله تَحت دوحة قرييا مِنْ زَمْزَمَ، فَلَمَّا رَآهُ قَامَ إِلَيْهِ فَصَنَعَا كَمَا يصنع بِالْوَلَدِ الْوَالِد وبالوالد للوالد ثمَّ قَالَ: يَا إِسْمَعِيل إِنَّ اللَّهَ أَمَرَنِي بِأَمْرٍ. قَالَ: فَاصْنَعْ مَا أَمرك بِهِ رَبُّكَ، قَالَ: وَتُعِينُنِي؟ قَالَ: وَأُعِينُكَ. قَالَ: فَإِنَّ اللَّهَ أَمَرَنِي أَنْ أَبْنِيَ هَاهُنَا بَيْتًا. وَأَشَارَ إِلَى أكمة عَلَى مَا حَوْلَهَا.',
    'فَعِنْدَ ذَلِكَ رَفَعَا الْقَوَاعِد من الْبَيْت، فَجعل إِسْمَعِيل يَأْتِي بِالْحِجَارَةِ وَإِبْرَاهِيمُ يَبْنِي، حَتَّى إِذَا ارْتَفَعَ الْبِنَاءُ جَاءَ بِهَذَا الْحَجَرِ فَوَضَعَهُ لَهُ. فَقَامَ عَلَيْهِ وَهُوَ يبْنى وإسمعيل يُنَاوِلُهُ الْحِجَارَةَ وَهُمَا يَقُولَانِ: «رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ». قَالَ: فَجعلَا يَبْنِيَانِ حَتَّى يَدُورَا حَوْلَ الْبَيْتِ وَهُمَا يَقُولَانِ: «رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ».',
    'وَقَالَ اللَّهُ تَعَالَى:',
    '«إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ ۝ رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ ۝ فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ ۝ فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ ۝ فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ ۝ وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ ۝ قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ۝ إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ ۝ وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ ۝ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ۝ سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ ۝ كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ۝ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ۝ وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ ۝ وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ»',
    'فَلَمَّا كَانَ هَذَا، رأى إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ فِي الْمَنَامِ أَنَّهُ يُؤْمَرُ بِذَبْحِ وَلَدِهِ هَذَا. وَهَذَا اخْتِبَارٌ مِنَ اللَّهِ عزوجل لِخَلِيلِهِ فِي أَنْ يَذْبَحَ هَذَا الْوَلَدَ الْعَزِيزَ الَّذِي جَاءَهُ عَلَى كِبَرٍ، وَقَدْ طَعَنَ فِي السِّنِّ، بَعْدَ مَا أُمِرَ بِأَنْ يُسْكِنَهُ هُوَ وَأُمَّهُ فِي بِلَادٍ قَفْرٍ، وَوَادٍ لَيْسَ بِهِ حَسِيسٌ وَلَا أَنِيسٌ، وَلَا زَرْعٌ وَلَا ضَرْعٌ.',
    'فبادر الْغُلَام الْحَلِيم، سر وَالِدَهُ الْخَلِيلَ إِبْرَاهِيمَ، فَقَالَ: «قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ». وَهَذَا الْجَوَابُ فِي غَايَةِ السَّدَادِ وَالطَّاعَةِ لِلْوَالِدِ ولرب الْعباد.',
  ];

  static const List<String> _p4 = [
    'وَالْمَقْصُودُ أَنَّ عَادًا - وَهُمْ عَادٌ الْأُولَى - كَانُوا أَوَّلَ مَنْ عَبَدَ الْأَصْنَامَ بَعْدَ الطُّوفَانِ.',
    'فَبَعَثَ اللَّهُ فِيهِمْ أَخَاهُمْ هُودًا عَلَيْهِ السَّلَامُ فَدَعَاهُمْ إِلَى اللَّهِ، كَمَا قَالَ تَعَالَى بَعْدَ ذِكْرِ قَوْمِ نُوحٍ، وَمَا كَانَ مِنْ أَمْرِهِمْ فِي سُورَةِ الْأَعْرَافِ:',
    '«وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ۝ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ ۝ قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ۝ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ ۝ أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ۝ قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ۝ قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ۝ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ وَمَا كَانُواْ مُؤۡمِنِينَ».',
    'وَقَدْ قَدَّمْنَا أَنَّهُمْ أَوَّلُ الامم الَّذين عَبَدُوا الْأَصْنَامَ بَعْدَ الطُّوفَانِ.',
    'وَذَلِكَ بَيِّنٌ فِي قَوْلِهِ لَهُمْ: «وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ» أَيْ جَعَلَهُمْ أَشَدَّ أَهْلِ زَمَانِهِمْ فِي الْخِلْقَةِ وَالشِّدَّةِ وَالْبَطْشِ.',
    'وَالْمَقْصُود أَن عادا كَانُوا جُفَاةً كَافِرِينَ، عُتَاةً مُتَمَرِّدِينَ فِي عِبَادَةِ الْأَصْنَامِ، فَأَرْسَلَ اللَّهُ فِيهِمْ رَجُلًا مِنْهُمْ يَدْعُوهُمْ إِلَى اللَّهِ وَإِلَى إِفْرَادِهِ بِالْعِبَادَةِ وَالْإِخْلَاصِ لَهُ، فَكَذَّبُوهُ وَخَالَفُوهُ وَتَنَقَّصُوهُ، فَأَخَذَهُمُ اللَّهُ أَخْذَ عَزِيزٍ مُقْتَدِرٍ.',
    'فَلَمَّا أَمَرَهُمْ بِعِبَادَةِ اللَّهِ وَرَغَّبَهُمْ فِي طَاعَتِهِ وَاسْتِغْفَارِهِ، وَوَعَدَهُمْ عَلَى ذَلِكَ خَيْرَ الدُّنْيَا وَالْآخِرَةِ، وَتَوَعَّدَهُمْ عَلَى مُخَالَفَةِ ذَلِكَ عُقُوبَةَ الدُّنْيَا وَالْآخِرَةِ «قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ» أَي هَذَا الامر الذى تدعونا إِلَيْهِ سفه بِالنِّسْبَةِ إِلَى مَا نَحن عَلَيْهِ من عبَادَة هَذِه الاصنام الَّتِى يرتجى مِنْهَا النَّصْر والرزق، وَمَعَ هَذَا نظن أَنَّك تكذب فِي دعواك أَن الله أرسلك.',
    '«قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ»، أَي لَيْسَ الامر كَمَا تظنون وَلَا كَمَا تَعْتَقِدُونَ «أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ» وَالْبَلَاغُ يَسْتَلْزِمُ عَدَمَ الْكَذِبِ فِي أَصْلِ الْمُبَلِّغِ، وَعدم الزِّيَادَة فِيهِ وَالنَّقْص مِنْهُ، ويستلزم أداءه بِعِبَارَةٍ فَصِيحَةٍ وَجِيزَةٍ جَامِعَةٍ مَانِعَةٍ لَا لَبْسَ فِيهَا وَلَا اخْتِلَافَ وَلَا اضْطِرَابَ.',
    'وَهُوَ مَعَ هَذَا الْبَلَاغِ عَلَى هَذِهِ الصِّفَةِ فِي غَايَةِ النُّصْحِ لِقَوْمِهِ وَالشَّفَقَةِ عَلَيْهِمْ وَالْحِرْصِ عَلَى هِدَايَتِهِمْ، لَا يَبْتَغِي مِنْهُمْ أَجْرًا وَلَا يَطْلُبُ مِنْهُمْ جعلا ; بل هُوَ مخلص لله عزوجل فِي الدَّعْوَةِ إِلَيْهِ وَالنُّصْحِ لِخَلْقِهِ، لَا يَطْلُبُ أَجْرَهُ إِلَّا مِنَ الَّذِي أَرْسَلَهُ، فَإِنَّ خَيْرَ الدُّنْيَا وَالْآخِرَةِ كُلَّهُ فِي يَدَيْهِ وَأَمْرُهُ إِلَيْهِ وَلِهَذَا وَقَالَ: «يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ» أَي أما لَكُمْ عَقْلٌ تُمَيِّزُونَ بِهِ وَتَفْهَمُونَ أَنِّي أَدْعُوكُمْ إِلَى الْحَقِّ الْمُبِينِ الَّذِي تَشْهَدُ بِهِ فِطَرُكُمُ الَّتِي خُلِقْتُمْ عَلَيْهَا، وَهُوَ دِينُ الْحَقِّ الَّذِي بَعَثَ اللَّهُ بِهِ نُوحًا وَأَهْلَكَ مَنْ خَالَفَهُ مِنَ الْخَلْقِ.',
    'وَهَا أَنَا أَدْعُوكُمْ إِلَيْهِ وَلَا أَسْأَلُكُمْ أَجْرًا عَلَيْهِ، بَلْ أَبْتَغِي ذَلِكَ عِنْدَ اللَّهِ مَالِكُ الضُّرِّ وَالنَّفْعِ.',
    'وَلِهَذَا قَالَ مُؤْمِنُ “يس”: «ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ۝ وَمَالِيَ لَآ أَعۡبُدُ ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ» وَقَالَ قوم هود لَهُ فِيمَا قَالُوا: «قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةٖ وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ ۝ إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ»، يَقُولُونَ مَا جِئْتَنَا بِخَارِقٍ يَشْهَدُ لَكَ بِصِدْقِ ماجئت بِهِ، وَمَا نَحْنُ بِالَّذِينِ نَتْرُكُ عِبَادَةَ أَصْنَامِنَا عَنْ مُجَرَّدِ قَوْلِكَ ; بِلَا دَلِيلٍ أَقَمْتَهُ وَلَا بُرْهَانٍ نَصَبْتَهُ، وَمَا نَظُنُّ إِلَّا أَنَّكَ مَجْنُونٌ فِيمَا تزعمه.',
    'وَعِنْدنَا أَنه إِنَّمَا أَصَابَك هَذَا لَان بَعْضَ آلِهَتِنَا غَضِبَ عَلَيْكَ فَأَصَابَكَ فِي عَقْلِكَ فَاعْتَرَاكَ جُنُونٌ بِسَبَبِ ذَلِكَ.',
    'وَهُوَ قَوْلُهُمْ: «إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ».',
    '«قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ۝ مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ».',
    'وَهَذَا تحد مِنْهُ لَهُم، وتبرأ من آلِهَتهم وتنقص مِنْهُ لَهَا، وَبَيَان أَنَّهَا لَا تَنْفَع شَيْئا وَلَا تضر، وَأَنَّهَا جماد حكمهَا حكمه وفعلها فعله.',
    'فَإِن كَانَت كَمَا تَزْعُمُونَ من أَنَّهَا تنصر وَتَنْفَع وتضر فها أَنا برِئ مِنْهَا لَا عَن لَهَا «فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ» أَنْتُم جَمِيعًا بِجَمِيعِ مَا يُمْكِنُكُمْ أَنْ تَصِلُوا إِلَيْهِ وَتَقْدِرُوا عَلَيْهِ، وَلَا تُؤَخِّرُونِي سَاعَةً وَاحِدَةً وَلَا طَرْفَةَ عَيْنٍ فَإِنِّي لَا أُبَالِي بِكُمْ وَلَا أُفَكِّرُ فِيكُمْ، وَلَا أَنْظُرُ إِلَيْكُمْ.',
    '«إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ» أَيْ أَنَا مُتَوَكِّلٌ عَلَى اللَّهِ وَمُتَأَيِّدٌ بِهِ، وواثق بجنابه الذى لَا يضيع من لاذبه واستند إِلَيْهِ، فلست أبالى مخلوقا سواهُ، لست أَتَوَكَّلُ إِلَّا عَلَيْهِ وَلَا أَعْبُدُ إِلَّا إِيَّاهُ.',
    'وَهَذَا وَحْدَهُ بُرْهَانٌ قَاطِعٌ عَلَى أَنَّ هُودًا عَبْدُ اللَّهِ وَرَسُولُهُ، وَأَنَّهُمْ عَلَى جَهْلٍ وَضَلَالٍ فِي عِبَادَتِهِمْ غَيْرَ اللَّهِ ; لِأَنَّهُمْ لَمْ يَصِلُوا إِلَيْهِ بِسُوءٍ وَلَا نَالُوا مِنْهُ مَكْرُوهًا.',
    'فَدَلَّ عَلَى صِدْقِهِ فِيمَا جَاءَهُمْ بِهِ، وَبُطْلَانِ مَا هُمْ عَلَيْهِ وَفَسَادِ مَا ذَهَبُوا إِلَيْهِ.',
    'اسْتَبْعَدُوا أَنْ يَبْعَثَ اللَّهُ رَسُولًا بَشَرِيًّا.',
    'وَهَذِهِ الشُّبْهَةُ أَدْلَى بِهَا كَثِيرٌ مِنْ جَهَلَةِ الْكَفَرَةِ قَدِيمًا وَحَدِيثًا، كَمَا قَالَ تَعَالَى: «أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ» وَقَالَ تَعَالَى: وَمَا مَنَعَ النَّاسَ أَنْ يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى إِلَّا أَنْ قَالُوا أَبَعَثَ اللَّهُ بَشَرًا رَسُولًا قُلْ لَوْ كَانَ فِي الْأَرْضِ مَلَائِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِمْ مِنَ السَّمَاء ملكا رَسُولا “.”',
    'وَلِهَذَا قَالَ لَهُم هود عَلَيْهِ السَّلَام: «أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ» أَيْ لَيْسَ هَذَا بِعَجِيبٍ ; فَإِنَّ اللَّهَ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُ.',
    'وَقَوْلُهُ: «أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ ۝ ۞ هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ ۝ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ ۝ إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ»',
    '«قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ». اسْتَبْعَدُوا الْمِيعَادَ وَأَنْكَرُوا قِيَامَ الْأَجْسَادِ بَعْدَ صَيْرُورَتِهَا تُرَابًا وَعِظَامًا، وَقَالُوا: هَيْهَاتَ هَيْهَاتَ، أَيْ بَعِيدٌ بَعِيدٌ هَذَا الْوَعْدُ، «إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ»، أَيْ يَمُوتُ قَوْمٌ وَيَحْيَا آخَرُونَ.',
    'وَقَالَ لَهُمْ فِيمَا وَعَظَهُمْ بِهِ: «أَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ۝ وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ».',
    'يَقُولُ لَهُمْ: أَتَبْنُونَ بِكُلِّ مَكَانٍ مُرْتَفِعٍ بَنَاءً عَظِيمًا هَائِلًا كَالْقُصُورِ وَنَحْوِهَا، تَعْبَثُونَ بِبِنَائِهَا لِأَنَّهُ لَا حَاجَةَ لَكُمْ فِيهِ، وَمَا ذَاكَ إِلَّا لِأَنَّهُمْ كَانُوا يَسْكُنُونَ الْخِيَامَ، كَمَا قَالَ تَعَالَى: «تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ ۝ إِرَمَ ذَاتِ ٱلۡعِمَادِ ۝ ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ» فَعَادُ إِرَمَ هُمْ عَادٌ الْأُولَى الَّذِينَ كَانُوا يَسْكُنُونَ الْأَعْمِدَةَ الَّتِي تَحْمِلُ الْخِيَامَ.',
    'وَقَالُوا لَهُ مِمَّا قَالُوا: «أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ» أَي أجئتنا لنعبد الله وَحده، وَنُخَالِف آبَاؤُنَا وَأَسْلَافَنَا وَمَا كَانُوا عَلَيْهِ؟ فَإِنْ كُنْتَ صَادِقًا فِيمَا جِئْتَ بِهِ فَأْتِنَا بِمَا تَعِدُنَا مِنَ الْعَذَابِ وَالنَّكَالِ، فَإِنَّا لَا نُؤْمِنُ بِكَ وَلَا نَتْبَعُكَ وَلَا نُصَدِّقُكَ.',
    'كَمَا قَالُوا: «سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ۝ إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ ۝ وَمَا نَحۡنُ بِمُعَذَّبِينَ».',
    'قَالَ: «قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ» أَي قد استحققتم بِهَذِهِ الْمَقَالَةِ الرِّجْسَ وَالْغَضَبَ مِنَ اللَّهِ، أَتُعَارِضُونَ عِبَادَةَ اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ بِعِبَادَةِ أَصْنَامٍ أَنْتُمْ نَحَتُّمُوهَا وَسَمَّيْتُمُوهَا آلِهَةً مِنْ تِلْقَاءِ أَنْفُسِكُمِ؟ اصْطَلَحْتُمْ عَلَيْهَا أَنْتُمْ وَآبَاؤُكُمْ، مَا نَزَّلَ الله بهَا من سُلْطَان.',
    'أَيْ لَمْ يُنَزِّلْ عَلَى مَا ذَهَبْتُمْ إِلَيْهِ دَلِيل وَلَا برهانا.',
    'وَإِذ أَبَيْتُمْ قَبُولَ الْحَقِّ وَتَمَادَيْتُمْ فِي الْبَاطِلِ، وَسَوَاءٌ عَلَيْكُمْ أَنْهَيْتُكُمْ عَمَّا أَنْتُمْ فِيهِ أَمْ لَا، فَانْتَظِرُوا الْآنَ عَذَابَ اللَّهِ الْوَاقِعَ بِكُمْ، وَبَأْسَهُ الَّذِي لَا يُرَدُّ وَنَكَالَهُ الَّذِي لَا يُصَدُّ.',
    'وَقَالَ تَعَالَى: «قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ۝ قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ ۝ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ» وَقَالَ تَعَالَى: «قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ۝ قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ۝ فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ ۝ تُدَمِّرُ كُلَّ شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ».',
    'وَأما تَفْصِيل إهلاكهم فَكَمَا قَالَ تَعَالَى: «فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ» كَانَ هَذَا أَوَّلَ مَا ابْتَدَأَهُمُ الْعَذَابُ، أَنَّهُمْ كَانُوا مُمْحِلِينَ مُسْنِتِينَ، فَطَلَبُوا السُّقْيَا فَرَأَوْا عَارِضًا فِي السَّمَاءِ وَظَنُّوهُ سُقْيَا رَحْمَةٍ، فَإِذَا هُوَ سُقْيَا عَذَابٍ.',
    'وَلِهَذَا قَالَ تَعَالَى: «بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ» أَيْ مِنْ وُقُوعِ الْعَذَابِ وَهُوَ قَوْلُهُمْ: «فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ» وَمِثْلُهَا فِي الْأَعْرَافِ.',
  ];

  static const List<String> _p5 = [
    'صالح عليه السلام نبى ثَمُود وهم قَبيلَة مَشْهُورَة، يُقَال لَهُم ثَمُودُ بِاسْمِ جَدِّهِمْ ثَمُودَ أَخِي جَدِيسٍ، وَهُمَا ابْنا عاثر بْنِ إِرَمَ بْنِ سَامِ بْنِ نُوحٍ.',
    'وَكَانُوا عَرَبًا مِنَ الْعَارِبَةِ يَسْكُنُونَ الْحِجْرَ الَّذِي بَيْنَ الْحِجَازِ وَتَبُوكَ.',
    'وَكَانُوا بَعْدَ قَوْمِ عَادٍ، وَكَانُوا يَعْبُدُونَ الْأَصْنَامَ كَأُولَئِكَ.',
    'فَبَعَثَ اللَّهُ فِيهِمْ رَجُلًا مِنْهُمْ وَهُوَ عبد الله وَرَسُوله: صَالح بن عبيد ابْن ماسح بن عبيد بن حادر بن ثَمُود بن عاثر بن إرم بْنِ نُوحٍ فَدَعَاهُمْ إِلَى عِبَادَةِ اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنْ يَخْلَعُوا الْأَصْنَامَ وَالْأَنْدَادَ وَلَا يُشْرِكُوا بِهِ شَيْئًا.',
    'فَآمَنَتْ بِهِ طَائِفَةٌ مِنْهُمْ، وَكَفَرَ جُمْهُورُهُمْ، وَنَالُوا مِنْهُ بِالْمَقَالِ وَالْفَعَالِ، وَهَمُّوا بِقَتْلِهِ، وَقَتَلُوا النَّاقَةَ الَّتِي جَعَلَهَا اللَّهُ حُجَّةً عَلَيْهِمْ، فَأَخَذَهُمُ اللَّهُ أَخْذَ عَزِيزٍ مُقْتَدِرٍ.',
    'كَمَا قَالَ تَعَالَى فِي سُورَةِ الْأَعْرَافِ: «وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ ۝ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ»',
    'فَاذْكُرُوا آلَاءَ اللَّهِ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ ۝ قَالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِنْ قَوْمِهِ لِلَّذِينَ اسْتُضْعِفُوا لِمَنْ آمَنَ مِنْهُمْ، أَتَعْلَمُونَ أَنَّ صَالِحًا مُرْسَلٌ مِنْ رَبِّهِ؟ قَالُوا إِنَّا بِمَا أُرْسِلَ بِهِ مُؤْمِنُونَ ۝ قَالَ الَّذِينَ اسْتَكْبَرُوا إِنَّا بِالَّذِي آمَنْتُمْ بِهِ كَافِرُونَ ۝ فَعَقَرُوا النَّاقَةَ وعَتَوْا عَنْ أَمْرِ رَبِّهِمْ، وَقَالُوا يَا صَالِحُ ائْتِنَا بِمَا تَعِدُنَا إِنْ كُنْتَ مِنَ الْمُرْسَلِينَ ۝ فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ ۝ فَتَوَلَّى عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْت لكم وَلَكِن لَا تحبون الناصحين.',
    'وَالْمَقْصُودُ الْآنَ ذِكْرُ قِصَّتِهِمْ وَمَا كَانَ مِنْ أَمْرِهِمْ، وَكَيْفَ نَجَّى اللَّهُ نَبِيَّهُ صَالِحًا عَلَيْهِ السَّلَامُ وَمَنْ آمَنَ بِهِ، وَكَيْفَ قَطَعَ دَابِرَ الْقَوْمِ الَّذِينَ ظَلَمُوا بِكُفْرِهِمْ وعتوهم، ومخالفتهم رسولهم عَلَيْهِ السَّلَام.',
    'وَلِهَذَا قَالَ لَهُمْ نَبِيُّهُمْ عَلَيْهِ السَّلَامُ: «ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ ۝ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ» أَيْ إِنَّمَا جَعَلَكُمْ خُلَفَاءَ مِنْ بَعْدِهِمْ لِتَعْتَبِرُوا بِمَا كَانَ مِنْ أَمْرِهِمْ، وَتَعْمَلُوا بِخِلَافِ عَمَلِهِمْ.',
    'وَأَبَاحَ لَكُمْ هَذِهِ الْأَرْضَ تَبْنُونَ فِي سُهُولِهَا الْقُصُور، «وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ» أَيْ حَاذِقِينَ فِي صَنْعَتِهَا وَإِتْقَانِهَا وَإِحْكَامِهَا.',
    'فَقَابِلُوا نِعْمَةَ اللَّهِ بِالشُّكْرِ وَالْعَمَلِ الصَّالِحِ، وَالْعِبَادَةِ لَهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَإِيَّاكُمْ وَمُخَالَفَتَهُ وَالْعُدُولَ عَنْ طَاعَتِهِ، فَإِنَّ عَاقِبَةَ ذَلِكَ وَخِيمَةٌ.',
    'وَلِهَذَا وعظهم بقوله: «فِي مَا هَٰهُنَآ ءَامِنِينَ ۝ فِي جَنَّٰتٖ وَعُيُونٖ ۝ وَزُرُوعٖ وَنَخۡلٖ طَلۡعُهَا هَضِيمٞ» أَيْ مُتَرَاكِمٌ كَثِيرٌ حَسَنٌ بَهِيٌّ نَاضِجٌ.',
    '«وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ ۝ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ۝ وَلَا تُطِيعُوٓاْ أَمۡرَ ٱلۡمُسۡرِفِينَ ۝ ٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ».',
    'وَقَالَ لَهُمْ أَيْضًا: «قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا» أَيْ هُوَ الَّذِي خَلَقَكُمْ فَأَنْشَأَكُمْ مِنَ الْأَرْضِ، وَجَعَلَكُمْ عُمَّارَهَا، أَيْ أَعْطَاكُمُوهَا بِمَا فِيهَا مِنَ الزروع وَالثِّمَار، فَهُوَ الْخَالِق الرَّزَّاق، وَهُوَ الذى يسْتَحق الْعِبَادَة وَحده لَا مَا سِوَاهُ.',
    '«فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ» أَيْ أَقْلِعُوا عَمَّا أَنْتُمْ فِيهِ وَأَقْبِلُوا عَلَى عِبَادَتِهِ، فَإِنَّهُ يَقْبَلُ مِنْكُمْ وَيَتَجَاوَزُ عَنْكُمْ «إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ».',
    '«قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ» أَيْ قَدْ كُنَّا نَرْجُو أَنْ يَكُونَ عَقْلُكَ كَامِلًا قَبْلَ هَذِهِ الْمَقَالَةِ، وَهِيَ دُعَاؤُكَ إِيَّانَا إِلَى إِفْرَاد الْعِبَادَة، وَتَرْكِ مَا كُنَّا نَعْبُدُهُ مِنَ الْأَنْدَادِ، وَالْعُدُولِ عَنْ دِينِ الْآبَاءِ وَالْأَجْدَادِ وَلِهَذَا قَالُوا: «أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ».',
    '«قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ».',
    'وَهَذَا تَلَطُّفٌ مِنْهُ لَهُمْ فِي الْعِبَارَةِ وَلِينِ الْجَانِبِ، وَحُسْنُ تَأَتٍّ فِي الدَّعْوَةِ لَهُمْ إِلَى الْخَيْر.',
    'أَي فَمَا ظنكم إِنْ كَانَ الْأَمْرُ كَمَا أَقُولُ لَكُمْ وَأَدْعُوكُمْ إِلَيْهِ؟ مَاذَا عُذْرُكُمْ عِنْدَ اللَّهِ؟ وَمَاذَا يُخَلِّصُكُمْ بَيْنَ يَدَيْهِ وَأَنْتُمْ تَطْلُبُونَ مِنِّي أَنْ أَتْرُكَ دُعَاءَكُمْ إِلَى طَاعَتِهِ؟ وَأَنَا لَا يُمْكِنُنِي هَذَا لِأَنَّهُ وَاجِبٌ عَلَيَّ، وَلَوْ تَرَكْتُهُ لَمَا قَدَرَ أَحَدٌ مِنْكُمْ وَلَا مِنْ غَيْرِكُمْ أَنْ يُجِيرَنِي مِنْهُ وَلَا يَنْصُرَنِي.',
    'فَأَنَا لَا أَزَالُ أَدْعُوكُمْ إِلَى اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ، حَتَّى يَحْكُمَ اللَّهُ بَيْنِي وَبَيْنَكُمْ.',
    'وَقَالُوا لَهُ أَيْضًا: «إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ» أَيْ مِنَ الْمَسْحُورِينَ، يَعْنُونَ مَسْحُورًا لَا تَدْرِي مَا تَقُولُ فِي دُعَائِكَ إِيَّانَا إِلَى إِفْرَادِ الْعِبَادَةِ لِلَّهِ وَحْدَهُ، وَخَلْعِ مَا سِوَاهُ مِنَ الانداد.',
    '«قَالَ هَٰذِهِۦ نَاقَةٞ لَّهَا شِرۡبٞ وَلَكُمۡ شِرۡبُ يَوۡمٖ مَّعۡلُومٖ ۝ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابُ يَوۡمٍ» كَمَا قَالَ: «قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ» وَقَالَ تَعَالَى: «وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ» وَقَدْ ذَكَرَ الْمُفَسِّرُونَ أَنَّ ثَمُودَ اجْتَمَعُوا يَوْمًا فِي نَادِيهِمْ، فَجَاءَهُمْ رَسُولُ اللَّهِ صَالِحٌ فَدَعَاهُمْ إِلَى اللَّهِ، وَذَكَّرَهُمْ وَحَذَّرَهُمْ وَوَعَظَهُمْ وَأَمَرَهُمْ، فَقَالُوا لَهُ: إِنْ أَنْتَ أَخْرَجْتَ لَنَا مِنْ هَذِهِ الصَّخْرَةِ - وَأَشَارُوا إِلَى صَخْرَةٍ هُنَاكَ - نَاقَةً، مِنْ صفتهَا كَيْت وَكَيْت وَذكروا أوصافا يسموها وَنَعَتُوهَا وَتَعَنَّتُوا فِيهَا.',
    'وَلِهَذَا قَالَ: “فَظَلَمُوا بِهَا” أَيْ جَحَدُوا بِهَا وَلَمْ يَتَّبِعُوا الْحَقَّ بِسَبَبِهَا، أَيْ أَكْثَرُهُمْ.',
    'فَاتَّفَقَ الْحَالُ عَلَى أَنْ تَبْقَى هَذِهِ النَّاقَةُ بَيْنَ أَظْهُرِهِمْ، تَرْعَى حَيْثُ شَاءَتْ مِنْ أَرْضِهِمْ، وَتَرِدُ الْمَاءَ يَوْمًا بَعْدَ يَوْمٍ، وَكَانَتْ إِذَا وَرَدَتِ الْمَاءَ تَشْرَبُ مَاءَ الْبِئْرِ يَوْمَهَا ذَلِكَ، فَكَانُوا يَرْفَعُونَ حَاجَتَهُمْ مِنَ الْمَاءِ فِي يَوْمِهِمْ لِغَدِهِمْ.',
    'وَلِهَذَا قَالَ تَعَالَى: «إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ» أَيِ اخْتِبَارًا لَهُمْ أَيُؤْمِنُونَ بِهَا أَمْ يَكْفُرُونَ؟ وَالله أعلم بِمَا يَفْعَلُونَ.',
    '“فارتقبهم” أَيِ انْتَظِرْ مَا يَكُونُ مِنْ أَمْرِهِمْ “وَاصْطَبِرْ” عَلَى أَذَاهُمْ فَسَيَأْتِيكَ الْخَبَرُ عَلَى جَلِيَّةٍ.',
    '«وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبٖ مُّحۡتَضَرٞ».',
    'فَلَمَّا طَال عَلَيْهِم هَذَا الْحَال اجْتمع مأوهم، وَاتَّفَقَ رَأْيُهُمْ عَلَى أَنْ يَعْقِرُوا هَذِهِ النَّاقَةَ، لِيَسْتَرِيحُوا مِنْهَا وَيَتَوَفَّرَ عَلَيْهِمْ مَاؤُهُمْ، وَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ.',
    'قَالَ اللَّهُ تَعَالَى: «فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ».',
    'قَالَ اللَّهُ تَعَالَى: «فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ ۝ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ».',
    'وَقَالَ الله تَعَالَى: «إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا ۝ فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا» أَيِ احْذَرُوهَا «فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا ۝ وَلَا يَخَافُ عُقۡبَٰهَا».',
    'وَقَالَ تَعَالَى: «فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ».',
    'فَجَمَعُوا فِي كَلَامِهِمْ هَذَا بَيْنَ كُفْرٍ بَلِيغٍ مِنْ وُجُوهٍ: مِنْهَا: أَنَّهُمْ خَالَفُوا اللَّهَ وَرَسُولَهُ فِي ارْتِكَابِهِمُ النَّهْيَ الْأَكِيدَ فِي عَقْرِ النَّاقَةِ الَّتِي جَعَلَهَا اللَّهُ لَهُمْ آيَةً.',
    'وَمِنْهَا: أَنَّهُمُ اسْتَعْجَلُوا وُقُوعَ الْعَذَابِ بِهِمْ فَاسْتَحَقُّوهُ مِنْ وَجْهَيْنِ: أَحَدُهُمَا الشَّرْطُ عَلَيْهِمْ فِي قَوْلِهِ: «وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ» وَفِي آيَةٍ “عَظِيمٌ” وَفِي الْأُخْرَى “أَلِيمٌ” وَالْكُلُّ حَقٌّ.',
    'وَالثَّانِي اسْتِعْجَالُهُمْ عَلَى ذَلِكَ.',
    'وَمِنْهَا: أَنَّهُمْ كَذَّبُوا الرَّسُولَ الَّذِي قَدْ قَامَ الدَّلِيلُ الْقَاطِعُ عَلَى نُبُوَّتِهِ وَصِدْقِهِ، وَهُمْ يَعْلَمُونَ ذَلِكَ عِلْمًا جَازِمًا، وَلَكِنْ حَمَلَهُمُ الْكُفْرُ وَالضَّلَالُ وَالْعِنَادُ عَلَى اسْتِبْعَادِ الْحَقِّ وَوُقُوعِ الْعَذَابِ بِهِمْ.',
    'قَالَ اللَّهُ تَعَالَى: «فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ».',
    'فَلِهَذَا قَالَ لَهُمْ صَالِحٌ: «تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ» أَي غير يَوْمِهِمْ ذَلِكَ، فَلَمْ يُصَدِّقُوهُ أَيْضًا فِي هَذَا الْوَعْدِ الْأَكِيدِ.',
    'بَلْ لَمَّا أَمْسَوْا هَمُّوا بِقَتْلِهِ وَأَرَادُوا - فِيمَا يَزْعُمُونَ - أَنْ يُلْحِقُوهُ بِالنَّاقَةِ.',
    '«قَالُواْ تَقَاسَمُواْ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهۡلَهُۥ» أَيْ لَنَكْبِسَنَّهُ فِي دَارِهِ مَعَ أَهْلِهِ فَلَنَقْتُلَنَّهُ، ثمَّ نجحدن قَتله ولننكرن ذَلِكَ إِنْ طَالَبَنَا أَوْلِيَاؤُهُ بِدَمِهِ.',
    'وَلِهَذَا قَالُوا: «ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَٰدِقُونَ» قَالَ اللَّهُ تَعَالَى: «وَمَكَرُواْ مَكۡرٗا وَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ ۝ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِينَ ۝ فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ۝ وَأَنجَيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ».',
    'فَلَمَّا أَشْرَقَتِ الشَّمْسُ جَاءَتْهُمْ صَيْحَةٌ مِنَ السَّمَاءِ مِنْ فَوْقِهِمْ، وَرَجْفَةٌ مِنْ أَسْفَلَ مِنْهُمْ، فَفَاضَتِ الْأَرْوَاحُ وَزَهَقَتِ النُّفُوسُ، وَسَكَنَتِ الْحَرَكَاتُ، وَخَشَعَتِ الْأَصْوَاتُ، وَحُقَّتِ الْحَقَائِقُ، فَأَصْبَحُوا فِي دَارهم جاثمين، جُثَثًا لَا أَرْوَاحَ فِيهَا وَلَا حِرَاكَ بِهَا.',
    'قَالَ الله تَعَالَى: «كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ» أَيْ لَمْ يُقِيمُوا فِيهَا فِي سَعَةٍ وَرِزْقٍ وَغَنَاءٍ، «أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ» أَيْ نَادَى عَلَيْهِمْ لِسَانُ الْقَدَرِ بِهَذَا.',
    'وَقَوْلُهُ تَعَالَى: «فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ» إِخْبَار عَن صَالح عَلَيْهِ السَّلَام، أَنَّهُ خَاطَبَ قَوْمَهُ بَعْدَ هَلَاكِهِمْ، وَقَدْ أَخَذَ فِي الذَّهَابِ عَنْ مَحِلَّتِهِمْ إِلَى غَيْرِهَا قَائِلًا لَهُمْ: «وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ» أَيْ جَهَدْتُ فِي هِدَايَتِكُمْ بِكُلِّ مَا أَمْكَنَنِي، وَحَرَصْتُ عَلَى ذَلِكَ بِقَوْلِي وَفِعْلِي وَنِيَّتِي.',
    '«وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ» أَيْ لَمْ تَكُنْ سَجَايَاكُمْ تَقْبَلُ الْحَقَّ وَلَا تُرِيدُهُ، فَلِهَذَا صِرْتُمْ إِلَى مَا أَنْتُمْ فِيهِ مِنَ الْعَذَابِ الْأَلِيمِ، الْمُسْتَمِرِّ بِكُمُ الْمُتَّصِلِ إِلَى الْأَبَدِ، وَلَيْسَ لِي فِيكُمْ حِيلَةٌ وَلَا لِي بِالدَّفْعِ عَنْكُمْ يَدَانِ.',
    'وَالَّذِي وَجَبَ عَلَيَّ مِنْ أَدَاءِ الرِّسَالَةِ وَالنُّصْحِ لَكُمْ قَدْ فَعَلْتُهُ وَبَذَلْتُهُ لَكُمْ، وَلَكِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ.',
    'وَهَكَذَا خَاطَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْلَ قَلِيبِ بَدْرٍ بَعْدَ ثَلَاثِ لَيَالٍ: وَقَفَ عَلَيْهِمْ وَقَدْ رَكِبَ رَاحِلَتَهُ وَأَمَرَ بِالرَّحِيلِ مِنْ آخِرِ اللَّيْلِ فَقَالَ: “يَا أَهْلَ الْقَلِيبِ هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا؟ فَإِنِّي قَدْ وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا” وَقَالَ لَهُمْ فِيمَا قَالَ: “بِئْسَ عَشِيرَةُ النَّبِيِّ كُنْتُمْ لِنَبِيِّكُمْ، كَذَّبْتُمُونِي وَصَدَّقَنِي النَّاسُ، وَأَخْرَجْتُمُونِي وَآوَانِي النَّاسُ، وَقَاتَلْتُمُونِي وَنَصَرَنِي النَّاسُ، فَبِئْسَ عَشِيرَةُ النَّبِيِّ كُنْتُمْ لِنَبِيِّكُمْ”.',
    'فَقَالَ لَهُ عُمَرُ: يَا رَسُولَ اللَّهِ تُخَاطِبُ أَقْوَامًا قَدْ جَيَّفُوا؟ فَقَالَ: “وَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ، وَلَكِنَّهُمْ لَا يجيبون”.',
  ];

  static const List<String> _p12 = [
    'قَالَ اللَّهُ تَعَالَى: «وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ ۝ فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ» وَقَالَ تَعَالَى فِي سُورَة ص «وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ ۝ ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ ۝ وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ ۝ وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ».',
    'قَالَ عُلَمَاءُ التَّفْسِيرِ وَالتَّارِيخِ وَغَيْرُهُمْ: كَانَ أَيُّوبُ رَجُلًا كَثِيرَ الْمَالِ مِنْ سَائِرِ صُنُوفِهِ وَأَنْوَاعِهِ ; مِنَ الْأَنْعَامِ وَالْعَبِيدِ وَالْمَوَاشِي، والاراضي المتسعة بِأَرْض الثَّنية مِنْ أَرْضِ حُورَانَ.',
    'فسلب مِنْهُ ذَلِك جَمِيعه، وابتلى فِي جسده بأنواع من الْبَلَاءِ وَلَمْ يَبْقَ مِنْهُ عُضْوٌ سَلِيمٌ سِوَى قَلْبِهِ وَلِسَانِهِ، يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ بِهِمَا.',
    'وَهُوَ فِي ذَلِكَ كُلِّهِ صَابِرٌ مُحْتَسِبٌ، ذَاكِرٌ لله عزوجل فِي لَيْلِهِ وَنَهَارِهِ وَصَبَاحِهِ وَمَسَائِهِ.',
    'وَطَالَ مَرَضُهُ حَتَّى عَافَهُ الْجَلِيسُ، وَأَوْحَشَ مِنْهُ الْأَنِيسُ، وَأُخْرِجَ مِنْ بَلَدِهِ وَأُلْقِيَ عَلَى مَزْبَلَةٍ خَارِجَهَا، وَانْقَطَعَ عَنْهُ النَّاسُ، وَلَمْ يَبْقَ أَحَدٌ يَحْنُو عَلَيْهِ سِوَى زَوْجَتِهِ، كَانَتْ تَرْعَى لَهُ حَقَّهُ، وَتَعْرِفُ قَدِيمَ إِحْسَانِهِ إِلَيْهَا وَشَفَقَتِهِ عَلَيْهَا.',
    'فَكَانَتْ تَتَرَدَّدُ إِلَيْهِ فَتُصْلِحُ مِنْ شَأْنِهِ، وَتُعِينُهُ عَلَى قَضَاءِ حَاجَتِهِ وَتَقُومُ بِمَصْلَحَتِهِ.',
    'وَضَعُفَ حَالُهَا وَقَلَّ مَالُهَا حَتَّى كَانَتْ تَخْدِمُ النَّاسَ بِالْأَجْرِ ; لِتُطْعِمَهُ وَتَقُومَ بأوده، رضى الله عمنها وأرضاها، وهى صابرة مَعَه على ماحل بِهِمَا مِنْ فِرَاقِ الْمَالِ وَالْوَلَدِ، وَمَا يَخْتَصُّ بِهَا مِنَ الْمُصِيبَةِ بِالزَّوْجِ، وَضِيقِ ذَاتِ الْيَدِ وَخِدْمَةِ النَّاسِ، بَعْدَ السَّعَادَةِ وَالنِّعْمَةِ وَالْخِدْمَةِ وَالْحُرْمَةِ.',
    'فَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ! وَقَدْ ثَبَتَ فِي الصَّحِيحِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: “أَشَدُّ النَّاسِ بَلَاءً الْأَنْبِيَاءُ، ثُمَّ الصَّالِحُونَ، ثُمَّ الْأَمْثَلُ فَالْأَمْثَلُ”. وَقَالَ: “يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ، فَإِنْ كَانَ فِي دِينِهِ صَلَابَةٌ زِيدَ فِي بَلَائِهِ”. وَلَمْ يَزِدْ هَذَا كُلُّهُ أَيُّوبَ عَلَيْهِ السَّلَامُ إِلَّا صَبْرًا وَاحْتِسَابًا وَحَمْدًا وَشُكْرًا، حَتَّى إِنَّ الْمَثَلَ لَيُضْرَبُ بِصَبْرِهِ عَلَيْهِ السَّلَامُ، وَيُضْرَبُ الْمَثَلُ أَيْضًا بِمَا حَصَلَ لَهُ مِنْ أَنْوَاعِ الْبَلَايَا.',
    'وَقَوله: “اركض برجلك” أَيِ اضْرِبِ الْأَرْضَ بِرِجْلِكَ، فَامْتَثَلَ مَا أُمِرَ بِهِ.',
    'فَأَنْبَعَ اللَّهُ لَهُ عَيْنًا بَارِدَةَ الْمَاءِ، وَأُمِرَ أَنْ يَغْتَسِلَ فِيهَا وَيَشْرَبَ مِنْهَا، فَأَذْهَبَ الله عَنهُ مَا كَانَ يحده مِنَ الْأَلَمِ وَالْأَذَى، وَالسَّقَمِ وَالْمَرَضِ، الَّذِي كَانَ فِي جَسَدِهِ ظَاهِرًا وَبَاطِنًا، وَأَبْدَلَهُ اللَّهُ بَعْدَ ذَلِكَ كُلِّهِ صِحَّةً ظَاهِرَةً وَبَاطِنَةً، وَجَمَالًا تَامًّا وَمَالًا كَثِيرًا ; حَتَّى صَبَّ لَهُ مِنَ الْمَالِ صَبًّا، مَطَرًا عَظِيمًا جَرَادًا مِنْ ذَهَبٍ.',
    'وَأَخْلَفَ اللَّهُ لَهُ أَهْلَهُ، كَمَا قَالَ تَعَالَى: «وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ» فَقِيلَ أَحْيَاهُمُ اللَّهُ بِأَعْيَانِهِمْ، وَقِيلَ آجَرَهُ فِيمَنْ سَلَفَ، وَعَوَّضَهُ عَنْهُمْ فِي الدُّنْيَا بَدَلَهُمْ وَجَمَعَ لَهُ شَمْلَهُ بِكُلِّهِمْ فِي الدَّارِ الْآخِرَةِ.',
    'وَقَوْلُهُ: «رَحۡمَةٗ مِّنۡ عِندِنَا» أَي رفعنَا عَنْهُ شِدَّتَهُ، وَكَشَفْنَا مَا بِهِ مِنْ ضُرٍّ، رَحْمَةً مِنَّا بِهِ وَرَأْفَةً وَإِحْسَانًا.',
    '“وَذِكْرَى لِلْعَابِدِينَ” أَيْ تَذْكِرَةً لِمَنِ ابْتُلِيَ فِي جَسَدِهِ أَوْ مَالِهِ أَوْ وَلَدِهِ، فَلَهُ أُسْوَةٌ بِنَبِيِّ اللَّهِ أَيُّوبَ ; حَيْثُ ابْتَلَاهُ اللَّهُ بِمَا هُوَ أَعْظَمُ مِنْ ذَلِكَ فَصَبَرَ وَاحْتَسَبَ حَتَّى فَرَّجَ اللَّهُ عَنْهُ.',
    'وَقَوْلُهُ: «وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ» هَذِهِ رُخْصَةٌ مِنَ اللَّهِ تَعَالَى لِعَبْدِهِ وَرَسُولِهِ أَيُّوبَ عَلَيْهِ السَّلَامُ، فِيمَا كَانَ مِنْ حَلِفِهِ لَيَضْرِبَنَّ امْرَأَتَهُ مِائَةَ سَوْطٍ.',
    'فَلَمَّا عافاه الله عزوجل أَفْتَاهُ أَنْ يَأْخُذَ ضِغْثًا وَهُوَ كَالْعِثْكَالِ الَّذِي يَجْمَعُ الشَّمَارِيخَ، فَيَجْمَعَهَا كُلَّهَا وَيَضْرِبَهَا بِهِ ضَرْبَةً وَاحِدَةً، وَيَكُونُ هَذَا مُنْزَلًا مَنْزِلَةَ الضَّرْبِ بِمِائَةِ سَوْطٍ وَيَبَرُّ وَلَا يَحْنَثُ.',
    'وَهَذَا مِنَ الْفَرَجِ وَالْمَخْرَجِ لِمَنِ اتَّقَى اللَّهَ وَأَطَاعَهُ، وَلَا سِيَّمَا فِي حَقِّ امْرَأَتِهِ الصَّابِرَةِ الْمُحْتَسِبَةِ، الْمُكَابِدَةِ الصِّدِّيقَةِ البارة الراشدة، رضى الله عَنْهَا.',
    'وَلِهَذَا عقب الله الرُّخْصَةَ وَعَلَّلَهَا بِقَوْلِهِ: «إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ».',
  ];

  static const List<String> _p21 = [
    'قَالَ اللَّهُ تَعَالَى فِي سُورَةِ يُونُسَ: «فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ».',
    'وَقَالَ تَعَالَى فِي سُورَةِ الْأَنْبِيَاءِ: «وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ۝ فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ» وَقَالَ تَعَالَى فِي سُورَة وَالصَّافَّات: «وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ۝ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ۝ فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ ۝ فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ ۝ فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ۝ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ۝ ۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ ۝ وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ ۝ وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ ۝ فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ» وَقَالَ تَعَالَى فِي سُورَة ن: «فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ ۝ لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ ۝ فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ».',
    'قَالَ أهل التَّفْسِير: بعث الله يُونُس عَلَيْهِ السَّلَام إِلَى أهل “نِينَوَى” من أَرض الْموصل، فَدَعَاهُمْ إِلَى الله عزوجل، فَكَذَّبُوهُ وَتَمَرَّدُوا عَلَى كُفْرِهِمْ وَعِنَادِهِمْ، فَلَمَّا طَالَ ذَلِكَ عَلَيْهِ مَنْ أَمْرِهُمْ خَرَجَ مِنْ بَيْنِ أَظْهَرِهِمْ، وَوَعَدَهُمْ حُلُولَ الْعَذَابِ بِهِمْ بَعْدَ ثَلَاثٍ.',
    'فَكَشَفَ اللَّهُ الْعَظِيمُ بِحَوْلِهِ وَقُوَّتِهِ وَرَأْفَتِهِ وَرَحْمَتِهِ، عَنْهُمُ الْعَذَاب الذى كَانَ قد اتَّصل بهم سَببه، وَدَارَ عَلَى رُؤُوسِهِمْ كَقِطَعِ اللَّيْلِ الْمُظْلِمِ.',
    'وَلِهَذَا قَالَ تَعَالَى: «فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ» أَيْ هَلَّا وُجِدَتْ فِيمَا سَلَفَ مِنَ الْقُرُونِ قَرْيَةٌ آمَنَتْ بِكَمَالِهَا، فَدَلَّ عَلَى أَنَّهُ لَمْ يَقَعْ ذَلِكَ، بَلْ كَمَا قَالَ تَعَالَى: «وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ».',
    'وَقَوْلُهُ: «إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ» أَيْ آمَنُوا بِكَمَالِهِمْ.',
    'وَاللَّهُ أَعْلَمُ، كَمَا قَالَ تَعَالَى: “لَمَّا آمَنُوا” وَقَالَ تَعَالَى: «وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ ۝ فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ»، وَهَذَا الْمَتَاعُ إِلَى حِينٍ لَا يَنْفِي أَنْ يَكُونَ مَعَهُ غَيْرُهُ مِنْ رَفْعِ الْعَذَابِ الْأُخْرَوِيِّ، وَاللَّهُ أَعْلَمُ.',
    'وَقَدْ كَانُوا مِائَةَ أَلْفٍ لَا مَحَالَةَ.',
    'وَالْمَقْصُودُ أَنَّهُ عَلَيْهِ السَّلَامُ لَمَّا ذَهَبَ مُغَاضِبًا بِسَبَبِ قَوْمِهِ، رَكِبَ سَفِينَةً فِي الْبَحْرِ فَلَجَّتْ بِهِمْ، وَاضْطَرَبَتْ وَمَاجَتْ بِهِمْ وَثَقُلَتْ بِمَا فِيهَا، وَكَادُوا يَغْرَقُونَ عَلَى مَا ذَكَرَهُ الْمُفَسِّرُونَ.',
    'قَالُوا: فَاشْتَوَرُوا فِيمَا بَيْنَهُمْ عَلَى أَنْ يَقْتَرِعُوا، فَمَنْ وَقَعَتْ عَلَيْهِ الْقُرْعَةُ أَلْقَوْهُ مِنَ السَّفِينَةِ لِيَتَخَفَّفُوا مِنْهُ.',
    'فَلَمَّا اقْتَرَعُوا وَقَعَتِ الْقُرْعَةُ عَلَى نَبِيِّ اللَّهِ يُونُسَ فَلَمْ يَسْمَحُوا بِهِ، فَأَعَادُوهَا ثَانِيَةً فَوَقَعَتْ عَلَيْهِ أَيْضًا، فَشَمَّرَ لِيَخْلَعَ ثِيَابَهُ وَيُلْقِيَ بِنَفْسِهِ، فَأَبَوْا عَلَيْهِ ذَلِكَ.',
    'ثُمَّ أَعَادُوا الْقُرْعَةَ ثَالِثَةً فَوَقَعَتْ عَلَيْهِ أَيْضًا، لِمَا يُرِيدُهُ اللَّهُ بِهِ مِنَ الْأَمْرِ الْعَظِيمِ.',
    'قَالَ اللَّهُ تَعَالَى: «وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ۝ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ۝ فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ ۝ فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ».',
    'وَذَلِكَ أَنَّهُ لَمَّا وَقَعَتْ عَلَيْهِ الْقُرْعَةُ أُلْقِيَ فِي الْبَحْر، وَبعث الله عزوجل حُوتًا عَظِيمًا مِنَ الْبَحْرِ الْأَخْضَرِ فَالْتَقَمَهُ وَأَمَرَهُ الله تَعَالَى أَن لَا يَأْكُل لَهُ لَحْمًا وَلَا يهشم لَهُ عَظْمًا فَلَيْسَ لَكَ بِرِزْقٍ، فَأَخْذَهُ فَطَافَ بِهِ الْبِحَارَ كُلَّهَا.',
    'وَالْمَقْصُودُ أَنَّهُ لَمَّا جُعِلَ الْحُوتُ يَطُوفُ بِهِ فِي قَرَارِ الْبِحَارِ اللُّجِّيَّةِ، وَيَقْتَحِمُ بِهِ لُجَجَ الْمَوْجِ الْأُجَاجِيِّ، فَسَمِعَ تَسْبِيحَ الْحِيتَانِ لِلرَّحْمَنِ، وَحَتَّى سَمِعَ تَسْبِيحَ الْحَصَى لِفَالِقِ الْحَبِّ والنوى، وَرب السَّمَوَات السَّبْعِ وَالْأَرْضِينَ السَّبْعِ وَمَا بَيْنَهَا وَمَا تَحْتَ الثَّرَى.',
    'فَعِنْدَ ذَلِكَ وَهُنَالِكَ، قَالَ مَا قَالَ بِلِسَانِ الْحَالِ وَالْمَقَالِ، كَمَا أَخْبَرَ عَنْهُ ذُو الْعِزَّةِ وَالْجَلَالِ، الَّذِي يَعْلَمُ السِّرَّ وَالنَّجْوَى، وَيَكْشِفُ الضُّرَّ وَالْبَلْوَى، سَامِعُ الْأَصْوَاتِ وَإِنْ ضَعُفَتْ، وَعَالِمُ الْخِفْيَاتِ وَإِنْ دَقَّتْ، وَمُجِيبُ الدَّعَوَاتِ وَإِنْ عَظُمَتْ، حَيْثُ قَالَ فِي كِتَابِهِ الْمُبِينِ، الْمُنَزَّلِ عَلَى رَسُولِهِ الْأَمِينِ، وَهُوَ أَصْدَقُ الْقَائِلِينَ وَرَبُّ الْعَالَمِينَ وإله الْمُرْسلين: «وَذَا ٱلنُّونِ إِذ ذَّهَبَ» أَي إِلَى أَهله «مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ۝ فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ» «فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ» أَي نضيق عَلَيْهِ.',
    'وَقَوْلُهُ تَعَالَى: «فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ۝ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ» قيل مَعْنَاهُ فلولا أَنَّهُ سَبَّحَ اللَّهَ هُنَالِكَ، وَقَالَ مَا قَالَ مِنَ التَّهْلِيلِ وَالتَّسْبِيحِ، وَالِاعْتِرَافِ لِلَّهِ بِالْخُضُوعِ، وَالتَّوْبَةِ إِلَى وَالرُّجُوعِ إِلَيْهِ، لَلَبِثَ هُنَالِكَ إِلَى يَوْمِ الْقِيَامَةِ، وَلَبُعِثَ مِنْ جَوْفِ ذَلِكَ الْحُوتِ.',
    'وَقد قَالَ الله تَعَالَى: “فنبذناه” أَيْ أَلْقَيْنَاهُ “بِالْعَرَاءِ” وَهُوَ الْمَكَانُ الْقَفْرُ الَّذِي لَيْسَ فِيهِ شئ مِنَ الْأَشْجَارِ، بَلْ هُوَ عَارٍ مِنْهَا، “وَهُوَ سقيم”',
    'وَلِهَذَا قَالَ تَعَالَى: «فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ» أَيِ الْكَرْبِ وَالضِّيقِ الَّذِي كَانَ فِيهِ «وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ» أَي وَهَذَا صنيعنا بِكُل من دَعَانَا وَاسْتَجَارَ بِنَا.',
    'قَالَ سَعْدٌ: فَأَنَا أُنْبِئُكَ بِهَا، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ لَنَا أَوَّلَ دَعْوَةٍ، ثُمَّ جَاءَ أَعْرَابِيٌّ فَشَغَلَهُ حَتَّى قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاتَّبَعْتُهُ، فَلَمَّا أَشْفَقْتُ أَنْ يَسْبِقَنِي إِلَى مَنْزِلِهِ ضَرَبْتُ بِقَدَمِي الْأَرْضَ، فَالْتَفَتَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «مِّنۡ هَٰذَا بَلۡ كُنَّا» قَالَ: قُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ: “خه؟ قُلْتُ لَا وَاللَّهِ، إِلَّا أَنَّكَ ذَكَرْتَ لَنَا أَوَّلَ دَعْوَةٍ، ثُمَّ جَاءَ هَذَا الْأَعْرَابِيُّ فَشَغَلَكَ.”',
    'قَالَ: “نَعَمْ، دَعْوَةُ ذِي النُّونِ إِذْ هُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ، فَإِنَّهُ لَمْ يَدْعُ بِهَا مُسْلِمٌ رَبَّهُ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ لَهُ”.',
    'قَالَ اللَّهُ تَعَالَى: «وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ» وَذكره تَعَالَى فِي جملَة الأنبياء الكرام و فِي سورتي النِّسَاء والانعام، عَلَيْهِمْ مِنَ اللَّهِ أَفْضَلُ الصَّلَاةِ وَالسَّلَامِ.',
  ];

  static const List<String> _p22 = [
    'قَالَ اللَّهُ تَعَالَى فِي سُورَةِ مَرْيَمَ:',
    '«ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ ۝ إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا ۝ قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ۝ وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا ۝ يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا ۝ يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا ۝ قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا ۝ قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٞ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَيۡـٔٗا ۝ قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٖ سَوِيّٗا ۝ فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا»',
    'وَقَالَ تَعَالَى فِي سُورَةِ آلِ عِمْرَانَ:',
    '«وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ ۝ هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ ۝ فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ ۝ قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ ۝ قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ»',
    'وَقَالَ تَعَالَى فِي سُورَةِ الْأَنْبِيَاءِ:',
    '«وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ ۝ فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ»',
    'فَلَمَّا بُشِّرَ بِالْوَلَدِ وَتَحَقَّقَ الْبِشَارَةَ شَرَعَ يَسْتَعْلِمُ على وَجه التَّعَجُّب وجود الْوَلَد لَهُ وَالْحَالة هَذِه «قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا» أَيْ كَيْفَ يُوجَدُ وَلَدٌ مِنْ شَيْخٍ كَبِيرٍ، قِيلَ كَانَ عُمْرُهُ إِذْ ذَاكَ سَبْعًا وَسَبْعِينَ سَنَةً، وَالْأَشْبَهُ وَاللَّهُ أَعْلَمُ أَنَّهُ كَانَ أَسَنَّ من ذَلِك «وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا» يَعْنِي وَقَدْ كَانَتِ امْرَأَتِي فِي حَالِ شَبِيبَتِهَا عَاقِرًا لَا تَلِدُ.',
    '«قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ» أَيْ عَلَامَةً عَلَى وَقْتَ تَعْلَقُ مِنِّي الْمَرْأَةُ بِهَذَا الْوَلَد المبشر بِهِ «قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٖ سَوِيّٗا» يَقُولُ عَلَامَةُ ذَلِكَ أَنْ يَعْتَرِيَكَ سَكْتٌ لَا تَنْطِقُ مَعَهُ ثَلَاثَةَ أَيَّامٍ إِلَّا رَمْزًا وَأَنْتَ فِي ذَلِكَ سَوِيُّ الْخَلْقِ صَحِيحُ الْمِزَاجِ مُعْتَدِلُ الْبِنْيَةِ.',
    'وَأُمِرَ بِكَثْرَةِ الذِّكْرِ فِي هَذِهِ الْحَالِ بِالْقَلْبِ وَاسْتِحْضَارِ ذَلِكَ بِفُؤَادِهِ بِالْعَشِيِّ وَالْإِبْكَارِ، فَلَمَّا بُشِّرَ بِهَذِهِ الْبِشَارَةِ خَرَجَ مَسْرُورًا بِهَا عَلَى قَوْمِهِ مِنْ مِحْرَابِهِ «فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا» وَالْوَحْيُ هَاهُنَا هُوَ الْأَمْرُ الْخَفِيُّ إِمَّا بِكِتَابَةٍ، كَمَا قَالَهُ مُجَاهِدٌ وَالسُّدِّيُّ، أَوْ إِشَارَةٍ كَمَا قَالَهُ مُجَاهِدٌ أَيْضًا وَوَهْبٌ وَقَتَادَةُ.',
  ];

  static const List<String> _p23 = [
    'قَالَ اللَّهُ تَعَالَى فِي سُورَةِ مَرْيَمَ:',
    '«يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا ۝ وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا ۝ وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا ۝ وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا»',
    'وَقَوْلُهُ تَعَالَى: «يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا» يُخْبِرُ تَعَالَى عَنْ وُجُودِ الْوَلَدِ وَفْقَ الْبِشَارَةِ الْإِلَهِيَّةِ لِأَبِيهِ زَكَرِيَّا عَلَيْهِ السَّلَامُ وَأَنَّ اللَّهَ عَلَّمَهُ الْكِتَابَ وَالْحِكْمَةَ وَهُوَ صَغِيرٌ فِي حَالِ صِبَاهُ.',
    'وَأَمَّا الزَّكَاةُ فَهُوَ طَهَارَةُ الْخُلُقِ وَسَلَامَتُهُ مِنَ النَّقَائِصِ وَالرَّذَائِلِ.',
    'وَالتَّقْوَى طَاعَةُ اللَّهِ بِامْتِثَالِ أَوَامِرِهِ وَتَرْكِ زَوَاجِرِهِ.',
    'ثُمَّ ذَكَرَ بِرَّهُ بِوَالِدَيْهِ وَطَاعَتَهُ لَهُمَا أَمْرًا وَنَهْيًا وَتَرْكَ عُقُوقِهِمَا قَوْلًا وَفِعْلًا فَقَالَ: «وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا» ثُمَّ قَالَ: «وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا» هَذِهِ الْأَوْقَاتُ الثَّلَاثَةُ أَشَدُّ مَا تَكُونُ عَلَى الْإِنْسَانِ، فَإِنَّهُ يَنْتَقِلُ فِي كُلٍّ مِنْهَا مِنْ عَالَمٍ إِلَى عَالَمٍ آخَرَ، فَيَفْقِدُ الْأَوَّلَ بَعْدَ مَا كَانَ أَلِفَهُ وَعَرَفَهُ وَيَصِيرُ إِلَى الْآخَرِ وَلَا يَدْرِي مَا بَيْنَ يَدَيْهِ، وَلِهَذَا يَسْتَهِلُّ صَارِخًا إِذَا خَرَجَ مِنْ بَيْنِ الْأَحْشَاءِ وَفَارَقَ لِينَهَا وَضَمَّهَا وَيَنْتَقِلُ إِلَى هَذِهِ الدَّارِ لِيُكَابِدَ همومها وغمها! وَكَذَلِكَ إِذَا فَارَقَ هَذِهِ الدَّارَ وَانْتَقَلَ إِلَى عَالَمِ الْبَرْزَخِ بَيْنَهَا وَبَيْنَ دَارِ الْقَرَارِ، وَصَارَ بَعْدَ الدُّورِ وَالْقُصُورِ إِلَى عَرْصَةِ الْأَمْوَاتِ سُكَّانِ الْقُبُورِ، وَانْتَظَرَ هُنَاكَ النَّفْخَةَ فِي الصُّوَرِ لِيَوْمِ الْبَعْثِ وَالنُّشُورِ، فَمِنْ مَسْرُورٍ وَمَحْبُورٍ وَمِنْ مَحْزُونٍ ومثبور، وَمَا بَين جُبَير وكسير وَفَرِيقٍ فِي الْجَنَّةِ وَفَرِيقٍ فِي السَّعِيرِ! وَلَقَدْ أحسن بعض الشُّعَرَاء حَيْثُ يَقُول: وَلَدَتْكَ أُمُّكَ بَاكِيًا مُسْتَصْرِخًا ۝ وَالنَّاسُ حَوْلَكَ يَضْحَكُونَ سُرَورًا',
  ];

  static const List<String> _p24 = [
    'قَالَ اللَّهُ تَعَالَى:',
    '«مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ»',
    'وَقَدْ تَقَدَّمَ مَا ثَبَتَ فِي الصَّحِيحَيْنِ: “مَا مِنْ مَوْلُودٍ إِلَّا وَالشَّيْطَانُ يَطْعَنُ فِي خَاصِرَتِهِ حِينَ يُولَدُ فَيَسْتَهِلُّ صَارِخًا إِلَّا مَرْيَمَ وَابْنَهَا، ذَهَبَ يَطْعَنُ فَطَعْنَ فِي الْحِجَابِ” وَتَقَدَّمَ حَدِيثُ عُمَيْرِ بْنِ هَانِئٍ عَنْ جُنَادَةَ، عَنْ عُبَادَةَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ “مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شريك لَهُ وَأَن مُحَمَّدًا عبد الله وَرَسُولُهُ وَأَنَّ عِيسَى عَبْدُ اللَّهِ وَرَسُولُهُ وَكَلِمَتُهُ الَّتِي أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ، وَالْجَنَّةَ حَقٌّ وَالنَّارَ حَقٌّ أَدْخَلَهُ اللَّهُ الْجَنَّةَ عَلَى مَا كَانَ مِنَ الْعَمَلِ”.',
    '«قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ»',
    '«وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ»',
    'وَقَالَ تَعَالَى فِي رَفْعِهِ إِلَى السَّمَاءِ:',
    '«وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ ۝ إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ»',
    '«فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا ۝ وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا ۝ وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا ۝ بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ۝ وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا»',
    'فَأَخْبَرَ تَعَالَى أَنَّهُ رَفَعَهُ إِلَى السَّمَاءِ بَعْدَ مَا تَوَفَّاهُ بِالنَّوْمِ عَلَى الصَّحِيحِ الْمَقْطُوعِ بِهِ، وَخَلَّصَهُ مِمَّنْ كَانَ أَرَادَ أَذِيَّتَهُ مِنَ الْيَهُودِ الَّذِينَ وَشَوْا بِهِ إِلَى بَعْضِ الْمُلُوكِ الْكَفَرَةِ فِي ذَلِك الزَّمَان.',
    'وَأَخْبَرَ تَعَالَى بِقَوْلِهِ: «وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ» أَيْ بَعْدَ نُزُولِهِ إِلَى الْأَرْضِ فِي آخِرِ الزَّمَانِ قَبْلَ قِيَامِ السَّاعَةِ، فَإِنَّهُ يَنْزِلُ وَيَقْتُلُ الْخِنْزِيرَ وَيَكْسِرُ الصَّلِيبَ وَيَضَعُ الْجِزْيَةَ وَلَا يَقْبَلُ إِلَّا الْإِسْلَامَ.',
    'وَهَذَا يَدُلُّ عَلَى سَجِيَّةٍ طَاهِرَةٍ، حَيْثُ قَدَّمَ حَلِفَ ذَلِكَ الرجل فَظن أَنَّ أَحَدًا لَا يَحْلِفُ بِعَظَمَةِ اللَّهِ كَاذِبًا عَلَى مَا شَاهَدَهُ مِنْهُ عِيَانًا، فَقَبِلَ عُذْرَهُ وَرَجَعَ عَلَى نَفْسِهِ فَقَالَ: آمَنْتُ بِاللَّهِ.',
  ];

  static const List<String> _p25 = [
    'ولد صلى الله عليه وسلم يوم الإثنين. والصحيح أنه ولد عام الفيل، وقد حكاه إبراهيم بن المنذر الحزامي شيخ البخاري، وخليفة بن خياط وغيرها إجماعاً.',
    'ومات أبوه وهو حمل، وقيل بعد ولادته بأشهر، وقيل بسنة، وقيل بسنتين، والمشهور الأول، واسترضع له في بني سعد، فأرضعته حليمة السعدية كما روينا ذلك بإسناد صحيح، وأقام عندها في بني سعد نحواً من أربع سنين، وشق عن فؤاده هناك، فردته إلى أمه، فخرجت به أمه إلى المدينة تزور أخواله بالمدينة، فتوفيت بالأبواء، وهي راجعة إلى مكة.',
    'فلما ماتت أمه حضنته أم أيمن وهي مولاته، ورثها من أبيه، وكفله جده عبد المطلب، فلما بلغ رسول الله صلى الله عليه وسلم من العمر ثماني سنين توفي جده، وأوصى به إلى عمه أبي طالب فكفله، وحاطه أتم حياطة، ونصره حين بعثه الله أعز نصر، مع أنه كان مستمراً على شركه إلى أن مات، فخفف الله بذلك من عذابه كما صح الحديث بذلك. وخرج به عمه إلى الشام في تجارة وهو ابن ثنتي عشرة سنة، وذلك من تمام لطفه به، لعدم من يقوم إذا تركه بمكة.',
    'وكان الله سبحانه قد صانه وحماه من صغره، وطهره من دنس الجاهلية ومن كل عيب، ومنحه كل خلق جميل حتى لم يكن يعرف بين قومه إلا بالأمين، لما شاهدوا من طهارته وصدق حديثه وأمانته.',
    'ولما أراد الله تعالى رحمة العباد، وكرامته بإرساله إلى العالمين، حبب إليه الخلاء، فكان يتحنث في غار حراء، كما كان يصنع ذلك متعبدو ذلك الزمان.',
    'ففجأه الحق وهو بغار حراء في رمضان، وله من العمر أربعون سنة، فجاءه الملك فقال له أقرأ، قال لست بقارىء، فغته حتى بلغ منه الجهد، ثم أرسله فقال له: اقرأ، قال: لست بقارئ ثلاثاً ثم قال: «ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ ۝ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ۝ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ۝ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ۝ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ». فرجع بها رسول الله صلى الله عليه وسلم ترجف بوادره، فأخبر بذلك خديجة رضي الله تعالى عنها، وقال: قد خشيت بها على عقلي، فثبتته وقالت: أبشر كلا والله لا يخزيك الله أبداً، إنك لتصل الرحم، وتصدق الحديث وتحمل الكل، وتعين على نوائب الدهر.',
    'ثم مكث رسول الله صلى الله عليه وسلم ما شاء الله أن يمكث لا يرى شيئاً، وفتر عنه الوحي. ثم تبدى له الملك بين السماء والأرض على كرسي، وثبته، وبشره بأنه رسول الله حقاً، فلما رآه رسول الله صلى الله عليه وسلم فرق منه وذهب إلى خديجة وقال: زملوني. دثروني. فأنزل الله عليه «يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ ۝ قُمۡ فَأَنذِرۡ ۝ وَرَبَّكَ فَكَبِّرۡ ۝ وَثِيَابَكَ فَطَهِّرۡ».',
    'وكانت الحال الأولى حال نبوة وإيحاء، ثم أمره الله في هذه الآية أن ينذر قومه ويدعوهم إلى الله، فشمر صلى الله عليه وسلم عن ساق التكليف، وقام في طاعة الله أتم قيام، يدعوا إلى الله سبحانه الكبير والصغير، والحر والعبد، والرجال والنساء، والأسود والأحمر، فاستجاب له عباد الله من كل قبيلة وكان حائز سبقهم أبو بكر رضي الله عنه، عبد الله بن عثمان التيمي وآزره في دين الله، ودعا معه إلى الله على بصيرة، فاستجاب لأبي بكر عثمان بن عفان، وطلحة، وسعد بن أبي وقاص.',
    'وصان الله رسوله وحماه بعمه أبي طالب، لأنه كان شريفاً مطاعاً فيهم، نبيلاً بينهم، لا يتجاسرون على مفاجأته بشيء في أمر محمد صلى الله عليه وسلم لما يعلمون من محبته له، وكان من حكمة الله بقاؤه على دينهم لما في ذلك من المصلحة، هذا رسول الله يدعو إلى الله ليلاً ونهاراً سراً وجهاراً لا يصده عن ذلك صاد ولا يرده عنه راد، ولا يأخذه في الله لومة لائم.',
    'ولما اشتد أذى المشركين على من آمن وفتنوا منهم جماعة حتى إنهم كانوا يصبرونهم، ويلقونهم في الحر، ويضعون الصخرة العظيمة على صدر أحدهم في شدة الحر، حتى إن أحدهم إذا أطلق لا يستطيع أن يجلس من شدة الألم فيقولون لأحدهم: اللاتي إلهك من دون الله. فيقول مكرهاً: نعم! وحتى إن الجعل ليمر فيقولون: وهذا إلهك من دون الله. فيقول نعم! ومر الخبيث عدو الله أبو جهل عمرو بن هشام بسمية أم عمار وهي تعذب وزوجها وابنها، فطعنها بحربة فقتلها، رضي الله عنها وعن ابنها وزوجها.',
    'فلما نقضت الصحيفة وافق موت خديجة رضي الله عنها، وموت أبي طالب، وكان بينهما ثلاثة أيام، فاشتد البلاء على رسول الله صلى الله عليه وسلم من سفهاء قومه، وأقدموا عليه، فخرج رسول الله صلى الله عليه وسلم إلى الطائف لكي يؤووه وينصروه على قومه، ويمنعوه منهم، ودعاهم إلى الله عز وجل، فلم يجيبوه إلى شيء من الذي طلب، وآذوه أذى عظيماً، لم ينل قومه منه أكثر مما نالوا منه. فرجع عنهم، ودخل مكة في جوار المطعم بن عدي بن نوفل بن عبد مناف، وجعل يدعو إلى الله عز وجل.',
    'وأسري برسول الله صلى الله عليه وسلم يجسده على الصحيح من قولي الصحابة والعلماء، من المسجد الحرام إلى بيت المقدس، راكباً البراق في صحبه جبريل عليه السلام، فنزل ثمَّ، وأم بالأنبياء ببيت المقدس فصلى بهم. ثم عرج به تلك الليلة من هناك إلى السماء الدنيا، ثم للتي تليها، ثم الثالثة، ثم إلى التي تليها، ثم الخامسة، ثم التي تليها، ثم السابعة. وفرض الله عليه الصلوات تلك الليلة.',
    'ولم يبق بمكة من المسلمين إلا رسول الله صلى الله عليه وسلم وأبو بكر وعلي رضي الله تعالى عنهما أقاما بأمره لهما، وخلا من اعتقله المشركون كرهاً، وقد أعد أبو بكر رضي الله عنه جهازه وجهاز رسول الله صلى الله عليه وسلم، منتظراً حتى يأذن الله عز وجل لرسوله صلى الله عليه وسلم في الخروج. فلما كانت ليلة هم المشركون بالفتك برسول الله صلى الله عليه وسلم، وأرصدوا على الباب أقواماً، إذا خرج عليهم قتلوه، فلما خرج عليهم لم يره منهم أحد، ثم خلص إلى بيت أبي بكر رضي الله عنه، فخرجا من خوخة في دار أبي بكر ليلاً، وقد استأجرا عبد الله بن أريقط، وكان هادياً خريتاً، ماهراً بالدلالة إلى أرض المدينة، وأمناه على ذلك مع أنه كان على دين قومه، وسلما إليه راحلتيهما، وواعداه غار ثور بعد ثلاث، فلما حصلا في الغار عمى الله على قريش خبرهما، فلم يدروا أين ذهبا.',
    'وكان عامر بن فهيرة، يريح عليهما غنماً لأبي بكر، وكانت أسماء بنت أبي بكر تحمل لهما الزاد إلى الغار، وكان عبد الله بن أبي بكر يتسمع ما يقال بمكة ثم يذهب إليهما بذلك فيحترزان منه.',
    'وجاء المشركون في طلبهما إلى ثور، وما هناك من الأماكن، حتى إنهم مروا على باب الغار، وحازت أقدامهم رسول الله صلى الله عليه وسلم وصاحبه، وعمى الله عليهم باب الغار، وذلك تأويل قوله تعالى «إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ» وذلك أن أبا بكر رضي الله تعالى عنه لشدة حرصه بكى حين مر المشركون، وقال: يا رسول الله، لو أن أحدهم نظر موضع قدميه لرآنا، فقال له النبي صلى الله عليه وسلم: “يا أبا بكر، ما ظنك باثنين الله ثالثهما؟”.',
    'ولما كان بعد الثلاث أتى ابن أريقط بالراحلتين فركباهما، وأردف أبو بكر عامر بن فهيرة وسار الديلي أمامهما على راحلته. وجعلت قريش لمن جاء بواحد من محمد صلى الله عليه وسلم وأبي بكر رضي الله عنه مائةً من الإبل، فلما مروا بحي مدلج، بصر بهم سراقة بن مالك بن جعشم، سيد مدلج، فركب جواده وسار في طلبهم، فلما قرب منهم سمع قراءة النبي صلى الله عليه وسلم، وأبو بكر رضي الله عنه يكثر الالتفات حذراً على رسول الله صلى الله عليه وسلم، وهو صلى الله عليه وسلم لا يلتفت، فقال أبو بكر: يا رسول الله هذا سراقة بن مالك قد رهقنا. فدعا عليه رسول الله صلى الله عليه وسلم فساخت يدا فرسه في الأرض فقال: رميت، إن الذي أصابني بدعائكما، فادعوا الله لي، ولكما علي أن أرد الناس عنكما، فدعا له رسول الله صلى الله عليه وسلم فأطلق، وسأل رسول الله صلى الله عليه وسلم أن يكتب له كتاباً، فكتب له أبو بكر في أدم، ورجع يقول للناس: قد كفيتم ما ههنا.',
    'وقد كان بلغ الأنصار مخرجه من مكة وقصده إياهم، فكانوا كل يوم يخرجون إلى الحرة ينتظرونه، فلما كان يوم الاثنين الثاني عشر من ربيع الأول على رأس ثلاث عشرة سنة من نبوته صلى الله عليه وسلم وافاهم رسول الله صلى الله عليه وسلم حين اشتد الضحى، وكان قد خرج الأنصار يومئذ، فلما طال عليهم رجعوا إلى بيوتهم، وكان أول من بصر به رجل من اليهود ـ وكان على سطح أطمه ـ فنادى بأعلى صوته: يا بني قيلة هذا جدكم الذي تنتظرون! فخرج الأنصار في سلاحهم وحيوه بتحية النبوة. ونزل رسول الله صلى الله عليه وسلم بقباء على كلثوم بن الهدم، وقيل: بل على سعد بن خيثمة، وجاء المسلمون يسلمون على رسول الله صلى الله عليه وسلم، وأكثرهم لم يره بعد، وكان بعضهم أو أكثرهم يظنه أبا بكر لكثرة شيبه، فلما اشتد الحر قام أبو بكر بثوب يظلل على رسول الله صلى الله عليه وسلم فتحقق الناس حينئذ رسول الله عليه الصلاة والسلام.',
    'فأقام رسول الله صلى الله عليه وسلم بقباء أياماً، وقيل: أربعة عشر يوماً، وأسس مسجد قباء ثم ركب بأمر الله تعالى فأدركته الجمعة في بني سالم بن عوف فصلاها في المسجد الذي في بطن الوادي رانوناً، ورغب إليه أهل تلك الدار أن ينزل عليهم فقال: “دعوها فإنها مأمورة” فلم تزل ناقته سائرة به لا تمر بدار من دور الأنصار إلا رغبوا إليه في النزول عليهم، فيقول: “دعوها فإنها مأمورة”. فلما جاءت موضع مسجده اليوم بركت، ولم ينزل عنها صلى الله عليه وسلم حتى نهضت وسارت قليلاً ثم التفتت ورجعت فبركت في موضعها الأول، فنزل عنها صلى الله عليه وسلم، وذلك في دار بني النجار، فحمل أبو أيوب رضي الله عنه رحل رسول الله صلى الله عليه وسلم إلى منزله. واشترى رسول الله صلى الله عليه وسلم موضع المسجد، وكان مربداً ليتيمين، وبناه مسجداً، فهو مسجده الآن، وبني لآل رسول الله صلى الله عليه وسلم حجراً إلى جانبه.',
    'وآخى رسول الله صلى الله عليه وسلم بين المهاجرين والأنصار، فكانوا يتوارثون بهذا الإخاء في ابتداء الإسلام إرثاً مقدماً على القرابة.',
    'غزوة بدر، وهي الوقعة العظيمة التي فرق الله فيها بين الحق والباطل وأعز الإسلام، ودمغ الكفر وأهله، وذلك أنه لما كان في رمضان من هذه السنة الثانية بلغ رسول الله صلى الله عليه وسلم أن عيراً مقبلة من الشام صحبة أبي سفيان، صخر بن حرب، في ثلاثين أو أربعين رجلاً من قريش وهي عير عظيمة، تحمل أموالاً جزيلة لقريش، فندب صلى الله عليه وسلم الناس للخروج إليها، وأمر من كان ظهره حاضراً بالنهوض، ولم يحتفل لها احتفالاً كثيراً، إلا أنه خرج في ثلاثمائة وبضعة عشر رجلاً، لثمان خلون من رمضان. ورسول الله صلى الله عليه وسلم يقول: “اللهم إن تهلك هذه العصابة لا تعبد في الأرض” فذلك قوله تعالى «إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُرۡدِفِينَ» ثم أغفى رسول الله صلى الله عليه وسلم إغفاءةً، ثم رفع رأسه وهو يقول: “أبشر يا أبا بكر، هذا جبريل على ثناياه النقع”. ومنح الله المسلمين أكتاف المشركين، فكان أول من فر منهم خالد بن الأعلم فأدرك فأسر، وتبعهم المسلمون في آثارهم، يقتلون ويأسرون، فقتلوا منهم سبعين وأسروا سبعين، وأخذوا غنائمهم.',
    'واستشار رسول الله صلى الله عليه وسلم أصحابه: أيخرج إليهم أم يمكث في المدينة؟ فبادر جماعة من فضلاء الصحابة ممن فاته الخروج يوم بدر إلى الإشارة بالخروج إليهم، وألحوا عليه صلى الله عليه وسلم في ذلك، وأشار عبد الله بن أبي بن سلول بالمقام بالمدينة، وتابعه على ذلك بعض الصحابة، فألح أولئك على رسول الله صلى الله عليه وسلم، فنهض ودخل بيته ولبس لأمته وخرج عليهم، وقد انثنى عزم أولئك فقالوا: يا رسول الله، إن أحببت أن تمكث في المدينة فافعل. فقال: “ما ينبغي لنبي إذا لبس لأمته أن يضعها حتى يقاتل” وأتي عليه الصلاة والسلام برجل من بني النجار فصلى عليه، وذلك يوم الجمعة، واستخلف على المدينة ابن أم مكتوم. واستقل رسول الله صلى الله عليه وسلم بمن بقي معه حتى نزل شعب أحد في عدوة الوادي إلى الجبل، فجعل ظهره إلى أحد، ونهى الناس عن القتال حتى يأمرهم، فلما أصبح تعبأ عليه الصلاة والسلام للقتال في أصحابه، وكان فيهم خمسون فارساً، واستعمل على الرماة ـ وكانوا خمسين ـ عبد الله بن جبير الأوسي، وأمره وأصحابه أن لا يتغيروا من مكانهم، وأن يحفظوا ظهور المسلمين أن يؤتوا من قبلهم. وكانت الدولة أول النهار للمسلمين على الكفار، فانهزموا راجعين حتى وصلوا إلى نسائهم. فلما رأى ذلك أصحاب عبد الله بن جبير قالوا: يا قوم، الغنيمة الغنيمة. فذكرهم عبد الله بن جبير تقديم رسول الله صلى الله عليه وسلم إليه في ذلك، فظنوا أن ليس للمشركين رجعة، وأنهم لا تقوم لهم قائمة بعد ذلك، فذهبوا في طلب الغنيمة، وكر الفرسان من المشركين فوجدوا تلك الفرجة قد خلت من الرماة فجاوزوها وتمكنوا، وأقبل آخرهم، فكان ما أراد الله تعالى كونه، فاستشهد من أكرمهم الله بالشهادة من المؤمنين، فقتل جماعة من أفاضل الصحابة، وتولى أكثرهم.',
    'وخلص المشركون إلى رسول الله صلى الله عليه وسلم فجرح في وجهه الكريم وكسرت رباعيته اليمنى السفلى بحجر، وهشمت البيضة على رأسه المقدس، ورشقه المشركون بالحجارة حتى وقع لشقه، وسقط في حفرة من الحفر التي كان أبو عامر الفاسق حفرها يكيد بها المسلمين، فأخذ علي بيده، واحتضنه طلحة بن عبيد الله. وصرخ الشيطان ـ لعنه الله ـ بأعلى صوته: إن محمداً قد قتل، ووقع ذلك في قلوب كثير من المسلمين، وتولى أكثرهم، وكان أمر الله. وأقبل رسول الله صلى الله عليه وسلم نحو المسلمين، فكان أول من عرفه تحت المغفر كعب بن مالك رضي الله عنه، فصاح بأعلى صوته: يا معشر المسلمين، أبشروا، هذا رسول الله صلى الله عليه وسلم! فأشار إليه صلى الله عليه وسلم أن اسكت، واجتمع إليه المسلمون، ونهضوا معه إلى الشعب الذي نزل فيه، فيهم أبو بكر وعمر وعلي والحارث بن الصمة الأنصاري وغيرهم. واستشهد يومئذ من المسلمين نحو السبعين.',
    'وفر يومئذ من المسلمين جماعة من الأعيان، منهم عثمان بن عفان رضي الله عنه، وقد نص الله سبحانه على العفو عنهم، فقال عز وجل: «إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ».',
    'غزوة الخندق التي ابتلى الله فيها عباده المؤمنين وزلزلهم، وثبت الإيمان في قلوب أوليائه وأظهر ما كان يبطنه أهل النفاق، وفضحهم وقرعهم. ثم أنزل نصره، ونصر عبده، وهزم الأحزاب وحده، وأعز جنده، ورد الكفرة بغيظهم، ووقى المؤمنين شر كيدهم، وذلك بفضله ومنه.',
    'فلما سمع رسول الله صلى الله عليه وسلم بمسيرهم إليه أمر المسلمين بحفر خندق يحول بين المشركين وبين المدينة، وكان ذلك بإشارة سلمان الفارسي رضي الله عنه، فعمل المسلمون فيه مبادرين هجوم الكفار عليهم. وخرج رسول الله صلى الله عليه وسلم فتحصن بالخندق وهو في ثلاثة آلاف على الصحيح من أهل المدينة. وثبت المشركون محاصرين رسول الله صلى الله عليه وسلم شهراً، ولم يكن بينهم قتال لأجل ما حال الله به من الخندق بينه وبينهم.',
    'وأرسل الله عز وجل على قريش ومن معهم الخور والريح تزلزلهم، فجعلوا لا يقر لهم قرار، ولا تثبت لهم خيمة ولا طنب، ولا قدر ولا شيء. فلما رأوا ذلك ترحلوا من ليلتهم تلك. وأرسل صلى الله عليه وسلم حديفة بن اليمان يخبر له خبرهم، فوجدهم كما وصفنا، ورأى أبا سفيان يصلي ظهره بنار، ولو شاء حذيفة لقتله، ثم رجع إلى رسول الله صلى الله عليه وسلم ليلاً فأخبره برحيلهم.',
    'ولما كان ذو القعدة من السنة السادسة خرج رسول الله صلى الله عليه وسلم معتمراً في ألف ونيف. فلما علم المشركون بذلك جمعوا أحابيشهم وخرجوا من مكة صادين له عن الاعتمار هذا العام، وقدموا على خيل لهم خالد بن الوليد إلى كراع الغميم. وخالفه صلى الله عليه وسلم في الطريق فانتهى صلى الله عليه وسلم إلى الحديبية، وتراسل هو والمشركون حتى جاء سهيل بن عمرو فصالحه على أن يرجع عنهم عامهم هذا وأن يعتمر من العام المقبل، فأجابه صلى الله عليه وسلم إلى ما سأل، لما جعل الله عز وجل في ذلك من المصلحة والبركة. وعلى أن يأمن الناس بينهم وبينه عشر سنين. فكانت هذه الهدنة من أكبر الفتوحات للمسلمين كما قال عبد الله مسعود رضي الله عنه.',
    'ولم يرجع عثمان رضي الله عنه، حتى بلغه صلى الله عليه وسلم أنه قد قتل عثمان، فحمي لذلك رسول الله صلى الله عليه وسلم ثم دعا أصحابه إلى البيعة على القتال، فبايعوه تحت شجرة هناك، وكانت سمرة. وأنزل الله عز وجل في ذلك: «لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ» فهذه هي بيعة الرضوان.',
    'غزوة فتح مكة التي أكرم الله عز وجل بها رسوله، وأقر عينه بها، وجعلها علما ظاهراً على إعلاء كلمته وإكمال دينه والاعتناء بنصرته. ودخل رسول الله صلى الله عليه وسلم مكة وهو راكب على ناقته وعلى رأسه المغفر، ورأسه يكاد يمس مقدمة الرحل من تواضعه لربه عز وجل.',
    'ودعا بالمفتاح، فدخل البيت وأمر بإلقاء الصور ومحوها منه، وأذن بلال يومئذ على ظهر الكعبة، ثم رد صلى الله عليه وسلم المفتاح إلى عثمان بن طلحة بن أبي طلحة. وأقرهم على السدانة. وكان الفتح لعشر بقين من رمضان.',
    'صلى رسول الله صلى الله عليه وسلم الظهر يوم الخميس لست بقين من ذي القعدة من سنة عشر بالمدينة، ثم خرج منها بمن معه من المسلمين من أهل المدينة ومن تجمع من الأعراب، فصلى العصر بذي الحليفة ركعتين، وبات بها. ثم خرج صلى الله عليه وسلم إلى منى فبات بها وكانت ليلة الجمعة التاسع من ذي الحجة. ثم أصبح فسار إلى عرفة وخطب تحت سمرة خطبة عظيمة، شهدها من أصحابه نحو من أربعين ألفاً رضي الله عنهم أجمعين، وجمع بين الظهر والعصر ثم وقف بعرفة. ثم بات بالمزدلقة، وجمع بين المغرب والعشاء ليلتئذ، ثم أصبح فصلى الفجر في أول وقتها. ثم سار قبل طلوع الشمس إلى منى، فرمى جمرة العقبة، ونحر، وحلق.',
    'وخطب ثاني يوم النحر خطبة عظيمة أيضاً، ووصى وحذر وأنذر. وأشهدهم على أنفسهم أنه بلغ الرسالة. فنحن نشهد أنه بلغ الرسالة، وأدى الأمانة، ونصح الأمة صلى الله عليه وسلم تسليماً كثيراً دائماً إلى يوم الدين.',
    'ثم أقبل صلى الله عليه وسلم منصرفاً إلى المدينة، وقد أكمل الله له دينه. فأقام بها بقية ذي الحجة والمحرم وصفر، ثم ابتدأ به صلى الله عليه وسلم وجعه في بيت ميمونة يوم خميس، وكان وجعاً في رأسه الكريم، وكان أكثر ما يعتريه الصداع عليه الصلاة والسلام، فجعل مع هذا يدور على نسائه حتى شق عليه، فاستأذنهن أن يمرض في بيت عائشة رضي الله عنها، فأذن له، فمكث وجعا اثني عشر يوماً. والصديق رضي الله عنه يصلي بالناس بنصه صلى الله عليه وسلم عليه، واستثنائه له من جيش أسامة الذي كان قد جهزه صلى الله عليه وسلم إلى الشام لغزو الروم. وقبض صلى الله عليه وسلم ضحى يوم الإثنين من ربيع الأول.',
  ];

