      brief: 'أرسل الله هودًا إلى عاد، وكانوا أول من عبد الأصنام بعد الطوفان، فدعاهم إلى التوحيد فكذّبوه فأهلكهم الله بريح عاتية.',
      lessons: [
        'القوة لا تغني عن الله: اغتر قوم عاد ببنيانهم وبطشهم فأهلكتهم ريح.',
        'التوكل على الله: قال «إني توكلت على الله ربي وربكم».',
        'شكر النعم: ذكّرهم بأن الله جعلهم خلفاء من بعد قوم نوح وزادهم في الخلق بسطة.',
      ],
    ),
    '5': (
      title: 'نبي ثمود وقصة الناقة',
      brief: 'أرسل الله صالحًا إلى ثمود، فكانت الناقة آية لهم، فعقروها وتحدّوا أمر الله، فأخذتهم الصيحة.',
      lessons: [
        'خطر التكذيب بالآيات: عقروا الناقة واستعجلوا العذاب فنزل بهم.',
        'استعجال الشر: قالوا «ائتنا بما تعدنا» فجمعوا بين الكفر والاستخفاف.',
        'النصح ولو لم يُقبل: قال لهم «لقد أبلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين».',
      ],
    ),
    '6': (
      title: 'خليل الله وأبو الأنبياء',
      brief: 'دعا إبراهيم قومه إلى عبادة الله وكسّر أصنامهم، فألقوه في النار فجعلها الله بردًا وسلامًا، ثم هاجر وأسكن هاجر وإسماعيل عند البيت.',
      lessons: [
        'البرهان على بطلان الأصنام: كسّرها فلم تدفع عن نفسها، وأقرّوا أنها لا تنطق.',
        'التوكل عند الشدة: قال وهو يُلقى في النار «حسبنا الله ونعم الوكيل».',
        'الثقة بالله: قالت هاجر لما علمت أنه أمر الله «إذًا لا يضيعنا».',
      ],
    ),
    '7': (
      title: 'النبي الصابر المبتلى بقومه',
      brief: 'دعا لوط قومه إلى التوحيد وإلى ترك الفاحشة التي لم يسبقهم بها أحد، فأخرجوه فنجّاه الله وأهله إلا امرأته وأهلك قومه.',
      lessons: [
        'النصح أمام الإصرار: دعاهم فلم يستجب منهم أحد ولم يرعووا عن غيّهم.',
        'قلب الحق عند المعاندين: جعلوا غاية المدح ذمًّا فقالوا «إنهم أناس يتطهرون».',
        'النجاة للمؤمنين: نجّاه الله وأهله إلا امرأته كانت من الغابرين.',
      ],
    ),
    '8': (
      title: 'الصادق الوعد وباني البيت',
      brief: 'نبي رسول أثنى الله عليه بصدق الوعد، أرسله إلى قبائل جرهم والعمالقة وأهل اليمن.',
      lessons: [
        'الصدق في الوعد: وصفه الله بأنه كان صادق الوعد.',
        'الأمر بالصلاة والزكاة في الأهل: كان يأمر أهله بهما.',
        'الرضا عند الله: وكان عند ربه مرضيًّا.',
      ],
    ),
    '9': (
      title: 'النبي المبارك وجد بني إسرائيل',
      brief: 'بشّر الله به إبراهيم وسارة نبيًّا من الصالحين وبارك عليه وعلى ذريته.',
      lessons: [
        'البشارة بعد اليأس: بُشّرت به سارة وعمرها تسعون سنة.',
        'البركة في الذرية: «وباركنا عليه وعلى إسحاق».',
        'شرف البيت النبوي: وصف النبي ﷺ يوسف بأنه الكريم ابن الكريم ابن الكريم ابن الكريم.',
      ],
    ),
    '10': (
      title: 'إسرائيل وصاحب الصبر الجميل',
      brief: 'نبي كريم ابن نبي، وصّى بنيه بالتوحيد، وصبر على فقد يوسف وأخيه صبرًا جميلًا حتى جمع الله شمله بهم.',
      lessons: [
        'الوصية بالتوحيد: سأل بنيه عند الموت «ما تعبدون من بعدي؟».',
        'الصبر الجميل: قال «فصبر جميل والله المستعان».',
        'الأمل برحمة الله: قال «ولا تيأسوا من روح الله».',
      ],
    ),
    '11': (
      title: 'الصدّيق وعزيز مصر',
      brief: 'قصة يوسف عليه السلام من رؤياه وكيد إخوته، إلى الجب والسجن والتمكين، ثم لقاء أبويه وإخوته.',
      lessons: [
        'العفة والتقوى: قال «معاذ الله إنه ربي أحسن مثواي» فصرف الله عنه السوء.',
        'العفو عند المقدرة: قال لإخوته «لا تثريب عليكم اليوم يغفر الله لكم».',
        'الصبر والتقوى سبيل التمكين: «إنه من يتق ويصبر فإن الله لا يضيع أجر المحسنين».',
      ],
    ),
    '12': (
      title: 'نبي الصبر والاحتساب',
      brief: 'ابتُلي أيوب في ماله وجسده وأهله فصبر واحتسب، ثم كشف الله ضره ورزقه أهله ومثلهم معهم رحمة منه.',
      lessons: [
        'الصبر على البلاء: بقي صابرًا محتسبًا ذاكرًا لله ليله ونهاره.',
        'اللجوء إلى الله بالدعاء: «أني مسني الضر وأنت أرحم الراحمين».',
        'القدوة لأهل البلاء: «وذكرى للعابدين»، وفي صبر زوجته أسوة كذلك.',
      ],
    ),
    '13': (
      title: 'خطيب الأنبياء وداعي العدل',
      brief: 'أرسل الله شعيبًا إلى أهل مدين، وكانوا يبخسون المكيال والميزان ويقطعون السبيل، فكذّبوه فأخذتهم الصيحة.',
      lessons: [
        'العدل في المعاملة: أمرهم بإيفاء الكيل والميزان ونهاهم عن بخس الناس.',
        'القدوة في الدعوة: قال «وما أريد أن أخالفكم إلى ما أنهاكم عنه».',
        'الثبات على الدين: رفض العودة إلى ملتهم وقال «وما توفيقي إلا بالله».',
      ],
    ),
    '14': (
      title: 'كليم الله وهادم الطغيان',
      brief: 'وُلد موسى في زمن فرعون الذي كان يذبح الأبناء، فحفظه الله، ثم كلّمه وأرسله إلى فرعون، فنجّاه الله وبني إسرائيل وأغرق فرعون.',
      lessons: [
        'حفظ الله لأوليائه: ألقته أمه في اليمّ فرده الله إليها.',
        'اليقين عند الشدة: قال عند البحر «كلا إن معي ربي سيهدين».',
        'التكبر عاقبته الهلاك: آمن فرعون حين لا ينفع الإيمان.',
      ],
    ),
    '15': (
      title: 'الوزير المعين واللسان الفصيح',
      brief: 'سأل موسى ربه أن يجعل أخاه هارون وزيرًا له، فأجابه الله ووهبه له نبيًّا.',
      lessons: [
        'عون الأخ لأخيه: سأل موسى أن يُشرك أخاه في أمره.',
        'النصح عند الفتنة: قال لقومه «إنما فتنتم به وإن ربكم الرحمن».',
        'منزلة الشفاعة: قال تعالى «ووهبنا له من رحمتنا أخاه هارون نبيًّا».',
      ],
    ),
    '16': (
      title: 'من الصابرين الأخيار',
      brief: 'ذكره الله مع الأنبياء ووصفه بالصبر والخير، واختلف العلماء: هل كان نبيًّا أم رجلًا صالحًا؟',
      lessons: [
        'الصبر: ذكره الله مع الصابرين.',
        'العدل في الحكم: قيل إنه سُمّي بذلك لأنه تكفّل لقومه أن يقضي بينهم بالعدل.',
      ],
    ),
    '17': (
      title: 'الملك العابد وصاحب الزبور',
      brief: 'آتاه الله ملكًا وحكمة وألان له الحديد وسخّر معه الجبال والطير، وكان كثير العبادة والإنابة.',
      lessons: [
        'العمل باليد: كان يأكل من كسب يده.',
        'العبادة والقوة فيها: أحب الصلاة إلى الله صلاة داود وأحب الصيام صيامه.',
        'الإنابة: «فاستغفر ربه وخرّ راكعًا وأناب».',
      ],
    ),
    '18': (
      title: 'الملك الذي سُخّر له الكون',
      brief: 'ورث سليمان داود ملكه وحكمته، وسخّر الله له الجن والإنس والطير والريح، وكانت قصته مع الهدهد وملكة سبأ.',
      lessons: [
        'شكر النعمة: قال «هذا من فضل ربي ليبلوني أأشكر أم أكفر».',
        'الحكمة في القضاء: حكم بين المرأتين فعرف الأم الحقيقية.',
        'الدعوة إلى التوحيد: دعا ملكة سبأ بعد أن علم أنهم يسجدون للشمس من دون الله.',
      ],
    ),
    '19': (
      title: 'الداعي إلى التوحيد',
      brief: 'أرسل الله إلياس إلى قوم يدعون بعلًا ويتركون أحسن الخالقين، فكذّبوه.',
      lessons: [
        'الدعوة إلى التوحيد: قال «أتدعون بعلًا وتذرون أحسن الخالقين».',
        'عاقبة التكذيب: «فكذبوه فإنهم لمحضرون».',
        'سلام الله على المحسنين: «سلام على إل ياسين».',
      ],
    ),
    '20': (
      title: 'من الأخيار',
      brief: 'ذكره الله في القرآن مع الأنبياء وبيّن فضله.',
      lessons: [
        'فضل الأنبياء: ذكره الله ممن فضّلهم على العالمين.',
        'الخيرية: وصفه الله بأنه من الأخيار.',
      ],
    ),
    '21': (
      title: 'صاحب الحوت ونبي الرحمة',
      brief: 'أرسل الله يونس إلى أهل نينوى، فآمنوا فكشف الله عنهم العذاب، وخرج هو مغاضبًا فالتقمه الحوت ثم نجّاه.',
      lessons: [
        'قبول التوبة قبل فوات الأوان: لم تنفع قريةً إيمانُها إلا قوم يونس.',
        'التسبيح في الكرب: «لا إله إلا أنت سبحانك إني كنت من الظالمين».',
        'استجابة دعوة ذي النون: لم يدعُ بها مسلم ربه في شيء إلا استجاب له.',
      ],
    ),
    '22': (
      title: 'نبي المحراب وكافل مريم',
      brief: 'نادى زكريا ربه نداءً خفيًّا يسأله ولدًا، فبشّره الله بيحيى مع كِبر سنه وعقم امرأته.',
      lessons: [
        'الدعاء الخفي: «إذ نادى ربه نداء خفيًّا».',
        'قدرة الله لا حدّ لها: «كذلك قال ربك هو عليَّ هيّن».',
        'الذكر والتسبيح: أُمر بكثرة الذكر والتسبيح بالعشي والإبكار.',
      ],
    ),
    '23': (
      title: 'النبي الزاهد والسيد الحصور',
      brief: 'بشّر الله به زكريا، وآتاه الحكم صبيًّا، ووصفه بالتقوى والبر بوالديه.',
      lessons: [
        'القوة في الأخذ بالكتاب: «يا يحيى خذ الكتاب بقوة».',
        'البر بالوالدين: «وبرًّا بوالديه ولم يكن جبارًا عصيًّا».',
        'السلام في المواطن الثلاثة: يوم وُلد ويوم يموت ويوم يُبعث حيًّا.',
      ],
    ),
    '24': (
      title: 'المسيح وكلمة الله',
      brief: 'عيسى ابن مريم عبد الله ورسوله، أيّده الله بروح القدس، ورفعه إليه ولم يقتلوه ولم يصلبوه، وسينزل في آخر الزمان.',
      lessons: [
        'عبد الله ورسوله: «ما المسيح ابن مريم إلا رسول قد خلت من قبله الرسل».',
        'حفظ الله لرسله: «وما قتلوه وما صلبوه ولكن شُبّه لهم».',
        'نزوله في آخر الزمان: يكسر الصليب ولا يقبل إلا الإسلام.',
      ],
    ),
    '25': (
      title: 'خاتم الأنبياء ورحمة الله للعالمين',
      brief: 'سيرة نبينا محمد ﷺ من مولده ونشأته إلى بعثته وهجرته ثم غزواته وفتح مكة وحجة الوداع ووفاته.',
      lessons: [
        'الأمانة قبل البعثة: عُرف بين قومه بالأمين.',
        'الصبر على الأذى في الدعوة: خرج إلى الطائف فآذوه، ثم عاد يدعو إلى الله.',
        'اليقين بالله في الشدة: قال لأبي بكر في الغار «ما ظنك باثنين الله ثالثهما؟».',
      ],
    ),
  };

  static ProphetStory apply(ProphetStory p) {
    final sourced = _sourced(p);
    final meta = _meta[p.id];
    if (meta == null) return sourced;
    return sourced.copyWith(
      title: meta.title,
      brief: meta.brief,
      lessons: meta.lessons,
    );
  }

